is
begin
if swhox=1 then
          if oper = 1 then  Update hoxsw_proper set sw_in_dir=V_value;
          end if;
          if oper = 2 then  Update hoxsw_proper set sw_out_dir=V_value;
          end if;
          commit;
end if;  
--
if swhox = 2 then

          if oper = 1 then  Update hoxsw_proper set hox_in_dir=V_value;
          end if;
          if oper = 2 then  Update hoxsw_proper set hox_out_dir=V_value;
          end if;
          if oper = 3 then  Update hoxsw_proper set hox_archive_dir=V_value;
          end if;
          commit;

end if;
end;
--ADD TO HOXSWACCOUNT ----------------------------------------------------------

PROCEDURE addto_hoxswaccount (oper integer,v_valute integer,V_value integer)
is val_exists integer;
begin
   select count(*) into val_exists from hoxsw_account where valute = v_valute;
   if oper = 1 then    
       if val_exists > 0 then
          update hoxsw_account set swift_id=v_value where valute = v_valute;
       else
          insert into hoxsw_account (swift_id,valute) values (v_value,v_valute);
       end if;    
   end if;
   if oper = 2 then    
      if val_exists > 0 then
          update hoxsw_account set hox_id=v_value where valute = v_valute;
      else
          insert into hoxsw_account (hox_id,valute) values (v_value,v_valute);
      end if;   
   end if;    
end;
