function CheckForFile(V_ID integer,V_STATUS integer) return integer
is result integer;
   notestiq integer;
   messcount integer;
   GlobalTestiq Integer; 
   BankDate date :=  sbop.get_date;

begin
   select  count(*) into notestiq 
   from    hoxmessage_out 
   where   (not(status =v_status))and(mt102_id=V_id) ;
   
   select  count(*) into Globaltestiq 
   from    hoxmessage_out 
   where   (TRANSACTION_ID not in (select id from provarch where dat=BankDate))and
           (mt102_id=V_id); 
           
   if (notestiq=0)and(GlobalTestiq=0) then
       result := 1;
   else
       result := 0;
   end if;
   return result;
end;

---------
procedure ToandNo_send(V_ID integer,to_no integer,allsend integer)
is maxamount number(22,2);
   messMax  number(22,2);
begin
select hoxamount_limit into maxamount from hoxsw_proper;
select max(amount) into messmax from hoxmessage_out where mt102_id=v_id;

if allsend=0 then 
  if (to_no = 1)and(maxamount>=messmax) then 
     update hox102_out set send =1 where (id = v_id)and(amount<=maxamount);
  else
     update hox102_out set send =0 where id = v_id;
  end if;
end if;  
if allsend=1 then
  if to_no=1 then
    update hox102_out set send =1
    where 
        ((send is null)or(send=0))and
        (status=1)and(CheckForFile(id,1) =1)and(amount<=maxamount);
  else      
    update hox102_out set send =0
    where 
        (send=1)and
        (status=1)and(CheckForFile(id,1) =1);
  end if;  
end if;
commit;
end;
