Function AddProvarch(Flag number) return number is
result number;
FlagStr varchar(16);
ToDay date;
Yesterday date;
v_Shifr number;
begin
if flag=1 then
FlagStr:=' RateDiff ';
else
FlagStr:=' Profit ';
end if;
dbms_output.put_line(' AddProvarch '||FlagStr|| to_char(rProvarch.id));

select tek_dat, pred_dat into ToDay, YesterDay from sysdat;
If rProvarch.dat=ToDay then
rProvarch.shifr:=3;
elsif rProvarch.dat=YesterDay then
 rProvarch.shifr:=2;  
 else
 rProvarch.shifr:=0;
end if;

insert into provarch 
(
  id
, op_id
, no_prov
, dat
, debt
, kredit
, val_acc
, vid_op
, ammount
, lammount
, tim
, shifr
, no_pack
, kassa_b
, kassa_z
, no_filial
, sloj_prov
, bank_d
, bank_k
, no_doc
, no_mem
, d1
, k1
, rate_d
, rate_c
, parentid
, currencyid_c
, ammount_c
, name)
values
(
  rProvarch.id
, rProvarch.op_id
, rProvarch.no_prov
, rProvarch.dat
, rProvarch.debt
, rProvarch.kredit
, rProvarch.val_acc
, rProvarch.vid_op
, rProvarch.ammount
, rProvarch.lammount
, rProvarch.tim
, rProvarch.shifr
, rProvarch.no_pack
, rProvarch.kassa_b
, rProvarch.kassa_z
, rProvarch.no_filial
, rProvarch.sloj_prov
, rProvarch.bank_d
, rProvarch.bank_k
, null --rProvarch.no_doc
, rProvarch.no_mem
, rProvarch.d1
, rProvarch.k1
, rProvarch.rate_d
, rProvarch.rate_c
, rProvarch.parentid
, rProvarch.currencyid_c
, rProvarch.ammount_c
, rProvarch.name
)	returning ID into Result;
return result;
end;
------------------------------------
Procedure AddTurnover is
begin
-- dbms_output.put_line('AddTornover');
-- Update debit account's balance 
update archost set
	obr_d = obr_d + DebitAmount, 
	pok_obr_d =	pok_obr_d + rProvarch.lammount 
		where
			(acc_id = rProvarch.debt)
			and (datdate = rProvarch.dat);  
-- Update credit account's balance 
		update archost set
			obr_k = obr_k + CreditAmount, 
			pok_obr_k = pok_obr_k + rProvarch.lammount 
		where
			(acc_id = rProvarch.kredit)
			and (datdate = rProvarch.dat);
end;
------------------------------------
Procedure AddRest is
begin
-- dbms_output.put_line('AddRest ');
-- Update debit account's balance */
update archost set
	ostat = ostat - DebitAmount, 
	pok_ostat =	pok_ostat - rProvarch.lammount 
		where
			(acc_id = rProvarch.debt)
			and (datdate >= rProvarch.dat);  
-- Update credit account's balance 
		update archost set
			ostat = ostat + CreditAmount, 
			pok_ostat = pok_ostat + rProvarch.lammount
		where
			(acc_id = rProvarch.kredit)
			and (datdate >= rProvarch.dat);
end;
------------------------------------
Procedure DelProvarch is
begin
 -- dbms_output.put_line('Transaction Id='||to_char(rprovarch.id)||' will be deleletet');
 delete from Provarch where id=rProvarch.id; 
end;
------------------------------------
Procedure DelRest	is
begin
-- dbms_output.put_line('DelRest ');
-- Update debit account's balance */
update archost set
	 ostat = ostat + DebitAmount
	,pok_ostat =	pok_ostat + rProvarch.lammount 
		where
			(acc_id = rProvarch.debt)	and (datdate >= rProvarch.dat);  
-- Update credit account's balance 
		update archost set
			 ostat = ostat - CreditAmount 
			,pok_ostat = pok_ostat - rProvarch.lammount
		where
			(acc_id = rProvarch.kredit)
			and (datdate >= rProvarch.dat);
end;
------------------------------------	
Procedure DelTurnOver is
begin
update archost set
	 obr_d = obr_d - DebitAmount()
	,pok_obr_d =	pok_obr_d - rProvarch.lammount 
		where
			(acc_id = rProvarch.debt)
			and (datdate = rProvarch.dat);  
-- Update credit account's balance 
		update archost set
			 obr_k = obr_k - CreditAmount() 
			,pok_obr_k = pok_obr_k - rProvarch.lammount 
		where
			(acc_id = rProvarch.kredit)
			and (datdate = rProvarch.dat);
end;
