			Result := rProvarch.ammount_c;
		else
			Result :=rProvarch.Lammount;
--				rProvarch.ammount  
--		  *	GetRate(rProvarch.val_acc, rProvarch.dat)
--				/ GetRate(rProvarch.currencyid_c, rProvarch.dat);
		end if;
		return Result;
	end;
