	Function DebitAmount	return number is
		Result number:=1;
	begin
		if (rProvarch.val_acc <> 0) or (rProvarch.currencyid_c = 0) then
			Result := rProvarch.ammount;
		else
			Result :=rProvarch.Lammount;
--				rProvarch.ammount_c 
