Procedure AddTempRepairTrans is
begin
 dbms_output.put_line('AddTempRepairTrans ' ||to_Char(rProvarch.id));
insert into TempRepairTrans 
(
  id
, op_id
, no_prov
, dat
, debt
, kredit
, val_acc
, vid_op
, ammount
, lammount
, tim
, shifr
, no_pack
, kassa_b
, kassa_z
, no_filial
, sloj_prov
, bank_d
, bank_k
, no_doc
, no_mem
, d1
, k1
, rate_d
, rate_c
, parentid
, currencyid_c
, ammount_c
, name)
values
(
  rProvarch.id
, rProvarch.op_id
, rProvarch.no_prov
, rProvarch.dat
, rProvarch.debt
, rProvarch.kredit
, rProvarch.val_acc
, rProvarch.vid_op
, rProvarch.ammount
, rProvarch.lammount
, rProvarch.tim
, rProvarch.shifr
, rProvarch.no_pack
, rProvarch.kassa_b
, rProvarch.kassa_z
, rProvarch.no_filial
, rProvarch.sloj_prov
, rProvarch.bank_d
, rProvarch.bank_k
, rProvarch.no_doc
, rProvarch.no_mem
, rProvarch.d1
, rProvarch.k1
, rProvarch.rate_d
, rProvarch.rate_c
, rProvarch.parentid
, rProvarch.currencyid_c
, rProvarch.ammount_c
, rProvarch.name
);
end;
