procedure DelCursor(str varchar2) as
cProvarch DynCursor;
begin
 open cProvarch for str; 
 LOOP
  FETCH cProvarch INTO rProvarch;
  EXIT WHEN cProvarch%NOTFOUND;
   DelTurnOver;
   DelRest;
   DelProvarch;
 END LOOP;
 CLOSE cProvarch;
end;
