strsql:='Select open_dat from  account where acc_id=' || TO_CHAR(v_id);
open maxDate for strsql; 
LOOP
 FETCH maxDate INTO OptDate;
  EXIT WHEN maxDate%NOTFOUND;
  dbms_output.put_line('Statement DateBeg ' || to_char(OptDate));
END LOOP;
CLOSE maxdate;
*/
return OptDate;
