PROCEDURE GetExtraction
(
   v_filial    number
,  v_BalType   number
,  v_Currency  Number
,  v_kli_id    varchar2
,  v_acc_no    varchar2
,  v_bal_cn    varchar2
,  v_date_beg  date
,  v_date_end  date
,  RateDif Number    -- Kurs fergi 0-he 1 yox
,  TurnYesNo number  -- Dovriyyeler 0-he 1-yox
)
is
   DateBeg date;
   DateEnd date;
   UserTab Varchar2(96);
   StrSql varchar2(1000);
   Str_For_Condition varchar2(500);
   Str_For_Currency varchar2(92);
			Str_for_filial varchar2(92);
   maxDate dynCursor;
   RateDiffCondition varchar2(92);
BEGIN

DateBeg:=v_date_beg;
DateEnd:=v_date_End;

if v_filial=-1 then
 Str_for_filial:='';
else
 Str_for_filial:=' and a1.filial=' || v_filial;
end if; 

if v_Currency=-1 then
 Str_For_Currency:=' and a1.CurrencyId is not null ';
else
 Str_For_Currency:=' and a1.CurrencyId=' || v_Currency;
end if;

if (v_kli_id='-1') and (v_acc_no='''-1''') and (v_bal_cn='-1') then
 str_for_condition:='';
else
 str_for_condition:='
 and ( a1.BalanceCode in ('||v_bal_cn||') 
    or a1.AccountNumber in ('||v_acc_no||')
    or a1.CustomerId in ('||v_kli_id||') 
     )';
end if;

UserTab:= user ||'.EXTRACTION_'|| user;
strsql:=
' create table ' || UserTab || ' as
select
   a1.*
 , 0         PreviousRest
 , sysdate   LastOpDate  
 , P_EXTRACTION.fdate('''||DateBeg||''',OpenDate) DatDate  
-- , sysdate   DatDate
 , 0         Ostat
 , 0         Pok_Ostat
 , 0         Obr_d
 , 0         Obr_k
 , 0         Pok_Obr_d
 , 0         Pok_Obr_k
 , ''(P)''   AP_beg
 , to_date('''||DateEnd||''') EndDate
 , 0         EndOstat
 , 0         EndPok_Ostat
 , 0         EndObr_d
 , 0         EndObr_k
 , 0         EndPok_Obr_d
 , 0         EndPok_Obr_k
 , ''(M)''   AP_end
from v_Account'||v_BalType||' a1
where a1.OpenDate<=''' ||DateEnd || ''''
|| Str_For_Currency
|| str_for_condition
|| Str_for_filial
|| ' order by accountnumber';

/*if upper(user)='ATABANK' then 
  raise_application_error(-20366, 'Str_For_Currency : '||Str_For_Currency||'  : str_for_condition : '||str_for_condition||' :Str_for_filial : '||Str_for_filial );
--  raise_application_error(-20366, ' usertab '||usertab||''||' strsql '||strsql);
 end if;
 */  
to_table(UserTab,StrSql);
commit;
strsql:='
Update '||UserTab||' e set 
(e.endostat, e.endpok_ostat, e.endobr_d, e.endobr_k, e.endpok_obr_d, e.endpok_obr_k, AP_end)
=
(select 
  a.ostat   , a.pok_ostat   , a.obr_d   , a.obr_k   , a.pok_obr_d   , a.pok_obr_k 
 ,decode(sign(a.pok_ostat),1,''(P)'',0,''(P)'',-1,''(A)'',''(P)'')
 from archost a where e.AccountId=a.acc_id and a.datdate=
 (select max(datdate) from archost a1 where datdate<='''||DateEnd||'''))';
	
EXECUTE IMMEDIATE StrSql;
commit;

strsql:='
update '||UserTab||' e set 
(e.lastopdate,  e.datdate,  e.ostat, e.pok_ostat, e.obr_d, e.obr_k, e.pok_obr_d, e.pok_obr_k, 
 AP_Beg)
=
(select
  a.lastopdate, a.datdate, a.ostat, a.pok_ostat, a.obr_d, a.obr_k, a.pok_obr_d, a.pok_obr_k, 
 decode(sign(a.pok_ostat),1,''(P)'',0,''(P)'',-1,''(A)'',''(P)'')
 from 
  archost a 
 where 
 e.AccountId=a.acc_id and 
 a.datdate=
 (select max(datdate) from archost a1 where datdate<'''||DateBeg||'''))';
--update a1 set c5 = strsql;commit;
EXECUTE IMMEDIATE StrSql;

if RateDif =1 then
 RateDiffCondition :=' and (P.vid_op<>1)';
else
 RateDiffCondition :='';
end if; 
strsql:='
update '||UserTab||' e set 
 e.LastOpDate = (select max(dat) from provarch p 
	  where (p.debt=e.AccountId or kredit=e.AccountId) 
	   and  p.dat <'''||DateBeg||''''||RateDiffCondition||')
';  
 --update A1 set c5=strsql;
 --EXECUTE IMMEDIATE StrSql; --Narik
-- commit; -- Narik

strsql:='
update '||UserTab||' e set 
 e.datdate = ''' || DateBeg || ''' 
 where e.datdate is null';
EXECUTE IMMEDIATE StrSql;
/*if upper(user)='ATABANK' then 
  raise_application_error(-20366, 'UserTab : '||UserTab||'  : v_date_beg : '||v_date_beg||' :v_date_end : '||v_date_end||' Turnyesno '|| turnyesno );
--  raise_application_error(-20366, ' usertab '||usertab||''||' strsql '||strsql);
 end if;
*/ 
GetExtracTrans(UserTab,v_date_beg,v_date_end,RateDif,TurnYesNo);
commit;
end;

