Function CheckCurrency 
(
   D_OR_K       NUMBER
,  CURRENCYID_D NUMBER 
,  CURRENCYID_C NUMBER
,  AMMOUNT      NUMBER
,  AMMOUNT_C    NUMBER
,  LAMMOUNT     NUMBER
)    
return Number is
Result number;
begin
Result:=0;
if CURRENCYID_D=CURRENCYID_C then
  Result:= Ammount;
  Return Result;
end if;

If D_OR_K=0 then -- debit
 if CURRENCYID_D=0 then 
  Result:= Ammount_c;
 else
  Result:= Ammount;
 end if;
else -- kredit
 if CURRENCYID_C=0 then 
  Result:= Ammount;
 else
  Result:= Ammount_C;
 end if;
End if;
 return Result;
end;


PROCEDURE TO_TABLE
(
  UserTab IN varchar2
, StrSql  IN varchar2
)
is
 nRow integer;
 v_Cursor integer;
 vCount Integer;
 DotPos integer := Instr(UserTab, '.');
 ATableName varchar2(32);
BEGIN

	if DotPos <> 0 then
		ATableName := substr(UserTab, DotPos+1, Length(UserTab)-DotPos);
	else
		ATableName := UserTab; 
	end if;
	
	select count(*)
		into vCount 
	from sys.all_tables
	where (owner = GetUserName) and (TABLE_NAME = Upper(ATableName));
commit;
if vCount<>0 then
  EXECUTE IMMEDIATE 'drop table ' || UPPER(UserTab);
end if;
  EXECUTE IMMEDIATE StrSql;
END;
--*******************************************

PROCEDURE TO_TABLEa
(
  UserTab IN varchar2
, StrSql  IN varchar2
)
is
 nRow integer;
 v_Cursor integer;
 vCount Integer;
 DotPos integer := Instr(UserTab, '.');
 ATableName varchar2(32);
BEGIN
	if DotPos <> 0 then
		ATableName := substr(UserTab, DotPos+1, Length(UserTab)-DotPos);
	else
		ATableName := UserTab; 
	end if;
	
	select count(*)
		into vCount 
	from sys.all_tables
	where (owner = GetUserName) and (TABLE_NAME = Upper(ATableName));
commit;
/*if upper(user)='ATABANK' then 
--  raise_application_error(-20366, 'UserTab : '||UserTab||'  : v_date_beg : '||v_date_beg||' :v_date_end : '||v_date_end||' Turnyesno '|| turnyesno );
  raise_application_error(-20366, ' usertab '||atablename||' '||vcount||' '||strsql);
 end if;
*/
if vCount<>0 then
  EXECUTE IMMEDIATE 'drop table ' || UPPER(UserTab);
end if;
  EXECUTE IMMEDIATE StrSql;
END;


--*****************************************
FUNCTION IIFBALANCE
  (
        n integer
,       TypeId1  integer
,       TypeId2  integer
,       aRemainder number
,       pRemainder number
        )RETURN  number IS

value number(15,2);
BEGIN
if TypeId1=1 and TypeId2=2 then
 if n=-1 then
  value:=0;
 else
  value:=-(aRemainder+pRemainder);
 end if;
elsif TypeId1=2 and TypeId2=1 then
 if n=-1 then
  value:=-(aRemainder+pRemainder);
 else
  value:=0;
 end if;
elsif TypeId1=3 and TypeId2=1 then
 if n=-1 then
  value:=(aRemainder+pRemainder);
 else
  value:=0;
 end if;
elsif TypeId1=3 and TypeId2=2 then
 if n=-1 then
  value:=0;
 else
  value:=-(aRemainder+pRemainder);
 end if;
elsif TypeId1=TypeId2 then
 if n=-1 then
  value:=aRemainder;
 else
  value:=pRemainder;
 end if;
end if;
RETURN value;
END;

procedure   getBankInfo(
  BankName OUT VarChar2
 ,BankCode OUT Number
 ,Manager  OUT VarChar2
 ,Accountant OUT varchar2        
 ) IS
begin
   Select  bank,kod_b,sedr,buhaltr into bankname,bankcode,manager,accountant from bankinfo;
   Exception When no_data_found Then
   begin
     BankName :='';
     BankCode :=0;
     Manager  :='';
     AccountAnt:='';
   end;
end;

Function GetBankDay return date is
begin
  return BankDay;
end;

Function IsWorkDay (D date)  return Boolean is
begin
--   if ( to_char(datdate,'D-MM-YYYY') = '1-1-2002'
   -- when Holidays return false
   if (( to_char(D,'DD-MM') = '31-12' ) or
       ( to_char(D,'DD-MM') = '01-01' ) or
       ( to_char(D,'DD-MM') = '20-01' ) or
       ( to_char(D,'DD-MM') = '08-03' ) or
       ( to_char(D,'DD-MM') = '20-03' ) or
       ( to_char(D,'DD-MM') = '09-05' ) or
       ( to_char(D,'DD-MM') = '15-06' ) or
       ( to_char(D,'DD-MM') = '26-06' ) or
       ( to_char(D,'DD-MM') = '18-10' ) or
       ( to_char(D,'DD-MM') = '12-11' ) or
       ( to_char(D,'DD-MM') = '17-11' ) 
      )
   then 
        return false;
   end if;
   -- when work day return true
   if (( to_char(D,'D') >= 2 ) and
       ( to_char(D,'D') <= 6 )
      )
   then 
        return true;             
   end if;
   
  return false;
end;
