PROCEDURE CalcDates (   v_date_beg  date,
                        v_date_end  date )
   IS
      
   InitSum              number(15);
   InitSumPok           number(15);
   InitSumId            number(10);
   InitSumDate          date;
   
   LastSum              number(15);
   LastSumPok           number(15);
   LastSumDate          date;
   
   DateBefore           date;
   StDate               date;
   EndDate              date;
   ArchOstMinDate       date;
   ArchOstMaxDate       date;
   ArchOstFirstID       number(10);    
   UserTab              Varchar2(96);
   StrSql               varchar2(1500);
   
CURSOR AccsSelForExtr IS
    SELECT * FROM ACCS_EXTR; 
              
BEGIN

    StDate          :=  v_date_beg; -- TO_date('20-10-2002','DD-MM-YYYY');
    EndDate         :=  v_date_end; -- TO_date('27-10-2002','DD-MM-YYYY');
    InitSum         :=  0;
    InitSumPok      :=  0;
    LastSum         :=  0;
    LastSumPok      :=  0;
       
    
    FOR Acc IN AccsSelForExtr loop
    
        DBMS_OUTPUT.PUT_LINE('Next Acc is '||Acc.ACC_ID); 
        
        if ( SQL%FOUND ) then 
            if ( SQL%ROWCOUNT = 0 ) then
            return;    
            end if;
        end if;
        
        SELECT      MIN(B.DATDATE)
        INTO        ArchOstMinDate  
        FROM        SMART.ARCHOST B
        WHERE       ( B.ACC_ID  =  Acc.ACC_ID );
        
       if ( ArchOstMinDate = Acc.ST_DATE ) then         
            InitSum     := 0;
            InitSumPok  := 0;
        else
         
        SELECT      MIN(B.DATDATE) 
        INTO        InitSumDate  
        FROM        SMART.ARCHOST B
        WHERE       ( B.ACC_ID  =  Acc.ACC_ID ) AND 
                    ( ( B.DATDATE >= StDate )  );

        SELECT      OSTAT, POK_OSTAT
        INTO        InitSum, InitSumPok
        FROM        ArchOst T          
        WHERE       ( T.DATDATE = InitSumDate AND T.ACC_ID = Acc.ACC_ID  );
                    
        end if;
        
        SELECT      MAX(B.DATDATE)
        INTO        LastSumDate  
        FROM        SMART.ARCHOST B
        WHERE       ( B.ACC_ID  =  Acc.ACC_ID ) and 
                    ( B.DATDATE <= EndDate );        
            
        SELECT      OSTAT,POK_OSTAT 
        INTO        LastSum, LastSumPok
        FROM        ArchOst T          
        WHERE       ( T.DATDATE = LastSumDate AND T.ACC_ID = Acc.ACC_ID  );
                        
        UPDATE  ACCS_EXTR
        SET     INIT_SUM      = InitSum,
                INIT_SUM_POK  = InitSumPok,
                INIT_SUM_DATE = InitSumDate,
                LAST_SUM      = LastSum,
                LAST_SUM_POK  = LastSumPok,
                LAST_SUM_DATE = LastSumDate
        WHERE   ACC_ID        = Acc.ACC_ID;
         
        commit;
    end loop;

end;
