PROCEDURE AddAccsByBalSeq(  v_BalSeq    String,   
                            v_BalType   Number,
                            v_Currency  Number,
                            vStDate     date,
                            vEndDate    date ) is
StrSql       varchar2(1500);
CurrCond     varchar2(100);   
BalTypeCond  varchar2(100);
vStDate1     date;
vEndDate1    date;
                  
begin
  
  DBMS_OUTPUT.PUT_LINE('AddAccsByBalSeq starts...');
  DBMS_OUTPUT.PUT_LINE('v_BalSeq is '||v_BalSeq);         
  if ( v_BalType = - 1 ) then
        BalTypeCond := '' ;
    else
        BalTypeCond :=  to_char( v_BalType) ;
  end if;
  
  if ( v_Currency =- 1 ) then
        CurrCond := '';
    else
        CurrCond := ' and ( P.VAL_ACC='||to_char(v_Currency)||') ';
  end if;

StrSql:='INSERT INTO  SMART.ACCS_EXTR (
ACC_ID,   ACC_NO,   NAME,  BAL_CN'||BalTypeCond||',        ST_DATE,          END_DATE )
SELECT 
P.ACC_ID, MIN(P.ACC_NO), MIN(P.NAME), MIN(P.BAL_CN'||BalTypeCond||'), MIN(P.PROV_DATE), MAX(P.PROV_DATE)
FROM
PROV_ALL P
WHERE ( P.BAL_CN'||BalTypeCond||' in ('||v_BalSeq||') ) '||CurrCond||'
GROUP BY  P.ACC_ID
HAVING  ( NOT( MAX(P.PROV_DATE) <'''||to_char(vStDate)||''' OR MIN(P.PROV_DATE) >'''||to_char(vEndDate)||'''))';
 
  DBMS_OUTPUT.PUT_LINE('AddAccsByBalSeq finishes');
Execute Immediate StrSql;
commit;
    
-- DebitTransMinDate := 0;
end;
