--*****************************************
FUNCTION IIFBALANCE
  (
        n integer
,       TypeId1  integer
, TypeId2  integer
,       aRemainder number
,       pRemainder number
        )RETURN  number IS

value number(15,2);
BEGIN
if TypeId1=1 and TypeId2=2 then
 if n=-1 then
  value:=0;
 else
  value:=-(aRemainder+pRemainder);
 end if;

elsif TypeId1=2 and TypeId2=1 then
 if n=-1 then
  value:=-(aRemainder+pRemainder);
 else
  value:=0;
 end if;

elsif TypeId1=3 and TypeId2=1 then
 if n=-1 then
  value:=(aRemainder+pRemainder);
 else
  value:=0;
 end if;

elsif TypeId1=3 and TypeId2=2 then
 if n=-1 then
  value:=0;
 else
  value:=-(aRemainder+pRemainder);
 end if;



elsif TypeId1=TypeId2 then
 if n=-1 then
  value:=aRemainder;
 else
  value:=pRemainder;
 end if;

end if;
RETURN value;
END;

