PROCEDURE TO_TABLE (  
 UserTab IN varchar2
,StrSql varchar2)
is
 vCount Integer;
BEGIN
	select count(*) into vCount from sys.all_tables
	 where (owner = User) and (TABLE_NAME = Upper(UserTab));
if vCount<>0 then
 EXECUTE IMMEDIATE 'drop table ' || UPPER(UserTab);
 commit;
end if;
EXECUTE IMMEDIATE 'Create Table '|| UserTab ||' as '|| StrSql;
commit;
END;
