Procedure Child as
Result Number:=0;
Begin
	Select Count(*) into Result from TempRepairTrans where ParentId=rTransaction.id; 
 if Result <> 0 then 
	 Select * into rChild from TempRepairTrans where ParentId=rTransaction.id; 
 else
  rChild.id:=0;
 End If;
End;
