CREATE OR REPLACE 
PACKAGE BODY p_statement IS
UserName varchar(32);
BankDay date;
Type DynCursor is ref cursor;  
---------------------------------------------------------------
FUNCTION fdate( v_Date IN Date, v_OpenDate in Date) return date as
OptDate Date;
begin
 if v_Date<v_OpenDate then
  OptDate:=v_OpenDate;
 else
  OptDate:=v_Date;
 end if;
return OptDate;
end;
-------------------------------------------------
PROCEDURE GetExtraction
(
   v_user      number
,  v_filial    number
,  v_BalType   number
,  v_Currency  Number
,  v_kli_id    varchar2
,  v_acc_no    varchar2
,  v_bal_cn    varchar2
,  v_date_beg  date
,  v_date_end  date
,  RateDif Number    -- Kurs fergi 0-he 1 yox
,  TurnYesNo number  -- Dovriyyeler 0-he 1-yox
)
is
   DateBeg date;
   DateEnd date;
   UserTab Varchar2(96);
   StrSql varchar2(2000);
   Str_For_Condition varchar2(500);
   Str_For_Currency varchar2(92);
   Str_for_filial varchar2(92);
   Str_for_user varchar2(92);
   maxDate dynCursor;
   RateDiffCondition varchar2(92);
   RecCount number;
BEGIN
DateBeg:=v_date_beg;
DateEnd:=v_date_End;

STRSQL:='Truncate table smart.EXTRACTION';
 Execute Immediate strsql;
STRSQL:='Truncate table smart.EXTRACTIONtrans';
 EXECUTE IMMEDIATE StrSql;

If v_user=-1 then
 Str_for_user:='';
Else
 Str_for_user:=' and ac.OP_ID=' || v_user;
End if; 

If v_filial=-1 then
 Str_for_filial:='';
Else
 Str_for_filial:=' and ac.filial=' || v_filial;
End if; 

If v_Currency=-1 then
 Str_For_Currency:='';
Else
 Str_For_Currency:=' and ac.val_acc=' || v_Currency;
End if;

If (v_kli_id='-1') and (v_acc_no='''-1''') and (v_bal_cn='-1') then
 str_for_condition:='';
Else
 str_for_condition:='
 and ( ac.Bal_Cn1 in ('||v_bal_cn||') 
    or ac.Acc_No in ('||v_acc_no||')
    or ac.kli_id in ('||v_kli_id||') 
     )';
End If;

dbms_output.put_line('Insert Into smart.EXTRACTION ');

strsql:='
Insert into smart.EXTRACTION
select
   c.name            CustomerName   
 , c.inn             CustomerVoin  
 , ac.kli_id         CustomerId 
 , ac.name           AccountName  
 , ac.acc_no         AccountNumber 
 , ac.id             AccountId 
 , ac.op_id          OperatorId 
 , ac.val_acc        CurrencyId 
 , av.val_name       CurrencyName 
 , ac.bal_cn1        BalanceCode 
 , ac.open_dat       OpenDate 
 , ac.filial         Filial 
 , ac.close_dat
 , 0                 PreviousRest
 , sysdate           LastOpDate 
 , smart.P_statement.fdate('''||DateBeg||''',ac.open_dat) DatDate 
 , 0                 Ostat
 , 0                 Pok_Ostat
 , 0                 Obr_d
 , 0                 Obr_k
 , 0                 Pok_Obr_d 
 , 0                 Pok_Obr_k
 , ''(P)''           AP_beg
 , to_date('''||DateEnd||''')  EndDate
 , 0                 EndOstat
 , 0                 EndPok_Ostat
 , 0                 EndObr_d
 , 0                 EndObr_k
 , 0                 EndPok_Obr_d
 , 0                 EndPok_Obr_k
 , ''(M)''           AP_end
from 
  account ac
, avalute av
, customers c
where 
    ac.val_acc = av.valute
and ac.kli_id=c.id
and ac.open_dat<=''' ||DateEnd || ''''
|| Str_For_Currency
|| str_for_condition
|| Str_for_filial
|| Str_for_user;

update a1 set c5=strsql;
commit;

EXECUTE IMMEDIATE StrSql;

dbms_output.put_line('End Insert ');
select Count(*) into RecCount from smart.EXTRACTION;
if RecCount <>0 then
dbms_output.put_line('Update N:1 ');
 Update smart.EXTRACTION e set 
 (e.endostat, e.endpok_ostat, e.endobr_d, e.endobr_k, e.endpok_obr_d, e.endpok_obr_k, AP_end)
 = (select 
   a.ostat   , a.pok_ostat   , a.obr_d   , a.obr_k   , a.pok_obr_d   , a.pok_obr_k 
  ,decode(sign(a.pok_ostat),1,'(P)',0,'(P)',-1,'(A)','(P)')
  from archost a where e.AccountId=a.acc_id and a.datdate=
  (select max(dat) from operkurs a1 where dat<=DateEnd));
	
dbms_output.put_line('Update N:2 ');
 Update smart.EXTRACTION e set 
 (e.lastopdate,  e.datdate,  e.ostat, e.pok_ostat, e.obr_d, e.obr_k, e.pok_obr_d, e.pok_obr_k, 
  AP_Beg)=
 (select
  a.lastopdate, a.datdate, a.ostat, a.pok_ostat, a.obr_d, a.obr_k, a.pok_obr_d, a.pok_obr_k, 
  decode(sign(a.pok_ostat),1,'(P)',0,'(P)',-1,'(A)','(P)')
  from 
   archost a 
  where 
  e.AccountId=a.acc_id and 
  a.datdate=
  (select max(dat) from operkurs a1 where dat<DateBeg));

-- Mezenne fergi Son emeliyyat tarixi sayilmir
--/*
dbms_output.put_line('Update N:3 ');
 
 /*  TNariman
 update smart.EXTRACTION e set e.LastOpDate = 
 ( 
   select max(dat) from provarch p 
 	where p.dat <DateBeg and (P.vid_op<>1)
     and (p.debt=e.AccountId or kredit=e.AccountId) 
  );  

 */ 
dbms_output.put_line('Update N:4 ');
 Update smart.EXTRACTION e set e.datdate = DateBeg where e.datdate is null;
--*/
end if;
dbms_output.put_line('Call GetExtracTrans');
GetExtracTrans(UserTab,v_date_beg,v_date_end,RateDif,TurnYesNo);
dbms_output.put_line('Return From GetExtracTrans');
dbms_output.put_line('END ALL ');
End;
------------------------------------------------------
PROCEDURE GetExtracTrans
(
  TableName Varchar2
, v_date_1 date
, v_date_2 date
, RateDif number
, TurnYesNo number
)
is
date_beg date;
date_end date;
STRSQL varchar2(1500);
v_Cursor number(9);
nRow number(9);
UserTab varchar2(64);

Begin
date_beg:=v_date_1; --GetApproximateDate(AccountID, v_date_1);
date_end:=v_date_2; --GetApproximateDate(AccountID, v_date_2);
dbms_output.put_line('Begin  GETsmart.smart.smart.EXTRACTIONtrans');
dbms_output.put_line('Insert Into smart.smart.smart.EXTRACTIONtrans');
Insert Into smart.EXTRACTIONtrans  
 Select 
 p.id
 , p.dat
 , p.tim
 , e.CurrencyId
 , e.AccountId OwnAccountID
 , p.kredit PairAccountId
 , a.acc_no PairAccountName
 , p.Currencyid_c PairCurrencyId
 , p_EXTRACTION.checkcurrency(0,p.val_acc,p.currencyid_c,p.ammount,p.ammount_c,p.lammount) debit
 , 0 Kredit
 , p.lammount Ldebit
 , 0 LKredit
 , p.vid_op OperationCode
 , p.name
 from smart.EXTRACTION 
 e, provarch p, account a 
  where 
    e.AccountId=p.debt 
    and p.kredit=a.id 
    and dat>= to_char(date_beg)
    and dat<= to_char(date_end)
  union 
 select 
 p.id
 , p.dat
 , p.tim
 , e.CurrencyId
 , e.AccountId OwnAccountID
 , p.debt PairAccountId
 , a.acc_no PairAccountName
 , p.val_acc PairCurrencyId
 , 0 debit
 , p_EXTRACTION.checkcurrency(1,p.val_acc,p.currencyid_c,p.ammount,p.ammount_c,p.lammount) Kredit
 , 0 Ldebit
 , p.lammount LKedit
 , p.vid_op OperationCode
 , p.name
 from smart.EXTRACTION
  e, provarch p, account a 
  where 
        e.AccountId=p.kredit 
  and p.debt=a.id
  and dat>=  to_char(date_beg)
  and dat<=  to_char(date_end)
;

dbms_output.put_line('End Insert Into smart.smart.smart.EXTRACTIONtrans');

if RateDif=1 then 
dbms_output.put_line('Delete RateDiff Transactions ');
 Delete from smart.EXTRACTIONtrans where OperationCode=1;
end if;


if TurnYesNo=0 then 
dbms_output.put_line('Delete Accounts wihch have not Turn');
 Delete from smart.EXTRACTION where not (accountid in 
  (select distinct ownaccountID from smart.EXTRACTIONtrans));
end if;
dbms_output.put_line('End GETEXTRACTIONtrans');

End;

--******************************************************
Function GetUserName return varchar2 is
begin
 return UserName;
end;

--******************************************************
Function CheckCurrency 
(
   D_OR_K       NUMBER
,  CURRENCYID_D NUMBER 
,  CURRENCYID_C NUMBER
,  AMMOUNT      NUMBER
,  AMMOUNT_C    NUMBER
,  LAMMOUNT     NUMBER
)    
return Number is
Result number;
begin
Result:=0;
if CURRENCYID_D=CURRENCYID_C then
  Result:= Ammount;
  Return Result;
end if;

If D_OR_K=0 then -- debit
 if CURRENCYID_D=0 then 
  Result:= Ammount_c;
 else
  Result:= Ammount;
 end if;
else -- kredit
 if CURRENCYID_C=0 then 
  Result:= Ammount;
 else
  Result:= Ammount_C;
 end if;
End if;
 return Result;
end;
--*****************************************
FUNCTION IIFBALANCE
  (
        n integer
,       TypeId1  integer
,       TypeId2  integer
,       aRemainder number
,       pRemainder number
        )RETURN  number IS

value number(15,2);
BEGIN
if TypeId1=1 and TypeId2=2 then
 if n=-1 then
  value:=0;
 else
  value:=-(aRemainder+pRemainder);
 end if;
elsif TypeId1=2 and TypeId2=1 then
 if n=-1 then
  value:=-(aRemainder+pRemainder);
 else
  value:=0;
 end if;
elsif TypeId1=3 and TypeId2=1 then
 if n=-1 then
  value:=(aRemainder+pRemainder);
 else
  value:=0;
 end if;
elsif TypeId1=3 and TypeId2=2 then
 if n=-1 then
  value:=0;
 else
  value:=-(aRemainder+pRemainder);
 end if;
elsif TypeId1=TypeId2 then
 if n=-1 then
  value:=aRemainder;
 else
  value:=pRemainder;
 end if;
end if;
RETURN value;
END;

procedure   getBankInfo(
  BankName OUT VarChar2
 ,BankCode OUT Number
 ,Manager  OUT VarChar2
 ,Accountant OUT varchar2        
 ) IS
begin
   Select  bank,kod_b,sedr,buhaltr into bankname,bankcode,manager,accountant from bankinfo;
   Exception When no_data_found Then
   begin
     BankName :='';
     BankCode :=0;
     Manager  :='';
     AccountAnt:='';
   end;
end;

Function GetBankDay return date is
begin
  return BankDay;
end;

Function IsWorkDay (D date)  return Boolean is
begin
--   if ( to_char(datdate,'D-MM-YYYY') = '1-1-2002'
   -- when Holidays return false
   if (( to_char(D,'DD-MM') = '31-12' ) or
       ( to_char(D,'DD-MM') = '01-01' ) or
       ( to_char(D,'DD-MM') = '20-01' ) or
       ( to_char(D,'DD-MM') = '08-03' ) or
       ( to_char(D,'DD-MM') = '20-03' ) or
       ( to_char(D,'DD-MM') = '09-05' ) or
       ( to_char(D,'DD-MM') = '15-06' ) or
       ( to_char(D,'DD-MM') = '26-06' ) or
       ( to_char(D,'DD-MM') = '18-10' ) or
       ( to_char(D,'DD-MM') = '12-11' ) or
       ( to_char(D,'DD-MM') = '17-11' ) 
      )
   then 
        return false;
   end if;
   -- when work day return true
   if (( to_char(D,'D') >= 2 ) and
       ( to_char(D,'D') <= 6 )
      )
   then 
        return true;             
   end if;
   
  return false;
end;
------------------------------------------
Procedure LastUpdate(dId number, cId number, trDate date) as

 dFirst date;
 cFirst date;
 dLast date;
 cLast date;
begin
execute immediate 'ALTER TRIGGER UPD_SET_OF_LASTOPDAY disable';
 dbms_output.put_line(to_char(dId)||' '||to_char(cId)||' '||to_char(TrDate));
 select lastopdate into dFirst  from archost where acc_id=dId and datdate=trDate;
 select lastopdate into cFirst from archost where acc_id=cId and datdate=trDate;
  dbms_output.put_line('First ' || to_char(dFirst)||' '||to_char(cFirst));

 select max(lastopdate) into dLast  from archost 
  where acc_id=dId and datdate<dFirst;

 select max(lastopdate) into cLast  from archost 
  where acc_id=cId and datdate<cFirst;
  dbms_output.put_line('Last ' || to_char(dLast)||' '||to_char(cLast));

update archost set lastopdate=dLast where acc_id=dId and datdate=trDate;
update archost set lastopdate=cLast where acc_id=cId and datdate=trDate;

execute immediate 'ALTER TRIGGER UPD_SET_OF_LASTOPDAY ENABLE';				
end;

begin
  select user, trunc(tek_dat) into UserName, BankDay from sysdat;
--  dbms_output.put_line('*');
end;
/

CREATE OR REPLACE 
PACKAGE quest_soo_pkg
IS
--
-- This package contains routines to support Spotlight On Oracle
--
-- Person      Date    Comments
-- ---------   ------  -----------------------------------------------
-- Guy         7oct98  Initial
-- Megh        20Jun99 Added procedures obj_keep, obj_unkeep and
--                     flush_shared_pool. Also added function obj_type
-- Han B Xie   Jun2000 - now.

    -- Global indicating that the object cache is initialized
    g_object_cache_initialized     NUMBER:=0;
    g_debug                        NUMBER:=0;

    --
    -- Function to format SQL
    --
    Function format_sql ( p_sql_text IN varchar2,
                          p_max_len  IN number:=256)
             RETURN  varchar2;
    PRAGMA restrict_references(format_sql, WNDS, RNDS, WNPS, RNPS);

    --
    -- Event_category returns the event "category" so we can group
    -- like categories.  It's overloaded to accept either a event anme
    -- or the INDX from X$KSLEI
    --
    FUNCTION event_category(p_event varchar2) RETURN varchar2;
    PRAGMA   RESTRICT_REFERENCES (event_category, WNDS, RNDS, WNPS);

    FUNCTION event_category(p_indx number) RETURN varchar2;
    PRAGMA   RESTRICT_REFERENCES (event_category, WNDS, RNDS, WNPS);

    FUNCTION latch_category(p_latch_name varchar2) RETURN varchar2;
    PRAGMA   RESTRICT_REFERENCES (latch_category, WNDS, RNDS, WNPS);

    FUNCTION obj_type(object_t varchar2) RETURN char;
    PRAGMA   RESTRICT_REFERENCES (obj_type, WNDS, RNDS, WNPS);

    --
    -- Event detail takes the p1, p2, p3 details from v$session_wait
    -- and returns the real location
    --
    FUNCTION event_detail(p_event varchar2,
                          p1text varchar2, p1 number,
                          p2text varchar2, p2 number,
                          p3text varchar2, p3 number)
             RETURN varchar2;

    FUNCTION IsSpOk RETURN number;
    PRAGMA   RESTRICT_REFERENCES (IsSpOk, WNDS, WNDS, WNPS);

    FUNCTION IsSprOk   RETURN number;
    PRAGMA   RESTRICT_REFERENCES (IsSprOk, WNDS, WNDS, WNPS);

    FUNCTION SgaOther RETURN number;
    PRAGMA   RESTRICT_REFERENCES (SgaOther, WNDS, WNDS, WNPS);

    --
    -- Procedure initialize to initialize PL/SQL tables , etc
    --
    PROCEDURE initialize;

    -- Quick but essential initialize
    PROCEDURE initializeA;
    -- Slower initialize which can be defered until main screen collected
    PROCEDURE initializeB;

    -- Print the current lock-tree
    PROCEDURE locktree;

    -- Set a normal trace on for the session
    PROCEDURE set_trace(p_sid NUMBER, p_serial NUMBER, p_mode boolean);

    -- Kill the nominated session
    PROCEDURE kill_session(p_sid NUMBER, p_serial NUMBER);

    -- Turn timed statistics on
    PROCEDURE set_timed_statistics;

    -- Keep object in shared pool
    -- PROCEDURE obj_keep(name in varchar2, type in varchar2);

    -- Unkeep object from shared pool
    -- PROCEDURE obj_unkeep(name in varchar2, type in varchar2);

    -- Flush shared pool
    PROCEDURE flush_shared_pool;

    --
    -- Translate values in the form 999{K|M} to byte values so
    -- instance monitor can deal with them
    --

    FUNCTION TRANSLATE_PARAMETER( p_value VARCHAR2) RETURN  varchar2;

    PRAGMA  RESTRICT_REFERENCES (translate_parameter, WNDS, RNDS, WNPS);

    --
    -- These routines support the "show locked row" facility
    --
    --Published procedures
    --Show the row locks being waited for by the specified sid
    FUNCTION show_locked_row(lsid in number) return varchar2;
    FUNCTION toRadixString(num in number, radix in number) return varchar2;
    PRAGMA   restrict_references(toRadixString, WNDS, WNPS, RNDS, RNPS);
    FUNCTION digitToString(num in number) return varchar2;
    PRAGMA   restrict_references(digitToString, WNDS, WNPS, RNDS, RNPS);

    FUNCTION sga_cat(p_pool VARCHAR2, p_name VARCHAR2) RETURN VARCHAR2;
    PRAGMA   restrict_references(sga_cat, WNDS, RNDS, WNPS, RNPS);

    FUNCTION sga_cat2(p_pool VARCHAR2, p_name VARCHAR2) RETURN VARCHAR2;
    PRAGMA   restrict_references(sga_cat2, WNDS, RNDS, WNPS, RNPS);

    FUNCTION sga_pool7(p_name VARCHAR2) RETURN VARCHAR2;
    PRAGMA   restrict_references(sga_pool7, WNDS, RNDS, WNPS, RNPS);

    FUNCTION sga_area7(p_name VARCHAR2) RETURN VARCHAR2;
    PRAGMA   restrict_references(sga_area7, WNDS, RNDS, WNPS, RNPS);

    -- Stuff for getting full SQL text
    FUNCTION exact_db_version(p_major OUT NUMBER,
                              p_minor1 OUT NUMBER,
                              p_minor2 OUT NUMBER)
             RETURN VARCHAR2;

    FUNCTION get_long_sqltext(p_hash_value NUMBER,
                              p_address RAW)
             RETURN VARCHAR2;

    FUNCTION get_session_long_sqltext(p_sid NUMBER)
             RETURN VARCHAR2;

    -- Decode lock details: TYPE, MODE, REQUEST
    FUNCTION lock_type_decode(type_p VARCHAR2, id2_p NUMBER default -1)
             RETURN VARCHAR2;
    PRAGMA restrict_references(lock_type_decode, WNDS, WNPS, RNPS);

    FUNCTION lock_mode_decode(mode_p NUMBER) RETURN VARCHAR2;
    PRAGMA   restrict_references(lock_mode_decode, WNDS, WNPS, RNPS);

END; -- quest_soo_pkg .
/

