         SET op_id = newowner
       WHERE op_id = owner;

      triggerinterface ('SMART', 'CUSTOMERS', TRUE);
      RETURN TRUE;
   EXCEPTION
      WHEN OTHERS
      THEN
         RETURN FALSE;
   END;

