CREATE OR REPLACE 
PACKAGE sb_archiveop
  IS
  procedure add_std_transaction (
		ArchiveDate					date,
    DebitID             integer,
    CreditID            integer,
    DAmount        			number,
		CAmount							number,
		LAmount							number,
    DebitRate           number,
    CreditRate          number,
    TrName              varchar2,
    Flags               integer default 0,
    Result    in out   integer
  );
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sb_archiveop
IS

	procedure add_std_transaction (
		ArchiveDate					date,
    DebitID             integer,
    CreditID            integer,
    DAmount        			number,
		CAmount							number,
		LAmount							number,
    DebitRate           number,
    CreditRate          number,
    TrName              varchar2,
    Flags               integer default 0,
    Result    in out   integer
  )
  as

		DebitCurrencyID integer; 
		CreditCurrencyID integer;

  begin
		/* Retreive currency IDs */
		
		/* DebitCurrencyID */
		DebitCurrencyID := sbrep.get_acc_currency(DebitID);	
		
		/* CreditCurrencyID */
		CreditCurrencyID := sbrep.get_acc_currency(CreditID);
	
		/* Add transaction */
		insert into provarch (
			DAT, DEBT, KREDIT, VAL_ACC, AMMOUNT, LAMMOUNT, 
			AMMOUNT_C, Rate_D, Rate_C, Name)
		values (
			ArchiveDate, DebitID, CreditID, DebitCurrencyID,
			DAmount, LAmount, CAmount, DebitRate, CreditRate, TrName 
		);
		
		/* Update account's balances */
		
		/*
			+??? ???????v? ??ђ? ???¶??v? - ?????????† ????? ?v????†???†
			+??? ????????v? ??ђ? ???¶??v? - ????????† ????? ?v????†???†
		 */
		
		-- Update debit account's balance */
		update archost
		set
			ostat = ostat - 
				SB_ARCHIVEOP_UTL.CalculateDebitAmount(
					DebitCurrencyID, 
					DAmount, 
					CreditCurrencyID, 
					CAmount,
					datdate), 
			pok_ostat =	pok_ostat - LAmount 
		where
			(acc_id = DebitID)
			and (datdate >= ArchiveDate);  
		
		-- Update credit account's balance */
		update archost
		set
			ostat = ostat + 
				SB_ARCHIVEOP_UTL.CalculateCreditAmount(
					DebitCurrencyID, 
					DAmount, 
					CreditCurrencyID, 
					CAmount,
					datdate), 
			pok_ostat = pok_ostat + LAmount 
		where
			(acc_id = CreditID)
			and (datdate >= ArchiveDate);
			
		/* Update rate difference transactions */

		SB_ARCHIVEOP_UTL.upd_RD_Transactions(
			DebitID, 
			DebitCurrencyID, 
			-DAmount, 
			ArchiveDate);
			
		SB_ARCHIVEOP_UTL.upd_RD_Transactions(
			CreditID, 				
			CreditCurrencyID, 
			CAmount, 
			ArchiveDate);
		
		-- Well done
  end;
	
END;
/

