CREATE OR REPLACE 
PACKAGE sb_archiveop_utl
  IS

	function CalculateDebitAmount(
		DebitCurrencyID integer,
		DebitAmount number,
		CreditCurrencyID integer,
		CreditAmount number,
		ArchiveDate date
	)
	return number;

	function CalculateCreditAmount(
		DebitCurrencyID integer,
		DebitAmount number,
		CreditCurrencyID integer,
		CreditAmount number,
		ArchiveDate date
	)
	return number;

  procedure upd_RD_Transactions(
		AccID integer, 
		CurrencyID integer, -- required to calculate lamount changes 
		DeltaAmount number, 
		FromDate date);
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sb_archiveop_utl
IS

	function CalculateDebitAmount(
		DebitCurrencyID integer,
		DebitAmount number,
		CreditCurrencyID integer,
		CreditAmount number,
		ArchiveDate date
	)
	return number
	is
		Result number;
	begin
		if (DebitCurrencyID <> 0) or (CreditCurrencyID = 0) then
			Result := DebitAmount;
		else
			Result :=
				CreditAmount * 
				sbop.get_currency_rate(CreditCurrencyID, ArchiveDate) / 
				sbop.get_currency_rate(DebitCurrencyID, ArchiveDate);
		end if;
		dbms_output.put_line(substr('CalculateDebitAmount: Returning '
			||TO_CHAR(Result)
			||', Date: '
			||TO_CHAR(ArchiveDate),1,255));
		return Result;
	end;

	function CalculateCreditAmount(
		DebitCurrencyID integer,
		DebitAmount number,
		CreditCurrencyID integer,
		CreditAmount number,
		ArchiveDate date
	)
	return number
	is
		Result number;
	begin
		if (CreditCurrencyID <> 0) or (DebitCurrencyID = 0) then
			Result := CreditAmount;
		else
			Result :=
				DebitAmount * 
				sbop.get_currency_rate(DebitCurrencyID, ArchiveDate) / 
				sbop.get_currency_rate(CreditCurrencyID, ArchiveDate);
		end if;
		dbms_output.put_line(substr('CalculateCreditAmount: Returning '
			||TO_CHAR(Result)
			||', Date: '
			||TO_CHAR(ArchiveDate),1,255));
		return Result;
	end;

	/* upd_RD_Transactions: Updates rate difference transactions after account's balance 
	||   changes
	|| Parameters:
	||   AccID - account
	||   CurrencyID - currencyID for this account
	||   DeltaAmount - amount difference (new - old)
	||   FromDate - Change date
	*/
	procedure upd_RD_Transactions(
		AccID integer, 
		CurrencyID integer, -- required to calculate lamount changes 
		DeltaAmount number, 
		FromDate date)
	is
		Transaction sbclibarchiveop.c_acc_rate_difference%rowtype;
		LastTransaction Transaction%type;
		CalculatedLAmount number;
	begin
		-- No RD transactions for accounts of national currency
		if CurrencyID = 0 then
			return;
		end if;

		for Transaction in sbclibarchiveop.c_acc_rate_difference(AccID, FromDate+1)
		loop
			dbms_output.put_line(
				'upd_RD_Transactions: editing RD transaction. ID: '
					||TO_CHAR(Transaction.ID)
					||', Date: '
					||TO_CHAR(Transaction.DAT));
		
			-- Backup
			LastTransaction := Transaction;
			
			/* Calculate new rate difference transaction */
			
			CalculatedLAmount := DeltaAmount * (
				sbop.get_currency_rate(CurrencyID, FromDate)-
				sbop.get_currency_rate(CurrencyID, Transaction.DAT)
			);

			-- calculate LAmount
			Transaction.lammount := Transaction.lammount + CalculatedLAmount;
			
			-- update sides in national currency (must be equal to LAmount)
			if sbrep.get_acc_currency(Transaction.DEBT) = 0 then
			-- Debit account is of national currency (debit or profit account)
				Transaction.ammount := Transaction.ammount + CalculatedLAmount;
			else
			-- one of this accounts MUST be of national currency
				Transaction.ammount_c := Transaction.ammount_c + CalculatedLAmount;   
			end if;
			
			-- Update rate difference transaction
			update provarch
			set
				Ammount = Transaction.Ammount,
				Ammount_C = Transaction.Ammount_C,
				LAmmount = Transaction.lammount
			where
				ID = Transaction.ID;

			/* Update account's balance after rate difference transaction modification */				

			dbms_output.put_line(TO_CHAR(Transaction.DAT)||' '||TO_CHAR(LastTransaction.LAmmount - Transaction.LAmmount));
			-- Update debit account's balance
			update archost
			set
				ostat = ostat + LastTransaction.Ammount - Transaction.Ammount,
				pok_ostat = pok_ostat + LastTransaction.LAmmount - Transaction.LAmmount 
			where
				(acc_id = Transaction.Debt)
				and (datdate = Transaction.Dat);
				
			-- Update credit account's balance
			update archost
			set
				ostat = ostat + Transaction.Ammount_C - LastTransaction.Ammount_C,
				pok_ostat = pok_ostat + Transaction.LAmmount - LastTransaction.LAmmount 
			where
				(acc_id = Transaction.KREDIT)
				and (datdate = Transaction.Dat);
		end loop; /* for Transaction in ... */
		 
	end;

END;
/

