CREATE OR REPLACE 
PACKAGE sb_callback_transactions
  IS

  type 
      TDynamicCursor is ref cursor;
 
  type t_transdata is record (
        TransactionDate date,
        OperationCode integer,
        DebtID integer,
        DebtCurrency integer,
        CreditID integer, 
        CreditCurrency integer,
        DebtAmmount number,
        CreditAmount number,
		LAmount number,
        DebtBalance integer,
        CreditBalance integer
        
	);


  procedure SetTransactions(
                          Debt Provdoc.debt%type,
                          Credit Provdoc.kredit%type,
                          OperationCode varchar,
                          BranchID filial.id%type);
END;
/

CREATE OR REPLACE 
PACKAGE BODY sb_callback_transactions
IS

procedure SetTransactions(
                          Debt Provdoc.debt%type,
                          Credit Provdoc.kredit%type,
                          OperationCode varchar,
                          BranchID filial.id%type)
is

  TDebt provdoc.debt%type;
  TCredit provdoc.kredit%type; 
  TransactionID provdoc.id%type;
  TDate provdoc.dat%type;
  
  Trans TDynamicCursor;
  
  TransData T_TransData;
   
  c_Transactions varchar(500);
begin
   c_Transactions :=' 
   select 
     p.dat, p.vid_op, p.debt, p.val_acc, p.kredit, p.currencyid_c, 
     p.ammount, p.ammount_c, p.lammount,
     d.bal_cn1 as dbalance,
     c.bal_cn1 as cbalance
   from 
     provdoc p,
     account d,
     account c
   where 
     p.debt = d.id
     and 
     p.kredit = c.id
     and
     (
     d.filial='||to_char(BranchID)||
     '
     or 
     c.filial='||to_char(BranchID)||
     '
     )
     and
     p.vid_op in ('||OperationCode||')';

  TDate :=SBOP.get_date;
  Open Trans for c_Transactions;
  loop
   fetch Trans into TransData;

   exit when Trans%notfound;
   
       --                 RateDifference
       
   IF TransData.OperationCode = 1 THEN 
     begin
        if TransData.DebtAmmount = 0 then
         begin
          TDebt :=Credit;
          TCredit :=Debt;
         end;
        else
         begin
          TDebt :=Debt;
          TCredit :=Credit;
         end; 
        end if;
        TransactionID :=
        sb_transaction.transaction_add (
                      debitid => TDebt,
                      creditid => TCredit,
                      debitamount => null,
                      creditamount => null,
                      lamount => TransData.LAmount,
                      debitrate => Null,
                      creditrate => Null,
                      trname => 'CallBack RateDifference Transactions',
                      flags => 0,
                      parentID => null,
                      OperationType =>11,
                      transactiondate => TDate);
     end;
     
       --                ProfitClosing
       
       
   ELSIF TransData.OperationCode = 2 THEN 
    begin
       if TransData.DebtBalance = 5501 then --between 6000 and 8000
        begin
         TDebt :=Debt;
         TCredit :=Credit;
        end;        
       else
        begin
         TDebt :=Credit;
         TCredit :=Debt;   
        end;
       end if;  
       TransactionID :=
       sb_transaction.transaction_add (
                      debitid => TDebt,
                      creditid => TCredit,
                      debitamount => null,
                      creditamount => null,
                      lamount => TransData.LAmount,
                      debitrate => Null,
                      creditrate => Null,
                      trname => 'CallBack ProfitClosing Transactions',
                      flags => 0,
                      parentID => null,
                      OperationType =>12,
                      transactiondate => TDate);

    end;                  
   END IF;    
  end loop;
  
  Commit Work;
  
end;
                          
END;
/

