CREATE OR REPLACE 
PACKAGE BODY sb_cashreport
IS
  Procedure       ChooseCashSymbol(
          TransactionID PROVARCH.id%Type
     ,NewBSymbolValue KASSA_B.symbol%Type 
		                                    )
Is
Begin
  update Provarch set KASSA_B=NewBSymbolValue
	where ID=TransactionID;
	commit;
End;
