							--if   Currency=1 then				
							--update a1 set c5 = QueryStr;commit;
							--end if; 					
		          Execute Immediate QueryStr;
							 						
						dbms_output.put_line(TO_CHAR(PresentDate)||'  Currency='||TO_CHAR(Currency)||'  Rate='||Rate);
						
				 	if   Currency <> 0 then
    				QueryStr:='Insert  Into '||TableName||
   				 '(Select '||BankID||' BankID,'||''''||'AZM'||''''||' ShortName,'
					           ||TO_CHAR(DefaultUSED)||' Using,'
					           ||''''||TO_CHAR(PresentDate)||''''||
											' PresentDate,'||TO_CHAR(DefaultCurrency)||' Currency,'
											||''''||DefaultOffical||''''||'  Offical,'
											||BalanceBill||' Balance
												,Max(B.CurrencyPosition) Incoming										
											  ,Sum(CPACTIVE(Ar.POK_OSTAT)) Active												
  										  ,Sum(CPPASSIVE(Ar.POK_OSTAT)) Passive,
										  '||1||' Rate From  Account Ac,Archost Ar,'||Reference||' B
											Where  (Ac.ID=Ar.Acc_ID)And(Ar.DatDate='
											||''''||TO_CHAR(PresentDate)||''''||')And(B.BAL_CN='||BalanceBill||
											')And(Ac.Val_Acc='||Currency||
											') Group By '||BalanceBill||')';
					 	update a1 set c5 = QueryStr;commit;		
					  	Execute Immediate QueryStr; 				   
						 end if;
					end if;	 							  	       		          
			 End Loop;
     Close CurrencySet;			  			   		  
	 End loop; 
	Close BankWorkingDays;
	Commit;
	
 Execute Immediate 'Delete From '||TableName||' Where Active=0 And Passive=0 ';
	Commit;     	
	EXCEPTION  WHEN  OTHERS  THEN
	BEGIN
	  Close BankWorkingDays;
		 Close CurrencySet;
