CREATE OR REPLACE 
PACKAGE BODY sb_custinfo
IS

 procedure add_custinfo
 (
    vidcust                         NUMBER,
    vsoname                         VARCHAR2 default null,
    vname                           VARCHAR2 default null,
    vlastname                       VARCHAR2 default null,
    vbirthday                       VARCHAR2 default null,
    vbirthplace                     VARCHAR2 default null,
    vpasser                         VARCHAR2 default null,
    vpaspnum                        NUMBER   default null,
    vpaspdate                       VARCHAR2 default null,
    vpaspplace                      VARCHAR2 default null,
    vcity                           VARCHAR2 default null,
    vaddress                        VARCHAR2 default null,
    vworkplace                      VARCHAR2 default null,
    vphone_w                        VARCHAR2 default null,
    vphone_h                        VARCHAR2 default null,
    vphone_m                        VARCHAR2 default null, 
