 procedure del_custinfo(v_id number)
 is
 begin
--Checks whether user has right to delete card from customer's info or not  
	sbsec.right_check('Right_CustInfoDelete');

  Delete from CustInfo
   where id=v_id;
   commit;  
 end;

 procedure upd_custinfo(
    vid                             NUMBER,
