PACKAGE sb_exchange
  IS
  procedure add_exchanges (v_name varchar, v_exnum number);
  procedure upd_exchanges (v_id number, v_name varchar, v_exnum number);
  procedure del_exchanges (v_id number);
  procedure del_all_excaccount(v_exchangeID number);
  procedure add_excaccount (v_exchangeID number,v_accountID number); 
  procedure del_excaccount (v_exchangeID number,v_accountID number);
  procedure upd_excaccount (v_exchangeID number,v_accountID number,last number);
  

  function GenerateFileName(Days number) return varchar;
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sb_exchange
IS
procedure add_exchanges (v_name varchar, v_exnum number)
  is
  begin
    insert into exchanges
                (name, exnum)
         values (v_name, v_exnum);
  end;

  procedure upd_exchanges (v_id number, v_name varchar, v_exnum number)
  is
  begin
   update exchanges
    set name = v_name
      , exnum= v_exnum
     where id = v_id;

    commit;
  end;
  

  PROCEDURE del_exchanges(v_id number) 
  is
  begin
   Delete from exchanges 
    Where Id=v_id;
   commit;
  end;

  procedure add_excaccount (v_exchangeID number,v_accountID number)  
  is 
  begin
    insert into excaccount   
               (exchangeID,accountID)    
           values(v_exchangeID,v_accountID);   
  end;
  
  procedure upd_excaccount (v_exchangeID number,v_accountID number,last number)
  is 
  begin
    update excaccount
    set accountID=v_accountID
     where exchangeID=v_exchangeID and accountID=last ; 
   commit;
  end;
  
  procedure del_excaccount (v_exchangeID number,v_accountID number)
    is
  begin
   Delete from excaccount 
    Where exchangeID=v_exchangeID and accountID=v_accountID ;
   commit;
  end;
 
  procedure del_all_excaccount(v_exchangeID number)
  is
  begin
   Delete from ExcAccount
   where exchangeID=v_exchangeID;
  commit;
  end;
 
 function GenerateFileName(Days number) return varchar
 is
  FileHeader constant varchar(3) :='$MB';
  FileExtension constant varchar(3) :='dbf';
  BankCode varchar(10);
  Distance varchar(3);
  Result varchar(20);
 begin
  select (val_mov) into BankCode from BankInfo;
  
  if Days <= 15 then
   Distance :='01.';
  else
   Distance :='02.';
  end if;  
  
  Result :=FileHeader||BankCode||Distance||FileExtension;
  return Result;
  
  dbms_output.put_line('Result '||result);
 end;
 
END;
/

CREATE OR REPLACE 
PACKAGE sb_expertanalyse
  IS

  CommaDelimiter constant char := ',';
  OrdinaryTransaction constant number := -1;
  MultiCurrencyTransaction constant number := -2;
  
  function CheckTipAcc(bTipacc Operation_balances.tipacc%type,
                aTipacc Account.tipacc%type) return number;
  function FlagExsist(bTipacc Operation_balances.tipacc%type,
                       aTipacc Account.tipacc%type
                       ) return boolean;
  function GetOperationType(OperationType Provarch.vid_op%type,
                           DebetCurrency Provarch.val_acc%type,
                           CreditCurrency Provarch.currencyid_c%type
                           ) return Vid_op.ID%type;
  function GetUserName(userid user$.id%type)
 return varchar2;
  function GetCreditPercent(accid account.id%type) return varchar;
END;
/

CREATE OR REPLACE 
PACKAGE BODY sb_expertanalyse
IS

 function CheckTipAcc(bTipacc Operation_balances.tipacc%type,
                      aTipacc Account.tipacc%type
                      ) return number
 is
 begin
  if bTipacc is null then return 1;
  end if;

  if (bTipacc is not null) and (aTipacc is null) then return 0;
  end if;
  
  if FlagExsist(bTipacc, aTipacc) then 
   return 1;
  else
   return 0;
  end if;   
  
 end;  
 
 function FlagExsist(bTipacc Operation_balances.tipacc%type,
                     aTipacc Account.tipacc%type
                     ) return boolean
 is
  BTip Operation_balances.tipacc%type;
  ATip Account.tipacc%type;  
  LengthBTip number;
  IsExsist Boolean :=true;  
  ch varchar(1);  
 begin
  BTip :=Upper(Replace(bTipacc,CommaDelimiter));
  ATip :=Upper(Replace(aTipacc,CommaDelimiter));
  
  LengthBTip :=Length(BTip);
 
  for POS in 1..LengthBTip
  loop
    ch :=substr(BTip, POS, 1);
    IsExsist :=IsExsist and (Instr(ATip, ch)>0); 
    exit when not IsExsist; 
  end loop;
  
  /* 
   if IsExsist then
    --dbms_output.put_line('IsExsist True');
    Return true;
   else
    --dbms_output.put_line('IsExsist False');
    
    Return false; 
   end if;
  */
  Return IsExsist;  
 end;   

 function CheckCurrency(DebetCurrency Provarch.val_acc%type,
                        CreditCurrency Provarch.currencyid_c%type
                       ) return Vid_op.ID%type
 is
  Result Vid_op.id%type;
 begin
  if DebetCurrency = CreditCurrency then
   Result :=OrdinaryTransaction;
  else
   Result :=MultiCurrencyTransaction;
  end if;
  return Result;  
 end;                      

 
 function GetOperationType(OperationType Provarch.vid_op%type,
                           DebetCurrency Provarch.val_acc%type,
                           CreditCurrency Provarch.currencyid_c%type
                           ) return Vid_op.ID%type
 is
  Result Vid_op.id%type;
  NotFound boolean;
 
  cursor c_VidOp(OperationID Provarch.vid_op%type) is
    select ID from Vid_op where ID = OperationID; 
  ID number;
 begin
  /*1. Operation Type is Exist.Application defined type */
  if OperationType is not null then
   begin
    Open c_VidOp(OperationType);
     Fetch c_VidOp into ID;     
     NotFound :=c_VidOp%NotFound;  
    Close c_VidOp;

    if NotFound then
     Result :=CheckCurrency(DebetCurrency, CreditCurrency);
    else
     Result :=OperationType; 
    end if; 
   end;
  else
   Result :=CheckCurrency(DebetCurrency, CreditCurrency); 
  end if;
  Return Result;
 end;

function GetUserName(userid user$.id%type)
 return varchar2
is
 UserName user$.name%type;
begin
 begin
  select 
    Name 
  into 
    UserName 
  from 
    user$ 
   where 
    id = userid;
 
  Exception When NO_DATA_FOUND Then
   return '<UNKNOWN>';
 end;
 
 return UserName;
 
end;

function GetCreditPercent(accid account.id%type) return varchar
is
  result sbcm_interests.interest%type;
begin
begin
 select 
   interest 
 into 
   result 
 from 
   sbcm_interests 
  where 
   id# = (select id# from sbcm_contract_accounts where CONTRACTACCID = accid);
  exception 
    when NO_DATA_FOUND then
     return '…ќ’ƒ”–!';
    When TOO_MANY_ROWS then
   return 'TOO_MANY_ROWS';
    when others then
     return '„ќ’ ћ÷√ј¬»Ћя!';
END;     

  return to_char(result);   
end;

                     
END;
/

