Function GetRate (AccID integer, ArchiveDate date) return number	is
	Result number;
 CurrencyID number;
Begin
 Select VAL_ACC into CurrencyID From account partition (ACTIVACC) where ID = AccID;
	Select OSTAT into Result from OPERKURS	where  
   VAL_KOD =CurrencyID and DAT = ArchiveDate;
	return Result;
	exception
		when NO_DATA_FOUND then
			raise_application_error(sbdecls.Error_NoRateForDateSpecified, 
				'Rate for specified date not found. CurrencyID='||TO_CHAR(CurrencyID)||', Date='||TO_CHAR(ArchiveDate));
end;
