			from OPERKURS
		where
			(DAT = TargetDate)
			and (VAL_KOD = CurrencyID)
	;
	
	cursor c_RateByAcc(AccID integer, TargetDate date)
	is
		select OSTAT as Result
			from OPERKURS
		where
			(DAT = TargetDate)
			and (VAL_KOD = (
				select VAL_ACC 
					from account
				where
					ID = AccID
				)
			)
	;
	
