(
  UserTab IN varchar2
, StrSql  IN varchar2
)
is
 nRow integer;
 v_Cursor integer;
BEGIN
select count(*) into nRow from tab where TNAME=UserTab;
--update a1 set c5=strsql;
--commit;
nRow:= 1;
if nRow<>0 then
-- EXECUTE IMMEDIATE 'drop table ' || UserTab;
  v_Cursor:=dbms_sql.open_cursor;
  dbms_sql.parse(v_Cursor,'drop table ' || UserTab ,dbms_sql.v7);
  nRow:=dbms_sql.execute(v_Cursor);
  dbms_sql.Close_cursor(v_cursor);
end if;
--EXECUTE IMMEDIATE StrSql;
 v_Cursor:=dbms_sql.open_cursor;
 dbms_sql.parse(v_Cursor,strsql,dbms_sql.v7);
 nRow:=dbms_sql.execute(v_Cursor);
 dbms_sql.Close_cursor(v_cursor);
END;

Function GetUserName return varchar2 is

begin
 return UserName;
end;

   
END;
