CREATE OR REPLACE 
PACKAGE BODY sbarch
IS

	VerboseLogging boolean := False;

	procedure exec_sql(Query varchar2, RaiseOnException boolean)
	is
		cur integer;
		rown integer;	
	begin
		if VerboseLogging then
			dbms_output.put_line('exec_sql: "'||Query||'"');
		end if;
		cur := dbms_sql.open_cursor();
		begin
			dbms_sql.parse(cur,Query,dbms_sql.NATIVE);
			rown := dbms_sql.execute(cur);
		exception
			when OTHERS then
				if RaiseOnException then
					dbms_sql.close_cursor(cur);
					raise;
				end if;
		end;
		dbms_sql.close_cursor(cur);
	end;

	procedure schema_backup(Prefix varchar2, SourceSchema varchar2, TargetSchema varchar2)
	is
		cursor c_tables(ObjOwner varchar2, ObjType varchar2)
		is
			select * from sys.all_objects
			where (OWNER = ObjOwner) and (OBJECT_TYPE = ObjType);
	begin
	
		dbms_output.put_line('Backing up schema: "'||SourceSchema||'" to "'||TargetSchema||'", Prefix: "'||Prefix||'"');
		dbms_output.put_line('This will backup the data only, not the structure.');
	
		dbms_output.put_line('. About to back up tables...');
		for ATable in c_tables(SourceSchema, 'TABLE')
		loop
			dbms_output.put_line('.. Archiving table: '||ATable.OBJECT_NAME);
			exec_sql(
  			'DROP TABLE '||TargetSchema||'.'||Prefix||ATable.OBJECT_NAME,
				False
			);
			exec_sql(
  			'CREATE TABLE '||TargetSchema||'.'||Prefix||ATable.OBJECT_NAME||sbdecls.CRLF||
  			'AS'||sbdecls.CRLF||
  			'  SELECT * FROM '||SourceSchema||'.'||ATable.OBJECT_NAME,
				True
			);
			exec_sql(
				'INSERT INTO '||TargetSchema||'.'||Prefix||ATable.OBJECT_NAME||sbdecls.CRLF||
				'SELECT * FROM '||SourceSchema||'.'||ATable.OBJECT_NAME,
				True
			);
		end loop;
		dbms_output.put_line('. Tables backup complete');
		dbms_output.put_line('End of the schema backup');		 
	end;
	
	procedure schema_restore(Prefix varchar2, SourceSchema varchar2, TargetSchema varchar2)
	is
	begin
		dbms_output.put_line(' ');
		/* Step 1. Retreive trigger's status */
		/* Step 2. Disable triggers */
		/* Step 3. Restore tables */
		/* Step 4. Enable triggers that was enabled before step 1 */
	end;

END;
