CREATE OR REPLACE 
PACKAGE sbarchiveop
  IS
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sbarchiveop
IS

	procedure add_std_transaction (
		ArchiveDate					date,
    DebitID             integer,
    CreditID            integer,
    DAmount        			number,
		CAmount							number,
		LAmount							number,
    DebitRate           number,
    CreditRate          number,
    TrName              varchar2,
    Flags               integer default 0,
    Result    in out   integer
  )
  as

		DebitCurrencyID integer; 
		CreditCurrencyID integer;
		Transaction sbclibarchiveop.c_acc_rate_difference%rowtype;
		LastTransaction Transaction%type;

  begin
		/* Retreive currency IDs */
		
		/* DebitCurrencyID */
		DebitCurrencyID := sbrep.get_acc_currency(DebitID);	
		
		/* CreditCurrencyID */
		CreditCurrencyID := sbrep.get_acc_currency(CreditID);
	
		/* Add transaction */
		insert into provarch (
			DAT, DEBT, KREDIT, VAL_ACC, AMMOUNT, LAMMOUNT, 
			AMMOUNT_C, Rate_D, Rate_C, Name)
		values (
			ArchiveDate, DebitID, CreditID, DebitCurrencyID,
			DAmount, LAmount, CAmount, DebitRate, CreditRate, TrName 
		);
		
		/* Update account's balances */
		
		/*
			+??? ????????v? ??ђ? ???¶??v? - ?????????† ????? ?v????†???†
			+??? ????????v? ??ђ? ???¶??v? - ????????† ????? ?v????†???†
		 */
		
		-- Update debit account's balance */
		update archost
		set
			ostat = ostat - DAmount, 
			pok_ostat =	pok_ostat - LAmount 
		where
			(acc_id = DebitID)
			and (datdate >= ArchiveDate);  
		
		-- Update credit account's balance */
		update archost
		set
			ostat = ostat + CAmount,
			pok_ostat = pok_ostat + LAmount 
		where
			(acc_id = CreditID)
			and (datdate >= ArchiveDate);
			
		/* Update rate difference transactions */
		
		-- Update debit account
		for Transaction in sbclibarchiveop.c_acc_rate_difference(DebitID, ArchiveDate+1)
		loop
			-- Backup
			LastTransaction := Transaction;
			
			-- Calculate new rate difference transaction
			Transaction.lammount := Transaction.lammount + DAmount;
			if sbrep.get_acc_currency(DebitID) = 0 then
				Transaction.ammount := Transaction.ammount + DAmount;
			else
				Transaction.ammount_c := Transaction.ammount_c + DAmount;   
			end if;
			
			-- Update rate difference transaction
			update provarch
			set
				Ammount = Transaction.Ammount,
				Ammount_C = Transaction.Ammount_C,
				LAmmount = Transaction.lammount
			where
				ID = Transaction.ID;

			/* Update account's balance after rate difference transaction modification */				

			-- Update debit account's balance
			update archost
			set
				ostat = ostat + LastTransaction.Ammount - Transaction.Ammount,
				pok_ostat = pok_ostat + LastTransaction.LAmmount - Transaction.LAmmount 
			where
				acc_id = Transaction.Debt;
				
			-- Update credit account's balance
			update archost
			set
				ostat = ostat + Transaction.Ammount_C - LastTransaction.Ammount_C,
				pok_ostat = pok_ostat + Transaction.LAmmount - LastTransaction.LAmmount 
			where
				acc_id = Transaction.KREDIT;
				
		end loop;
		 
		/* update credit account's rate difference */
		
		-- Well done
  end;
END;
/

CREATE OR REPLACE 
PACKAGE sbbalance
  IS
  Procedure Get_Balance
      (
      v_acc_no IN VARCHAR2,
      v_date_ic IN DATE,
      v_date_oc OUT DATE,
      v_date_ip IN DATE,
      v_date_op OUT DATE,
      vo_ostat_c out number,
      vo_ostat_p out number
      );
END;
/

CREATE OR REPLACE 
PACKAGE sbclibarchiveop
IS

	/* c_acc_rate_difference: Enumerates rate difference transactions for account
	|| Parameters:
	||		AccID - ID of the account
	||		ArchiveDate - The start date
	|| Note: L????????¶??† ????v ????????, ? ?? ??? VID_OP 
	*/
	cursor c_acc_rate_difference(AccID integer, ArchiveDate date)
	is
  	select * 
			from provarch
  	where
			(dat >= ArchiveDate) 
  		and ((Ammount = 0) or (Ammount_C = 0)) 
  		and ((DEBT = AccID) or (KREDIT = AccID))
			and (VAL_ACC <> CurrencyID_C);

	/* c_acc_history: ¶???????†?? ??????¶ ???????? ? ????????
	|| ?? ??ђ?? ??????† ? ???????ђ???? ???v
	|| Parameters:
	||		AccID - ID of the account
	||		ArchiveDate: The date
	*/
	cursor c_acc_history(AccID integer, ArchiveDate date)
	is
  	select * 
  		from archost
		where 
			(datdate > ArchiveDate)
			and (acc_id = AccID);
			
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sbclibarchiveop
IS

	/* 
	|| There are no code currently defined
	*/
	
END;
/

