CREATE OR REPLACE 
PACKAGE BODY sbcm_contract
IS
Procedure  NewDeposit(
            p_Type  IN  Integer
           ,p_OpenDate IN Date
           ,p_CloseDate IN Date
           ,p_Amount IN Number
           ,p_ContractNo IN VarChar2
           ,p_ContractType IN VarChar2
           ,p_ClientType IN Integer
           
           ,p_ContractAccID IN Integer
           ,p_ClientAccID IN Integer
           ,p_InterestAccID IN Integer
           
           ,p_Percent IN Number
           ,p_OverduePercent IN Number 
           )
Is
  TakedID SBCM_CONTRACTS.ID%type;
Begin
SB_ACA.CheckObjectAccess('DEPOSITMANAGER','insert');  --adm
TakedID := AddContract(
                      p_Type
        			 ,p_OpenDate
        			 ,p_CloseDate
        			 ,p_Amount
        			 ,p_ContractNo
        			 ,p_ContractType
        			 ,null
        			 ,null
        			 ,p_ClientType
        			 ,null
               ,null
		           );
      AddContractAccounts(
						  TakedID
		                 ,p_ContractAccID
            			 ,p_ClientAccID
            			 ,null
            			 ,p_InterestAccID
            			 ,null
            			 ,null
                   ,null
		                 );
      	 AddContractState(
	  			      TakedID
	                 ,0
					 ,0
					 ,0
					 ,0
					 ,Null
					 ,p_OpenDate  -- LastWCDate
					 ,p_OpenDate
					 ,1
					 ,null
					 ,null
					 ,null 
                     ,0   
			    	 );
     AddInterest(
         TakedID
        ,p_OpenDate
        ,p_Percent 
        );
     AddOverdueInterest(
         TakedID
        ,p_OpenDate
        ,p_OverduePercent 
        );
                                                   
   COMMIT;
   
End;
Procedure  UpdateDeposit(
              p_ContractID Integer
             ,p_Type  Integer
	         ,p_OpenDate Date
			 ,p_CloseDate Date
			 ,p_Amount  Number
			 ,p_ContractNo VarChar2
			 ,p_ContractType Integer 
			 ,p_ClientType  Number 
			 
                ,p_ContractAccID  Number
    			,p_ClientAccID  Number    			
    			,p_InterestAccID Number
                
                ,p_Percent IN Number
                ,p_OverduePercent IN Number    					  						
            )
Is
begin
 SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
    UpdateContract(
              p_ContractID 
             ,p_Type  
	         ,p_OpenDate 
			 ,p_CloseDate 
			 ,p_Amount  
			 ,p_ContractNo 
			 ,p_ContractType 
			 ,null  
			 ,null  
			 ,p_ClientType
			 ,null
       ,null  
	   );
 UpdateContractAccounts(
         p_ContractID
        ,p_ContractAccID  
    	,p_ClientAccID  
    	,null 
    	,p_InterestAccID
    	,null 
    	,null
      ,null     
     );
 UpdateContractState(
      p_ContractID
     ,null 
  	 ,null 
  	 ,null
	 ,null 
     );
	DeleteInterests(p_ContractID);
	DeleteOverdueInterests(p_ContractID);
    AddInterest(
         p_ContractID
        ,p_OpenDate
        ,p_Percent 
        );
     AddOverdueInterest(
         p_ContractID
        ,p_OpenDate
        ,p_OverduePercent 
        );
   
  COMMIT;
end;                        
Procedure  NewContract(
        p_Type  Integer
	     ,p_OpenDate Date
			 ,p_CloseDate Date
			 ,p_Amount  Number
			 ,p_ContractNo VarChar2
			 ,p_ContractType Integer
			 ,p_PledgeType  Integer
			 ,p_ReliabilityID  Integer 
			 ,p_ClientType  Number  --addcontract
			 ,p_PledgePrice Number
			 
                ,p_ContractAccID  Number
    			,p_ClientAccID  Number
    			,p_ReserveAccID Number
    			,p_InterestAccID Number
    			,p_OverdueAccID  Number
    			,p_OverdueInterestAccID Number -- AddcontractAccounts
          ,p_OverdueReserveAccID  Number
		  		
		      -- ,p_FacticalDebt Number  --AddContractState
				--	 ,p_OverdueDebt  Number
				--	 ,p_FacticalInterestDebt Number
				--	 ,p_OverdueInterestDebt Number
					 --,p_HCloseDate  Date                 -- !!!Actual Close Date!!!
					 ,p_StopCalculationDate Date
					 --,p_LastProcessDate  Date  --default null
					 --,p_CalculationEnabled Integer  --Is Calculation enabled 1 enabled 0 Disabled
					 ,p_ReguiredAmountDEC Number
					 ,p_ReguiredPercentDEC Number	
					 --,p_ResiuduaryAmount Number
           ,p_OverdueReliabilityID Number	
		   )			 
 Is
 TakedID SBCM_CONTRACTS.ID%type;
 Begin 
 SB_ACA.CheckObjectAccess('CREDITMANAGER','insert');  --adm      
    TakedID := AddContract(
		            p_Type
							 ,p_OpenDate
							 ,p_CloseDate
							 ,p_Amount
							 ,p_ContractNo
							 ,p_ContractType
							 ,p_PledgeType
							 ,p_ReliabilityID
							 ,p_ClientType
							 ,p_PledgePrice
               ,p_OverdueReliabilityID
		           );

		AddContractAccounts(
												TakedID
		                   ,p_ContractAccID
											 ,p_ClientAccID
											 ,p_ReserveAccID
											 ,p_InterestAccID
											 ,p_OverdueAccID
											 ,p_OverdueInterestAccID
                       ,p_OverdueReserveAccID
		                   );
	 AddContractState(
	  								TakedID
	                 ,0--p_FacticalDebt
									 ,0--p_OverdueDebt
									 ,0--p_FacticalInterestDebt
									 ,0--p_OverdueInterestDebt
									 ,Null
									 ,p_StopCalculationDate
									 ,p_OpenDate
									 ,1
									 ,p_ReguiredAmountDEC
									 ,p_ReguiredPercentDEC
									 ,p_Amount
                                     ,0  --ON  Contract  Conclusion ResiduaryAmount = Amount  
									 );
		AddStateCache(TakedID);							 
		InsertInterests(0,TakedID);
		InsertInterests(1,TakedID);		
            update SBCM_CONTRACTS
    set
      BRANCHID = (select Filial from Account where ID = p_ContractAccID)
    where 
      ID = TakedID;
					 
		Commit;							 
 End;
Procedure  AddStateCache(
            p_ID IN Number
           ) 
Is
Begin
   Insert Into SBCM_STATE_CACHE(
	               ID#
	              ,FacticalInterest 
							  ,OverdueInterest 	
	              )
					Values(
					 p_ID
					,0
					,0  
					);			
End;
 
Procedure  AddValue(
            InterestMode IN Integer
					 ,p_HDate IN Date
					 ,p_Percent IN Number 	
           ) 
Is
Begin
  if  InterestMode = 0  then
	  Interests(InterestIndex).HDate:=p_HDate;
		Interests(InterestIndex).Percent:=p_Percent;
		InterestIndex:=InterestIndex + 1;
	 else
	  OInterests(OInterestIndex).HDate:=p_HDate;
		OInterests(OInterestIndex).Percent:=p_Percent;
		OInterestIndex:=OInterestIndex + 1;
	end if;
End;					 
Procedure  Init(   
             PercentMode IN Integer         
            ,maxLength IN Integer												
					  ) 			 
Is
Begin
 if  PercentMode = 0 then    	
	 Interests :=TInterests();
   Interests.Extend(maxLength);
	 InterestIndex :=1;
 else	 
	 OInterests :=TInterests();
   OInterests.Extend(maxLength); 
	 OInterestIndex :=1;
 end if;	 
End;
Procedure Free
Is
Begin  		
	 Interests.Delete; 
	 InterestIndex :=1;	
	 OInterests.Delete;
	 OInterestIndex :=1;	   
End;											
	function AddContract(
    p_Type  Integer
   ,p_OpenDate Date
	 ,p_CloseDate Date
	 ,p_Amount  Number
	 ,p_ContractNo VarChar2
	 ,p_ContractType Integer
	 ,p_PledgeType  Integer
	 ,p_ReliabilityID  Integer
	 ,p_ClientType  Number
	 ,p_PledgePrice Number
   ,p_OverdueReliabilityID Number)
	return SBCM_Contracts.ID%type
  Is
    Result SBCM_Contracts.ID%type; 
  Begin
    Insert Into SBCM_CONTRACTS(
      Type#
		 ,OpenDate
		 ,CloseDate
		 ,Amount
		 ,ContractNo
		 ,ContractType
		 ,PledgeType
		 ,ReliabilityID
		 ,ClientType
		 ,PledgePrice
     ,OverdueReliabilityID)
  	Values(
      p_Type  
     ,p_OpenDate
     ,p_CloseDate
	   ,p_Amount 
	   ,p_ContractNo
		 ,p_ContractType
     ,p_PledgeType
     ,p_ReliabilityID
     ,p_ClientType
		 ,p_PledgePrice
     ,p_OverdueReliabilityID)
		returning ID into Result;
		return Result;		
  End;
	
Procedure  AddContractAccounts(
           p_ID         Number
          ,p_ContractAccID  Number
					,p_ClientAccID  Number
					,p_ReserveAccID Number
					,p_InterestAccID Number
					,p_OverdueAccID  Number
					,p_OverdueInterestAccID Number
          ,p_OverdueReserveAccID  Number
          )
 Is
 Begin
   Insert  Into  SBCM_CONTRACT_ACCOUNTS(
	 							  ID#
	               ,ContractAccID
								 ,ClientAccID
								 ,ReserveAccID
								 ,InterestAccID
								 ,OverdueAccID
								 ,OverdueInterestAccID
                 ,OverdueReserveAccID	 
	               )								 
		                      			Values(
																   p_ID
  		  													,CheckCorrectly(p_ContractAccID)  
                        	 				,CheckCorrectly(p_ClientAccID)  
                        					,CheckCorrectly(p_ReserveAccID) 
                        					,CheckCorrectly(p_InterestAccID)
                        					,CheckCorrectly(p_OverdueAccID) 
                        					,CheckCorrectly(p_OverdueInterestAccID)
                                  ,CheckCorrectly(p_OverdueReserveAccID)																
																);
		--commit;														  			  
 End;
Procedure  AddContractState(
            p_ID  Number
					 ,p_FacticalDebt Number
					 ,p_OverdueDebt  Number
					 ,p_FacticalInterestDebt Number
					 ,p_OverdueInterestDebt Number
					 ,p_CloseDate  Date
					 ,p_StopCalculationDate Date
					 ,p_LastProcessDate  Date
					 ,p_CalculationEnabled Integer
					 ,p_ReguiredAmountDEC  Number
					 ,p_ReguiredPercentDEC Number
					 ,p_ResiduaryAmount Number
                     ,P_INTPRECISION number
                     
           )
 Is
   RealLastProcessDate Date;
 Begin
    RealLastProcessDate :=p_LastProcessDate ;
    Insert  Into  SBCM_CONTRACT_STATE(
		              ID#
								 ,FacticalDebt
								 ,OverdueDebt
								 ,FacticalInterestDebt
								 ,OverdueInterestDebt
								 ,CloseDate
								 ,StopCalculationDate
								 ,LastProcessDate
								 ,CalculationEnabled
								 ,ReguiredAmountDEC
								 ,ReguiredPercentDEC
								 ,ResiduaryAmount	
                 ,LastFacticalDebt
                 ,LastOverdueDebt
		             )
                         			Values(
									 p_ID
									,p_FacticalDebt
									,p_OverdueDebt
									,p_FacticalInterestDebt
									,p_OverdueInterestDebt
									,p_CloseDate
									,p_StopCalculationDate
									,RealLastProcessDate
									,p_CalculationEnabled
									,p_ReguiredAmountDEC
									,p_ReguiredPercentDEC
									,p_ResiduaryAmount
                  ,p_FacticalDebt
                  ,p_OverdueDebt 	
									);
   -- commit;									 					 
 End;
 
Procedure  InsertInterests(
            InterestMode IN Integer
					 ,p_ID  IN Integer	
					 )
Is
  Idx Integer:=1;
Begin
  if  InterestMode = 0 then
	  while  Idx<=Interests.Count loop
		  AddInterest(p_ID,Interests(Idx).HDate,Interests(Idx).Percent);
		  Idx :=Idx + 1;
		end loop;
	else
	 while  Idx<=OInterests.Count loop
		  AddOverdueInterest(p_ID,OInterests(Idx).HDate,OInterests(Idx).Percent);
		  Idx :=Idx + 1;
		end loop;	
	end if;
End;					  
Procedure  AddInterest(
                     p_ID  Number
					,p_HDate Date
					,p_Interest Number
          )
 Is
 Begin
   Insert  Into  SBCM_INTERESTS(
	                      ID#
						 ,HDate
						 ,Interest	  
	           )
  		Values(
			  p_ID
			 ,p_HDate
			 ,p_Interest	 
			 );
		--commit;	 				 	 
 End;
Procedure  AddOverdueInterest(
                     p_ID  Number
					,p_HDate Date
					,p_OverdueInterest Number
          )
 Is
 Begin
   Insert  Into  SBCM_OVERDUEINTERESTS(
	            ID#
						 ,HDate
						 ,OverdueInterest	  
	           )
  		Values(
			  p_ID
			 ,p_HDate
			 ,p_OverdueInterest	 
			 );
		--commit;	 				 	 
 End;
Procedure  UpdateContract(
						p_ID   Number
     	     ,p_Type  Integer
             ,p_OpenDate Date
        	 ,p_CloseDate Date
        	 ,p_Amount  Number
        	 ,p_ContractNo VarChar2
        	 ,p_ContractType Integer
        	 ,p_PledgeType  Integer
        	 ,p_ReliabilityID  Integer
        	 ,p_ClientType  Number
	    	   ,p_PledgePrice Number
           ,p_OverdueReliabilityID Number
          )
 Is 
 Begin 
    Update SBCM_Contracts  Set
    		  Type# = p_Type
    		 ,Opendate = p_OpenDate
    		 ,CloseDate = p_CloseDate
    		 ,Amount = p_Amount
    		 ,ContractNo = p_ContractNo
    		 ,ContractType = p_ContractType
    		 ,PledgeType = p_PledgeType
				 ,ReliabilityID = p_ReliabilityID
				 ,ClientType = p_ClientType
				 ,PledgePrice = p_PledgePrice
         ,OverdueReliabilityID = p_OverdueReliabilityID
			Where 
			  ID = p_ID;
	 --commit;				 		 		
 End;
Procedure  UpdateContractAccounts(
             p_ID         Number
            ,p_ContractAccID  Number
  					,p_ClientAccID  Number
  					,p_ReserveAccID Number
  					,p_InterestAccID Number
  					,p_OverdueAccID  Number
  					,p_OverdueInterestAccID Number 
            ,p_OverdueReserveAccID  Number            
            )
 Is 
 Begin
    Update  SBCM_Contract_Accounts
		  Set
			  ContractAccID = p_ContractAccID
			 ,ClientAccID = p_ClientaccID
			 ,ReserveAccID = p_ReserveAccID
			 ,InterestAccID = p_InterestAccID
			 ,OverdueAccID = p_OverdueAccID
			 ,OverdueInterestAccID = p_OverdueInterestAccID
       ,OverdueReserveAccID = p_OverdueReserveAccID
			Where 
			  ID# = p_ID;
	 --commit;			  	
 End;				
