function  CheckCorrectly(Value IN  Number)
 return Number
  Is
	begin
	  if  Value = -1  then
		 return null;
		else
		 return Value;
	  end if;	  
	end;
	 
function  CheckAssigned(PercentMode IN Integer) 
return Boolean
Is
 RecCount Integer; 
begin
 if  PercentMode = 0  then
  RecCount :=Interests.Count;
 else
  RecCount :=OInterests.Count;
 end if;
 return  True;
 Exception  when OTHERS  then
 begin
   return False;
 end;		
end;
procedure 	UpdateingContract(
        p_ContractID Integer
       ,p_Type  Integer
	     ,p_OpenDate Date
			 ,p_CloseDate Date
			 ,p_Amount  Number
			 ,p_ContractNo VarChar2
			 ,p_ContractType Integer
			 ,p_PledgeType  Integer
			 ,p_ReliabilityID  Integer 
			 ,p_ClientType  Number  --addcontract
			 ,p_PledgePrice Number
			 
          ,p_ContractAccID  Number
    			,p_ClientAccID  Number
    			,p_ReserveAccID Number
    			,p_InterestAccID Number
    			,p_OverdueAccID  Number
    			,p_OverdueInterestAccID Number -- AddcontractAccounts
          ,p_OverdueReserveAccID Number
		  		
		      -- ,p_FacticalDebt Number  --AddContractState
				--	 ,p_OverdueDebt  Number
				--	 ,p_FacticalInterestDebt Number
				--	 ,p_OverdueInterestDebt Number
					 --,p_HCloseDate  Date                 -- !!!Actual Close Date!!!
					 ,p_StopCalculationDate Date
					 --,p_LastProcessDate  Date  --default null
					 --,p_CalculationEnabled Integer  --Is Calculation enabled 1 enabled 0 Disabled
					 ,p_ReguiredAmountDEC Number
					 ,p_ReguiredPercentDEC Number
           ,p_OverdueReliabilityID Number
          )
Is
Begin
SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm  
  UpdateContract(
        p_ContractID 
       ,p_Type  
	     ,p_OpenDate 
			 ,p_CloseDate 
			 ,p_Amount  
			 ,p_ContractNo 
			 ,p_ContractType 
			 ,p_PledgeType  
			 ,p_ReliabilityID  
			 ,p_ClientType
			 ,p_PledgePrice 
       ,p_OverdueReliabilityID 
	   );
 UpdateContractAccounts(
       p_ContractID
      ,p_ContractAccID  
    	,p_ClientAccID  
    	,p_ReserveAccID 
    	,p_InterestAccID
    	,p_OverdueAccID 
    	,p_OverdueInterestAccID
      ,p_OverdueReserveAccID     
     );
 UpdateContractState(
      p_ContractID
     ,p_StopCalculationDate 
  	 ,p_ReguiredAmountDEC 
  	 ,p_ReguiredPercentDEC
		 ,p_Amount 
     );
	DeleteInterests(p_ContractID);
	DeleteOverdueInterests(p_ContractID);
  InsertInterests(0,p_ContractID);
  InsertInterests(1,p_ContractID);
      update SBCM_CONTRACTS
    set
      BRANCHID = (select Filial from Account where ID = p_ContractAccID)
    where 
      ID = p_ContractID;

	commit;			 		 		 
End;								 		 			  		 					    					 					     					 			
END;
/

CREATE OR REPLACE 
PACKAGE sbcm_credit_tranches
IS
   PROCEDURE depositmoney (
      contractid       IN   sbcm_contracts.id%TYPE,
      hdate            IN   DATE,
      total            IN   NUMBER,
      PERCENT          IN   NUMBER,
      usetransaction   IN   BOOLEAN
   );

   PROCEDURE addtranch (
      contractid       IN   sbcm_contracts.id%TYPE,
      hdate            IN   DATE,
      total            IN   NUMBER,
      usetransaction   IN   BOOLEAN
   );
  function IfFirstTranch(ContractID in Integer)
   return 
     Boolean;
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sbcm_credit_tranches
IS

   function IfFirstTranch(ContractID in Integer)
   return 
     Boolean
   is
     tranchCount Integer;
     Result Boolean;
   begin
     select count(*) into tranchCount 
     from SBCM_Tranches
     where ID# = ContractID;
     if tranchCount = 0 then
     Result := TRUE;
     else
     Result :=FALSE;
     end if;
     return Result;     
   end;  
   
   PROCEDURE addtocollection (
      contractid   IN   sbcm_contracts.id%TYPE,
      p_hdate      IN   DATE,
      p_amount     IN   NUMBER,
      p_percent    IN   NUMBER
   )
   IS
   BEGIN
      INSERT INTO sbcm_collection
                  (id#, hdate, amount, PERCENT)
           VALUES (contractid, p_hdate, p_amount, p_percent);
   END;

   PROCEDURE updateresiduaryamount (
      contractid    IN   sbcm_contracts.id%TYPE,
      tranchtotal   IN   NUMBER
   )
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET residuaryamount =   residuaryamount
                               - tranchtotal
       WHERE id# = contractid;
   END;

   PROCEDURE setlastprocessdate (
      contractid   IN       sbcm_contracts.id%TYPE,
      tranchdate   IN OUT   DATE
   )
   IS
     CalcLeft Integer:=0;
   BEGIN
--      CalcLeft := sbcm_stored_programs.booltoint (sbcm_stored_programs.usingleft);
      
            
      UPDATE sbcm_contract_state
         SET lastprocessdate = tranchdate
       WHERE id# = contractid;

      
   END;

   FUNCTION checkcantranch (
      contractid    IN   sbcm_contracts.id%TYPE,
      tranchtotal   IN   NUMBER
   )
      RETURN BOOLEAN
   IS
      result            BOOLEAN;
      residuaryamount   NUMBER;
   BEGIN
      residuaryamount := sbcm_stored_programs.getresiduaryamount (contractid);
      result := (residuaryamount >= tranchtotal);
      RETURN result;
   END;

   PROCEDURE inserttranch (
      p_id        IN   sbcm_contracts.id%TYPE,
      p_hdate     IN   sbcm_tranches.hdate%TYPE,
      p_total     IN   NUMBER,
      p_reserve   IN   NUMBER
   )
   IS
   BEGIN
      INSERT INTO sbcm_tranches
                  (id#, hdate, total, reserve)
           VALUES (p_id, p_hdate, p_total, p_reserve);
   END;

   PROCEDURE customerdebtincrease (
      contractid   IN   sbcm_contracts.id%TYPE,
      increaseby   IN   NUMBER
   )
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET lastfacticaldebt = facticaldebt,
             facticaldebt =   facticaldebt
                            + increaseby
       WHERE id# = contractid;
   END;

   PROCEDURE addtranch (
      contractid       IN   sbcm_contracts.id%TYPE,
      hdate            IN   DATE,
      total            IN   NUMBER,
      usetransaction   IN   BOOLEAN
   )
   IS
      credittransid         NUMBER;
      reservetransid        NUMBER;
      contractaccid         ACCOUNT.id%TYPE;
      clientaccid           ACCOUNT.id%TYPE;
      reserveaccid          ACCOUNT.id%TYPE;
      outcomereserveaccid   ACCOUNT.id%TYPE;
      dcurrency             avalute.valute%TYPE;
      ccurrency             avalute.valute%TYPE;
      debtamount            NUMBER (15, 2);
      creditamount          NUMBER (15, 2);
      reserveamount         NUMBER (15, 2);
      lamount               NUMBER (15, 2);
      reliabilitypercent    NUMBER (15, 2);
      bankyeardays          INTEGER;
      tranchdate            DATE;
      contractnum           VARCHAR2 (256);
      cashsymbol            integer;
   BEGIN
   SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
      IF NOT checkcantranch (contractid, total)
      THEN
         raise_application_error (
            sbcm_exceptions.etrancherror,
            'Tranch Total Must Be Less Than Resuduary Amount!'
         );
      END IF;
      IF usetransaction
      THEN
         contractnum :=
                      sbcm_stored_programs.contractnumasvarchar2 (contractid);
         contractaccid := sbcm_stored_programs.getcontractaccid (contractid);
         clientaccid := sbcm_stored_programs.getclientaccid (contractid);
         reserveaccid := sbcm_stored_programs.getreserveaccid (contractid);
         outcomereserveaccid :=
               sbcm_stored_programs.getselectedaccid (
                  contractid,
                  'outComeAccForReserve'
               );
         dcurrency :=
                    sbcm_stored_programs.getaccountcurrencyid (contractaccid);
         ccurrency := sbcm_stored_programs.getaccountcurrencyid (clientaccid);

         --Contract Conclusion in one Currncy!
         
         cashsymbol := sbcm_stored_programs.getcashsymbolifexsist('cmrCahsSymbolOnTransh',clientaccid);          

         IF dcurrency <> ccurrency
         THEN
            debtamount := total;
            creditamount := NULL;
         ELSE
            debtamount := total;
            creditamount := total;
         END IF;

         lamount := NULL;
         reliabilitypercent :=
                       sbcm_stored_programs.getreliabilitypercent (contractid);
         bankyeardays := sbcm_stored_programs.getreference ('cmrYearDayCount');
         reserveamount := sbcm_stored_programs.ReserveInNational(
                                               hdate ,
                                               total ,
                                               ContractID ,
                                               reliabilitypercent
                                               );
         credittransid :=
               sb_transaction.transaction_add (
                  debitid=> contractaccid,
                  creditid=> clientaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> lamount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    ' редит “ранщы є '
                           || contractnum,
                  flags => 0,
                  transactiondate=> tranchdate ,
                  InBalanceChar => cashsymbol
               );
         reservetransid :=
               sb_transaction.transaction_add (
                  debitid=> outcomereserveaccid,
                  creditid=> reserveaccid,
                  debitamount=> reserveamount,
                  creditamount=> NULL,
                  lamount=> NULL,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    '“ранщ заманы ещтиййата пул кючцлм€си є '
                           || contractnum,
                  flags => 0,
                  transactiondate=> tranchdate
               );
      END IF; --Use Transactions

      tranchdate := hdate;
      customerdebtincrease (contractid, total);      
      updateresiduaryamount (contractid, total);
      setlastprocessdate (contractid, tranchdate);      
      inserttranch (contractid, tranchdate, total, reserveamount);      
      COMMIT;
   END;

   PROCEDURE depositmoney (
      contractid       IN   sbcm_contracts.id%TYPE,
      hdate            IN   DATE,
      total            IN   NUMBER,
      PERCENT          IN   NUMBER,
      usetransaction   IN   BOOLEAN
   )
   IS
      debtaccid          INTEGER;
      creditaccid        INTEGER;
      damount            NUMBER (18, 2);
      camount            NUMBER (18, 2);
      deposittransid     INTEGER;
      depositmoneydate   DATE           := hdate;
      contractnum        VARCHAR2 (256);
      firstpercent       NUMBER (7, 2);
   BEGIN
   SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
      IF usetransaction
      THEN
         contractnum :=
                      sbcm_stored_programs.contractnumasvarchar2 (contractid);
         debtaccid := sbcm_stored_programs.getclientaccid (contractid);
         creditaccid := sbcm_stored_programs.getcontractaccid (contractid);
         damount := total;
         camount := NULL;
         deposittransid :=
               sb_transaction.transaction_add (
                  debitid=> debtaccid,
                  creditid=> creditaccid,
                  debitamount=> damount,
                  creditamount=> camount,
                  lamount=> NULL,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    'ƒепозит ўесабына пул дахил олур є '
                           || contractnum,
                  flags => 0,
                  transactiondate=> hdate
               );
      END IF;

      firstpercent := sbcm_stored_programs.getpercent (contractid);

      IF firstpercent = PERCENT
      THEN
         customerdebtincrease (contractid, total);
      ELSE
         addtocollection (contractid, hdate, total, PERCENT);
      END IF;
      inserttranch (contractid, hdate, total, PERCENT);
      
      UPDATE sbcm_contract_state
      SET lastprocessdate = depositmoneydate
      WHERE id# = contractid;

      COMMIT;
   END;
   
END;
/

