CREATE OR REPLACE 
PACKAGE sbcm_expire
  IS
 procedure  ExpireInterestDebts(
                  ContractID IN SBCM_Contracts.ID%type
                 ,Total IN Number 
                 );
  Procedure  AddExpire(
            ContractID in SBCM_Contracts.ID%type
					 ,HDate in date	
					 ,FacticalDebt     in number
           ,ExpiredDebt      in number
           ,ReserveID        in integer
           ,ExpiredReserveID in integer	
           ,ChangeReserve        in boolean
           ,ChangeExpiredReserve in boolean
           ,TransactionsON       in boolean           
           );
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sbcm_expire
IS
procedure  ExpireContractDebts(
               ContractID IN  SBCM_Contracts.ID%type
							,Value IN Number 
							)
 Is
 begin
   Update SBCM_Contract_State
	 Set
	   FacticalDebt = FacticalDebt - Value ,
		 OverdueDebt  = OverdueDebt  + Value
	 Where 
	   ID# = ContractID;	  
 end;
Procedure  InsertExpires(
            ContractID IN SBCM_Contracts.ID%type
					 ,p_HDate IN Date		
					 ,p_Amount IN Number	
           )
 Is
 begin 
    Insert Into  SBCM_Expires(
		              ID#
								 ,HDate								
								 ,Amount	
		             )
								Values(
								 ContractID
								,p_HDate								
								,p_Amount  
								); 
 end;					  
function   CheckCanExpire(
              ContractID IN SBCM_Contracts.ID%type
						 ,Value in number
             ,CheckParam in boolean
						 )
return Boolean						 
 is
   Result Boolean;
 begin
   if  CheckParam then
   Result :=(SBCM_Stored_Programs.GetFacticalDebt(ContractID)>=Value);
   else
   Result :=(SBCM_Stored_Programs.GetOverdueDebt(ContractID)>=Value);
   end if;   			 	   
   return Result;
 end;
 						  
 Procedure  AddExpire(
            ContractID in SBCM_Contracts.ID%type
					 ,HDate in date	
					 ,FacticalDebt     in number
           ,ExpiredDebt      in number
           ,ReserveID        in integer
           ,ExpiredReserveID in integer	
           ,ChangeReserve        in boolean
           ,ChangeExpiredReserve in boolean
           ,TransactionsON       in boolean           
           )
					 
 Is	 
	 Debit    integer;
	 Credit  integer;   
	 TransID integer;       
	 OutReserveTransID integer;
   InReserveTransID  integer;         
   TransactionDesc varchar2(64) :=' редитин юд€нилм€си эежикдирилмишдир є ';      	
 begin
 SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
  if  FacticalDebt > 0  then
  if  not CheckCanExpire(
    	      ContractID
    			 ,FacticalDebt
           ,TRUE
    	     ) then
	raise_application_error(
		       SBCM_EXCEPTIONS.EExpireError
					,' Expired amount must be less than debt.'
					);          				 
	end if;
  if ChangeExpiredReserve then
  sbcm_reserve_cont.ChangeSecondaryReserve(
                    ContractID , 
                    HDate ,
                    ReserveID ,
                    FacticalDebt , 
                    TransactionsON ,
                    OutReserveTransID ,
                    InReserveTransID ,
                    FALSE
                    );
  end if;
  if ChangeReserve then  
  sbcm_reserve_cont.ChangePrimaryReserve(
                    ContractID , 
                    HDate ,
                    ExpiredReserveID ,
                    -FacticalDebt , 
                    TransactionsON ,
                    OutReserveTransID ,
                    InReserveTransID ,
                    FALSE
                    );
  end if;  
  Debit := sbcm_stored_programs.getcontractaccid(ContractID);
  Credit := sbcm_stored_programs.getoverdueaccid(ContractID);
  
  expireContractDebts(ContractID,FacticalDebt);
                          
  elsif ExpiredDebt > 0 then
  if  not CheckCanExpire(
    	      ContractID
    			 ,ExpiredDebt
           ,FALSE
    	     ) then
	raise_application_error(
		       SBCM_EXCEPTIONS.EExpireError
					,' Returned amount must be less than expired debt.'
					);          				 
	end if;
  if ChangeExpiredReserve then  
  sbcm_reserve_cont.ChangeSecondaryReserve(
                    ContractID , 
                    HDate ,
                    ExpiredReserveID ,
                    -ExpiredDebt , 
                    TransactionsON ,
                    OutReserveTransID ,
                    InReserveTransID ,
                    FALSE
                    );
  end if;
  if ChangeReserve then
  sbcm_reserve_cont.ChangePrimaryReserve(
                    ContractID , 
                    HDate ,
                    ReserveID ,
                    ExpiredDebt , 
                    TransactionsON ,
                    OutReserveTransID ,
                    InReserveTransID ,
                    FALSE
                    );
  end if;  
  Debit := sbcm_stored_programs.getoverdueaccid(ContractID); 
  Credit := sbcm_stored_programs.getcontractaccid(ContractID);
  expireContractDebts(ContractID , -ExpiredDebt);                        
  end if;
  
  if  TransactionsON  then
  TransactionDesc := TransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);
  TransID := 
  SB_TRANSACTION.Transaction_Add(
		                  DebitID      => Credit
            				 ,CreditID     => Debit
            				 ,DebitAmount  => FacticalDebt
            				 ,CreditAmount => null
            				 ,LAmount      => null
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => TransactionDesc
            				 ,Flags        => 0
            				 ,TransactionDate =>HDate
		                 );  
  end if;
  
  commit;
        
 end;
 
procedure  ExpireInterestDebts(
                  ContractID IN SBCM_Contracts.ID%type
                 ,Total IN Number 
                 )
is
begin
   update SBCM_Contract_State
   set
     FacticalInterestDebt = FacticalInterestDebt - Total
    ,OverdueInterestDebt  = OverdueInterestDebt  + Total
   where 
      ID# = ContractID;    
end;                   					  
END;
/

CREATE OR REPLACE 
PACKAGE sbcm_exports
  IS    
	     /*  Smart Credit Managment  */
	
  cursor  AccountRestExporter(AccID Account.ID%type,HDate Date) is
  Select
     Ostat
  	 ,Pok_Ostat From Archost
  Where   Acc_ID = AccID
	   	 and DatDate=HDate;
			  
  cursor  PercentsExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select 
	  HDate
	 ,Interest From SBCM_Interests
	Where ID# = ContractID;
	
	cursor  ResiduaryAmountOfContract(ContractID IN SBCM_Contracts.ID%type) is
	Select
	   ResiduaryAmount From SBCM_Contract_State
	Where ID# = ContractID;	 
	
	cursor  OverduePercentsExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select
	  HDate
	 ,OverdueInterest From SBCM_OverdueInterests
	Where ID# = ContractID;	  
	 	 	 
	cursor  OpenDateOfContract(p_ID IN Number) is
	Select
	  OpenDate From SBCM_Contracts
	Where ID = p_ID;
		
	cursor  LastDateExporter(p_ID IN SBCM_Contracts.ID%type) is
  Select
    CloseDate From SBCM_Contracts
  Where  ID = p_ID;	 	  
	
	cursor  CostOfContract(ContractID IN SBCM_Contracts.ID%type) is
	Select  
	   Amount  From  SBCM_Contracts
	 Where  ID = ContractID;
	 
	cursor  CurrentDebtsOfContract(ContractID IN SBCM_Contracts.ID%type) is
	Select
	   FacticalDebt
		,OverdueDebt
		,FacticalInterestDebt
		,OverdueInterestDebt From SBCM_Contract_State
	Where  ID# = ContractID;
	 	 
	cursor  ContractAccounts(ContractID IN SBCM_Contracts.ID%type) is
	Select
	   ContractAccID
		,ClientAccID
		,ReserveAccID
		,InterestAccID
		,OverdueAccID
		,OverdueInterestAccID
    ,OverdueReserveAccID From  SBCM_Contract_Accounts	
	Where  ID# = ContractID;
	
	cursor  ContractCurrency(ContractID IN SBCM_Contracts.ID%type) is
	Select
  	  Val_Acc
		 From   SBCM_Contract_Accounts ContractAccs
		       ,Account    Accs
	Where 
	        ContractAccs.ID# =ContractID  
	   and  Accs.ID = ContractAccs.ContractAccID;
	
	cursor  AccountNoExporter(AccID IN  Account.ID%type) is
	Select
	   Acc_No  From  Account
	Where  ID = AccID;
	
	cursor  CurrencyShortNameExporter(AccID IN  Account.ID%type) is
	Select
	   Av.Val_Name From Account Ac,Avalute Av
	Where  Ac.ID = AccID
	   and Av.Valute = Ac.Val_Acc;	 		 
	
	cursor  AccountNameExporter(AccID IN Account.ID%type) is
	Select
	  Name From Account
	Where  ID = AccID;					  	
	
	cursor  ContractClientCategoryExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select
	  ClientType From SBCM_Contracts
	Where  ID = ContractID;	
	
	cursor MovieNamesExporter(
	          p_TypeID IN SBCM_Movie_Names.TypeID%type
					 ,MovieName IN SBCM_Movie_Names.Name%type	
					 ) is
  Select
	   ID From  SBCM_Movie_Names
	Where 
	    TypeID = p_TypeID
	and Name = MovieName;
	
	cursor  SettingsExporter(
	        p_ParentID IN SBCM_Settings.ParentID%type
				 ,p_CurrencyID IN SBCM_Settings.CurrencyID%type	
	       ) is
	Select
	   AccID From SBCM_Settings
  Where  
	    ParentID = p_ParentID
  and CurrencyID = p_CurrencyID;  		 			 			 
	
	Cursor LastProcessDateExporter(ContractID IN SBCM_Contracts.ID%type) is
  Select
	  LastProcessDate From SBCM_Contract_State
	Where ID# = ContractID;
	
	cursor ReferenceExporter(ReferName IN VarChar2) is
	Select
	 Value From SBCM_References 
	Where Name = ReferName;
	
	cursor CalculationEnabledExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select
	  CalculationEnabled From SBCM_Contract_State
	Where ID# = ContractID;	  
	
	cursor CurrencyIDExporter(AccID IN Account.ID%type) is
	Select
	  Val_Acc From Account
	Where  ID = AccID;
	
	cursor  ContractReliabilityExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select
	  Reliabilitys.Percent 
		From SBCM_Contracts Contracts,SBCM_Reliability Reliabilitys
	Where (Contracts.ID = ContractID)
		And	(Reliabilitys.ID = Contracts.ReliabilityID);		
	
	cursor  PercentExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select
	  Interest From SBCM_Interests
	Where  ID# = ContractID;	
	
	cursor  OverduePercentExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select
	  OverdueInterest From SBCM_OverdueInterests
	Where  ID# = ContractID;
    
  cursor  HistoryExporter(ContractID IN SBCM_Contracts.ID%type,HDate# IN Date) is
  Select
    ID From SBCM_State_History
  Where  ID# = ContractID and HDate = HDate#;     
	
  cursor  ReliabilityPercentExporter(ReliabilityID IN Integer) is
  Select
    Percent From SBCM_Reliability
  Where  ID = ReliabilityID;
  
  cursor  AdditionalDepositTypeExporter(ContractID IN Integer) is
  Select
    AdditionalType From SBCM_Deposit_Types
  Where 
     ID = (
           Select 
             ContractType From SBCM_Contracts
           Where  ID = ContractID              
           );  

  cursor  CollectionExporter(ContractID IN SBCM_Contracts.ID%type) is
  Select
    Amount,Percent From SBCM_Collection
  Where ID# = ContractID;               
  
  cursor  StopCalculationDateExporter(ContractID IN SBCM_Contracts.ID%type) is
  Select
    StopCalculationDate From SBCM_Contract_State
  Where ID# = ContractID;  
  
  cursor  CreditTypeExporter (ContractID in integer) is
  Select
    AdditionalType 
  From  SBCM_Credit_Types
  Where  ID = (
                Select
                  CONTRACTTYPE
                From SBCM_Contracts
                Where ID = ContractID   
                );
                
  cursor  AdditionalDepositTypeExporterA(ContractID IN Integer) is
  Select
    WithdrawType From SBCM_Deposit_Types
  Where 
     ID = (
           Select 
             ContractType From SBCM_Contracts
           Where  ID = ContractID              
           );
  
  cursor  DepositWCDateIntervalExporter(ContractID IN Integer) is
  Select
    DateInterval From SBCM_Deposit_Types
  Where 
     ID = (
           Select 
             ContractType From SBCM_Contracts
           Where  ID = ContractID              
           );

  cursor  LastProlongationExporter(ContID SBCM_Contracts.ID%type) is
	Select
	  ID	 
	 ,HDate 
  From  SBCM_Prolongations
	Where
	  ID = 	
	(Select
	  Max(ID) From  SBCM_Prolongations
	 Where 
	   ID# = ContID);				

 	cursor  OverdueReliabilityExporter(ContractID IN SBCM_Contracts.ID%type) is
	Select
	  Reliabilitys.Percent 
		From SBCM_Contracts Contracts,SBCM_Reliability Reliabilitys
	Where (Contracts.ID = ContractID)
		And	(Reliabilitys.ID = Contracts.OverdueReliabilityID);		

  cursor LastFacticalDebtExporter(ContractID in SBCM_Contracts.ID%type) is
  select 
    LastFacticalDebt 
  from SBCM_Contract_State
  where ID# = ContractID;  

  cursor LastOverdueDebtExporter(ContractID in SBCM_Contracts.ID%type) is
  select 
    LastOverdueDebt 
  from SBCM_Contract_State
  where ID# = ContractID;
    
  cursor AllContracts is
  select
        ID
      , Contracts.ReliabilityID
      , Contracts.OverdueReliabilityID
      , State.FacticalDebt
      , State.FacticalInterestDebt
      , State.OverdueDebt
      , State.OverdueInterestDebt 
  from 
      SBCM_Contracts  Contracts ,
      SBCM_Contract_State State 
  where 
      Contracts.ID = State.ID#
      and Contracts.type# in 
      (select 
         ID 
       from 
         SBCM_Contract_Types
       where 
         upper(Name) in ('CREDIT','DEPOSIT'))   
       order by 
          Contracts.ID;
          
    cursor c_CalcedInterests(p_ID in integer) is
    SELECT  hdate, interest, overdureinterest, intprecision,
       dueintprecision, inttrid, dueinttrid, withdrawtrid
    FROM sbcm_deposit_interests    
    where id# = p_ID;          
  
END; -- Package spec
/

