CREATE OR REPLACE 
PACKAGE BODY sbcm_payment
IS

procedure  SetResiduaryAmount(
               ContractID in SBCM_Contracts.ID%type
              ,Amount in number 
              )
is
begin
  update sbcm_contract_state
  set
    ResiduaryAmount = ResiduaryAmount + Amount
  where 
    ID# = ContractID;   
end;

function  IsCreditLine(ContractID in SBCM_Contracts.ID%type)
return Boolean
is      
  Result varchar2(32);
  ResultRow SBCM_EXPORTS.CreditTypeExporter%rowtype; 
begin
  open SBCM_EXPORTS.CreditTypeExporter(ContractID);
  fetch SBCM_EXPORTS.CreditTypeExporter into ResultRow;
  close SBCM_EXPORTS.CreditTypeExporter;
  
  Result := ResultRow.AdditionalType;  
  return (lower(Result) = 'line');
end;
							
Procedure  InsertPayments(
            p_ID IN SBCM_Contracts.ID%type
					 ,p_HDate IN Date
					 ,p_FacticalDebt IN Number
					 ,p_InterestDebt IN Number
					 ,p_OverdueDebt IN Number
					 ,p_OverdueInterestDebt IN Number 	
           )
 Is
 begin
   Insert Into  SBCM_Payments(
	                ID#
								 ,HDate
								 ,FacticalDebt
								 ,InterestDebt
								 ,OverdueDebt
								 ,OverdueInterestDebt	
	               )
				       	Values(
								  p_ID
								 ,p_HDate
								 ,p_FacticalDebt
								 ,p_InterestDebt
								 ,p_OverdueDebt
								 ,p_OverdueInterestDebt	
					       );
								 			 
 end;
procedure  InitPayments(
            ContractID IN SBCM_Contracts.ID%type
					 ,FacticalDebtPayment IN Number
					 ,OverdueDebtPayment  IN Number
					 ,InterestDebtPayment IN Number					 
					 ,OverdueInterestDebtPayment IN Number	 
           )
 Is
 begin
    -- if Transactions  then
		Update  SBCM_Contract_State
		Set
      LastFacticalDebt = FacticalDebt
     ,LastOverdueDebt  = OverdueDebt 
		 ,FacticalDebt = FacticalDebt - FacticalDebtPayment
		 ,OverdueDebt = Overduedebt - OverdueDebtPayment	
		 ,FacticalInterestDebt = FacticalInterestDebt - InterestDebtPayment		 
		 ,OverdueInterestDebt = OverdueInterestDebt - OverdueInterestdebtPayment
		Where ID# = ContractID; 		   	 
 end;
 			
Function   CheckCanPayment( 
            ContractID IN SBCM_Contracts.ID%type
					 ,FacticalDebtPayment IN Number
					 ,OverdueDebtPayment  IN Number
					 ,InterestDebtPayment IN Number					 
					 ,OverdueInterestDebtPayment IN Number
					 )
 return  Boolean
 Is
   Result Boolean;
 begin
   Result :=
	      (SBCM_Stored_Programs.GetFacticalDebt(ContractID)>=FacticalDebtPayment)
		 And(SBCM_Stored_Programs.GetOverdueDebt(ContractID)>=OverdueDebtPayment)
		 And(SBCM_Stored_Programs.GetFacticalInterestDebt(ContractID)>=InterestDebtPayment)
		 And(SBCM_Stored_Programs.GetOverdueInterestDebt(ContractID)>=OverdueInterestDebtPayment);		

  return  Result;	          
 end;
procedure   GetClientRest(
                ContractID IN SBCM_Contracts.ID%type
							 ,HDate   IN Date
							 ,Rest IN OUT Archost.Ostat%type 
							 ,NationalRest IN OUT Archost.Pok_Ostat%type 
							 ) 
Is 	  	
Begin

 open SBCM_Exports.AccountRestExporter(
        SBCM_Stored_Programs.GetClientAccID(ContractID)
			 ,HDate	
			 );
			 
		Fetch  SBCM_Exports.AccountRestExporter		       
					    Into Rest,NationalRest;			 
 close SBCM_Exports.AccountRestExporter;
 			  
end;
 							   
procedure  AddPayment(
            ContractID IN SBCM_Contracts.ID%type
					 ,HDate  IN Date
					 ,FacticalDebtPayment IN Number
					 ,OverdueDebtPayment  IN Number
					 ,InterestDebtPayment IN Number					 
					 ,OverdueInterestDebtPayment IN Number
           ,UseTransaction IN Boolean
           ) 
					 
  Is
						
		ContractAccID Number;
		ClientAccID   Number;
		ReserveAccID  Number;
		InterestAccID Number;
		OverdueAccID  Number;
		OverdueInterestAccID Number;
		outComeReserveAccID  Number;
								
		DAmount Number(17,2);
		CAmount Number(17,2);		
		LAmount Number(17,2);
		
    FacticalTransID Number :=-1;
		InterestTransID Number :=-1;
		OverdueTransID  Number :=-1;
		OverdueInterestTransID Number :=-1;
		ReserveTransID Number :=-1;
		
		DCurrency Integer;
		CCurrency Integer;
		
		ReliabilityPercent SBCM_Reliability.Percent%type;
    ContractNum  Varchar2(256);
    cashsymbol integer; 		
	begin
	 SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm	  		  
		 if  not CheckCanPayment(
            ContractID 
					 ,FacticalDebtPayment 
					 ,OverdueDebtPayment  
					 ,InterestDebtPayment 					 
					 ,OverdueInterestDebtPayment 
		    )  then
		 RAISE_APPLICATION_ERROR(
            SBCM_EXCEPTIONS.EPaymentError
           ,'Payment Must Be Less Than Debt!^'
           );
		end if;
    
    ContractNum := SBCM_STORED_PROGRAMS.ContractNumAsVarchar2(ContractID);
    
    if UseTransaction then
    
		ClientAccID   :=SBCM_Stored_Programs.GetClientAccID(ContractID);
    DCurrency :=SBCM_Stored_Programs.GetAccountCurrencyID(ClientAccID);
    cashsymbol := sbcm_stored_programs.getcashsymbolifexsist('cmrCashSymbolsOnMainDebtPayment',clientaccid);          
		
		if FacticalDebtPayment>0 then
    
			ContractAccID :=SBCM_Stored_Programs.GetContractAccID(ContractID);    
			CCurrency :=SBCM_Stored_Programs.GetAccountCurrencyID(ContractAccID);     	 	      
      
  		if  DCurrency<>Ccurrency then		
   		  DAmount :=null;
   		  CAmount :=FacticalDebtPayment;
   		else
   		  DAmount :=FacticalDebtPayment;
   		  CAmount :=FacticalDebtPayment;
   		end if;																				 			  			
			
			LAmount :=null;
			
			FacticalTransID :=SB_TRANSACTION.Transaction_Add(
		                  DebitID      => ClientAccID
            				 ,CreditID     => ContractAccID
            				 ,DebitAmount  => DAmount
            				 ,CreditAmount => CAmount
            				 ,LAmount      => LAmount
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => ' редитл€рд€ €сас боржун юд€нилм€си є '||ContractNum
            				 ,Flags        => 0
            				 ,TransactionDate => HDate
                     ,InBalanceChar => cashsymbol
		                 );				
    
 		  ReserveAccID  :=SBCM_Stored_Programs.GetReserveAccID(ContractID);      
			outComeReserveAccID  :=SBCM_Stored_Programs.GetSelectedAccID(
		                                              ContractID
		                                             ,'outComeAccForReserve'
																								 );
																											 											 
	  ReliabilityPercent :=SBCM_Stored_Programs.GetReliabilityPercent(ContractID);    
    DAmount := sbcm_stored_programs.reserveinnational(
                                    hdate ,
                                    FacticalDebtPayment ,
                                    ContractID ,
                                    ReliabilityPercent
                                    );    
    CAmount :=null;
		
		ReserveTransID :=SB_TRANSACTION.Transaction_Add(
		                  DebitID      => ReserveAccID
            				 ,CreditID     => outComeReserveAccID
            				 ,DebitAmount  => DAmount
            				 ,CreditAmount =>	CAmount
            				 ,LAmount      => LAmount
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => ' редитл€рд€ €сас боржун юд€нилм€си заманы ещтиййатын азалдылмасы є '||ContractNum
            				 ,Flags        => 0
            				 ,TransactionDate => HDate
		                 );				
                     
		end if;   
		
		if  OverdueDebtPayment>0 then
		
	    OverdueAccID  :=SBCM_Stored_Programs.GetOverdueAccID(ContractID);
			CCurrency :=SBCM_Stored_Programs.GetAccountCurrencyID(OverdueAccID);
      cashsymbol := sbcm_stored_programs.getcashsymbolifexsist('cmrCashSymbolsOnOverdueDebtPayment'
                    ,clientaccid
                    );      
  		if DCurrency<>CCurrency then	 			
  	  	DAmount :=null;		
	  		CAmount :=OverdueDebtPayment;
			else
			  DAmount :=OverdueDebtPayment;		
	  		CAmount :=OverdueDebtPayment;
			end if;
      		
			LAmount :=null;
	    	
			OverdueTransID :=SB_TRANSACTION.Transaction_Add(
		                  DebitID      => ClientAccID
            				 ,CreditID     => OverdueAccID
            				 ,DebitAmount  => DAmount
            				 ,CreditAmount => CAmount
            				 ,LAmount      => LAmount
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => ' редитл€рд€ эежикмиш боржунцн юд€нилм€си  є '||ContractNum
            				 ,Flags        => 0
            				 ,TransactionDate => HDate
                     ,InBalanceChar => cashsymbol                     
		                 );
   
    ReserveAccID  :=SBCM_Stored_Programs.GetReserveAccID(ContractID);      
		outComeReserveAccID  :=SBCM_Stored_Programs.GetSelectedAccID(
		                                              ContractID
		                                             ,'outComeAccForExpReserve'
																								 );
																											 											 
	  ReliabilityPercent :=SBCM_Stored_Programs.GetOverdueReliabilityPercent(ContractID);    
    DAmount :=sbcm_stored_programs.reserveinnational(
                                    hdate ,
                                    OverdueDebtPayment ,
                                    ContractID ,
                                    ReliabilityPercent
                                    );    
    CAmount :=null;
		
		ReserveTransID :=SB_TRANSACTION.Transaction_Add(
		                  DebitID      => ReserveAccID
            				 ,CreditID     => outComeReserveAccID
            				 ,DebitAmount  => DAmount
            				 ,CreditAmount =>	CAmount
            				 ,LAmount      => LAmount
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => ' редитл€рд€ ьежикдирилмиш боржун юд€нилм€си заманы ещтиййатын азалдылмасы є '||ContractNum
            				 ,Flags        => 0
            				 ,TransactionDate => HDate
		                 );				
                                       
		end if;
		
		if  InterestDebtPayment>0 then
    
      cashsymbol := sbcm_stored_programs.getcashsymbolifexsist('cmrCashSymbolsOnPercentPayment'
                    ,clientaccid
                    );      
		
  		InterestAccID :=SBCM_Stored_Programs.GetInterestAccID(ContractID);
			CCurrency :=SBCM_Stored_Programs.GetAccountCurrencyID(InterestAccID);
      
			if DCurrency<>CCurrency then 
  		  DAmount :=null;
	  		CAmount :=InterestDebtPayment;
			else
			  DAmount :=InterestDebtPayment;
	  		CAmount :=InterestDebtPayment;
			end if;
      	
			LAmount :=null;
			
			InterestTransID :=SB_TRANSACTION.Transaction_Add(
    		                  DebitID      => ClientAccID
                				 ,CreditID     => InterestAccID
                				 ,DebitAmount  => DAmount
                				 ,CreditAmount =>	CAmount
                				 ,LAmount      => LAmount
                				 ,DebitRate    => 0
                				 ,CreditRate   => 0
                				 ,TrName       => ' редитл€рд€ €сас борж цзр€ фаизин юд€нилм€си  є '||ContractNum
                				 ,Flags        => 0
                				 ,TransactionDate => HDate
                         ,InBalanceChar => cashsymbol                         
    		                  );					
		end if;
    
		if OverdueInterestDebtPayment>0 then
    
      cashsymbol := sbcm_stored_programs.getcashsymbolifexsist('cmrCashSymbolsOnPercentPayment'
                    ,clientaccid
                    );      
    
      OverdueInterestAccID :=SBCM_Stored_Programs.GetOverdueInterestAccID(ContractID);
			CCurrency :=SBCM_Stored_Programs.GetAccountCurrencyID(OverdueInterestAccID);
      
			if DCurrency<>CCurrency then		  
  			DAmount :=null;
	  		CAmount :=OverdueInterestDebtPayment;
			else
			  DAmount :=OverdueInterestDebtPayment;
	  		CAmount :=OverdueInterestDebtPayment;
			end if; 	
      
			LAmount :=null;			
			
				OverdueInterestTransID :=SB_TRANSACTION.Transaction_Add(
		                  DebitID      => ClientAccID
            				 ,CreditID     => OverdueInterestAccID
            				 ,DebitAmount  => DAmount
            				 ,CreditAmount => CAmount
            				 ,LAmount      => LAmount
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => ' редитл€рд€ эежикмиш боржц цзр€ фаизин юд€нилм€си  є '||ContractNum
            				 ,Flags        => 0
            				 ,TransactionDate => HDate
                     ,InBalanceChar => cashsymbol                     
		                 );
		end if;
    
    end if;  --UseTransaction
    
        if  IsCreditLine(ContractID)  then
          SetResiduaryAmount(ContractID ,FacticalDebtPayment);
        end if;             

       
		InsertPayments(
    		 ContractID
    		,HDate
    		,FacticalDebtPayment   
    		,InterestDebtPayment 
        ,OverdueDebtPayment        					 
    		,OverdueInterestDebtPayment 
    		);
		
		InitPayments(
		 ContractID
		,FacticalDebtPayment 
    ,OverdueDebtPayment  
		,InterestDebtPayment 					 
		,OverdueInterestDebtPayment 
		);
    		
	 commit;
	 		
	end;

Procedure  WithDrawMoney(
            ContractID IN SBCM_Contracts.ID%type
           ,HDate IN Date 
           ,FacticalDebtWithdraw IN Number
           ,InterestDebtWithdraw IN Number
           ,UseTransactions IN Boolean
           )
Is
  DepositAccID  Integer;
  ClientAccID   Integer;
  InterestAccID Integer;
  
  DAmount  Number(18,2);
  CAmount  Number(18,2);
  LAmount  Number(18,2) :=null;
  
  TransactionID Integer;
  ContractNum Varchar2(256);
Begin
  SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
		 if  not CheckCanPayment(
            ContractID 
					 ,FacticalDebtWithDraw 
					 ,0  
					 ,InterestDebtWithdraw 					 
					 ,0 
		    )  then
		 RAISE_APPLICATION_ERROR(
            SBCM_EXCEPTIONS.EPaymentError
           ,'%Payment Must Be Less Than Debt!'
           );
		end if;
	
  if UseTransactions then
  ClientAccID  :=SBCM_STORED_PROGRAMS.GetClientAccID(ContractID);  
  ContractNum := SBCM_STORED_PROGRAMS.ContractNumAsVarchar2(ContractID);  
  if  FacticalDebtWithDraw<>0 then
  
    DepositAccID :=SBCM_STORED_PROGRAMS.GetContractAccID(ContractID);
    DAmount :=FacticalDebtWithDraw;
    CAmount :=FacticalDebtWithDraw;
    LAmount :=null;
    TransactionID :=SB_TRANSACTION.Transaction_Add(
		                  DebitID      => DepositAccID
            				 ,CreditID     => ClientAccID
            				 ,DebitAmount  => DAmount
            				 ,CreditAmount => CAmount
            				 ,LAmount      => LAmount
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => 'ƒепозит  кючрцлцр є '||ContractNum
            				 ,Flags        => 0
            				 ,TransactionDate => HDate
		                 );
  end if;
  
  if  InterestDebtWithdraw<>0 then
  
    InterestAccID:=SBCM_STORED_PROGRAMS.GetInterestAccID(ContractID);  
    DAmount :=InterestDebtWithdraw;
    CAmount :=InterestDebtWithdraw;
    LAmount :=null;
    TransactionID :=SB_TRANSACTION.Transaction_Add(
		                  DebitID      => InterestAccID
            				 ,CreditID     => ClientAccID
            				 ,DebitAmount  => DAmount
            				 ,CreditAmount => CAmount
            				 ,LAmount      => LAmount
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => 'ƒепозит цзр€ 30 эцнлцк фаиз жари щесаба кючрцлцр  є '||ContractNum
            				 ,Flags        => 0
            				 ,TransactionDate => HDate
		                 );
  update sbcm_deposit_interests 
  set WITHDRAWTRID = TransactionID
  where id# = ContractID;                      
 
  end if;
  end if; --Using Transactions  
  InitPayments(
              ContractID
             ,FacticalDebtWithDraw
             ,0
             ,InterestDebtWithdraw             
             ,0 
             );
               
 Commit ;
 
End;

Procedure  Capitalization(
                     ContractID IN SBCM_Contracts.ID%type
                    ,HDate      IN Date  
                    ,Total      IN Number 
                    ,UseTransactions IN Boolean  
                    )
Is

  DebtAccID   Integer;
  CreditAccID Integer;
  
  DebtAmount   Number(18,2);
  CreditAmount Number(18,2);
  LAmount      Number(18,2) :=null;
  
  TransactionID Integer;
  ContractNum   Varchar2(256);
  
Begin
SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
		 if sbcm_stored_programs.getfacticalinterestdebt(contractid)<total then
		 RAISE_APPLICATION_ERROR(
            SBCM_EXCEPTIONS.EPaymentError
           ,'%Payment Must Be Less Than Debt!'
           );
		end if;

  
  if UseTransactions  then
  DebtAccID   := SBCM_STORED_PROGRAMS.GetInterestAccID(ContractID);
  CreditAccID := SBCM_STORED_PROGRAMS.GetContractAccID(ContractID);    
  
  ContractNum := SBCM_STORED_PROGRAMS.ContractNumAsVarchar2(ContractID); 
      
  DebtAmount   := Total;
  CreditAmount := null;
  
      TransactionID :=SB_TRANSACTION.Transaction_Add(
		                  DebitID      => DebtAccID
            				 ,CreditID     => CreditAccID
            				 ,DebitAmount  => DebtAmount
            				 ,CreditAmount => CreditAmount
            				 ,LAmount      => LAmount
            				 ,DebitRate    => 0
            				 ,CreditRate   => 0
            				 ,TrName       => 'ƒепозит цзр€  фаиз капиталлашдырылыр є '||ContractNum
            				 ,Flags        => 0
            				 ,TransactionDate => HDate
   	                 );
   end if;
               
         InitPayments(
              ContractID
             ,-Total
             ,0
             ,Total             
             ,0 
             );              
        
  commit;
  
End;


              					  					 					  					 
END;
/

CREATE OR REPLACE 
PACKAGE sbcm_payment_plane
  IS
  Procedure Payments_Plane_Add(
                      ContractID IN SBCM_Contracts.ID%type
                     ,HDate#     IN Date
                     ,FacticalDebt IN Number
                     ,InterestDebt IN Number   
                     ,Paid# IN CHAR
                     );
  Procedure Payments_Plane_Del(
                      p_ID IN Integer
                     );
  Procedure Payments_Plane_Upd(
                      p_ID IN Integer
                     ,HDate# IN Date
                     ,FacticalDebt IN Number
                     ,InterestDebt IN Number
                     ,Paid# IN Char 
                     );
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sbcm_payment_plane
IS

  Procedure Payments_Plane_Add(
                      ContractID IN SBCM_Contracts.ID%type
                     ,HDate#     IN Date
                     ,FacticalDebt IN Number
                     ,InterestDebt IN Number   
                     ,Paid# IN CHAR
                     ) 
  Is
  Begin
  
    Insert  Into  SBCM_Payments_Plane(
                        ID#
                       ,HDate
                       ,FacticalDebtPayment
                       ,InterestDebtPayment
                       ,Paid 
                       )
            Values     (
             ContractID
            ,HDate#
            ,FacticalDebt
            ,InterestDebt
            ,Paid#   
            );
   commit;                                
                        
  End;
  
  Procedure Payments_Plane_Del(
                      p_ID IN Integer
                     )
  Is                     
  Begin
  
    Delete 
    From 
      SBCM_Payments_Plane
    Where
      ID = p_ID;
    
   commit;
      
  End;
  
  Procedure Payments_Plane_Upd(
                      p_ID IN Integer
                     ,HDate# IN Date
                     ,FacticalDebt IN Number
                     ,InterestDebt IN Number
                     ,Paid# IN Char 
                     )
  Is
  Begin
  
    update SBCM_Payments_Plane
    set
       HDate = HDate#
      ,FacticalDebtPayment = FacticalDebt
      ,InterestDebtPayment = InterestDebt
      ,Paid = Paid#
    where
      ID = p_ID;    
  
  commit;
        
  End;
                                            
END;
/

