CREATE OR REPLACE 
PACKAGE BODY sbcm_percent_converting
IS

/*--------------------------------------------*/
 /*  Warning :                                 */
 /*  This Procedure was working  succesful     */
/*  only when Contract has regulyar Percents! */
 /*                                            */
 /*--------------------------------------------*/
   PROCEDURE setlastdebts (contractid IN INTEGER)
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET lastfacticaldebt = facticaldebt,
             lastoverduedebt = overduedebt
       WHERE id# = contractid;
   END;

   FUNCTION iscapitalizationon
      RETURN BOOLEAN
   IS
      result   BOOLEAN;
   BEGIN
      result :=
          (sbcm_stored_programs.getreference ('cmrAutoCapitalization') = 'ON');
      RETURN result;
   END;

   FUNCTION iswithdrawon
      RETURN BOOLEAN
   IS
      result   BOOLEAN;
   BEGIN
      result :=
         (sbcm_stored_programs.getreference ('cmrAutoPaymentPercents') = 'ON');
      RETURN result;
   END;

   FUNCTION convertfloatableinterest (
      contractid     IN   sbcm_contracts.id%TYPE,
      dateinterval   IN   INTEGER
   )
      RETURN NUMBER
   IS
      result       NUMBER (18, 2)                            := 0.00;
      collection   sbcm_exports.collectionexporter%ROWTYPE;
      temp         NUMBER;
   BEGIN
      FOR collection IN sbcm_exports.collectionexporter (contractid)
      LOOP
         temp := getconverteddebt (
                    dateinterval,
                    collection.amount,
                    collection.PERCENT
                 );
         result :=   result
                   + temp;
      END LOOP;

      RETURN result;
   END;

   PROCEDURE setlastprocessdate (
      contractid   IN   sbcm_contracts.id%TYPE,
      convdate     IN   DATE
   )
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET lastprocessdate = convdate
       WHERE id# = contractid;
   END;

   PROCEDURE updatestatecache (
      contractid            IN   sbcm_contracts.id%TYPE,
      interestdebt          IN   NUMBER,
      overdueinterestdebt   IN   NUMBER
   )
   IS
   BEGIN
      UPDATE sbcm_state_cache
         SET facticalinterest = interestdebt,
             overdueinterest = overdueinterestdebt
       WHERE id# = contractid;
   END;

   FUNCTION getconverteddebt (
      dateinterval   IN   INTEGER,
      debt           IN   NUMBER,
      PERCENT        IN   NUMBER
   )
      RETURN NUMBER
   IS
      result           NUMBER ;
      daysofbankyear   INTEGER        := 360;
   BEGIN
     -- daysofbankyear := sbcm_stored_programs.getreference ('cmrYearDayCount');
      result :=   (debt * PERCENT * dateinterval)
                / (daysofbankyear * 100);
      RETURN result;
   END;

   FUNCTION getdateinterval (firstdate IN DATE, lastdate IN DATE)
      RETURN INTEGER
   IS
      result          INTEGER;
      currentmonth    DATE;
      MONTH           DATE    := firstdate;
      monthinterval   INTEGER;
      mounthindex     INTEGER;
      lastmonthday    INTEGER;
   BEGIN
      IF firstdate >= lastdate
      THEN
         result := 0;
      ELSE
         result := (  lastdate
                    - firstdate
                   );
         monthinterval := (  lastdate
                           - firstdate
                          ) / 30;

         FOR monthindex IN 0 .. monthinterval
         LOOP
            currentmonth := LAST_DAY (MONTH);
            lastmonthday := TO_NUMBER (TO_CHAR (currentmonth, 'DD'));

            IF  (currentmonth <= lastdate) AND (currentmonth > firstdate)
            THEN
               IF lastmonthday = 31
               THEN
                  result :=   result
                            - 1;
               END IF;

               IF lastmonthday = 28
               THEN
                  result :=   result
                            + 2;
               END IF;

               IF lastmonthday = 29
               THEN
                  result :=   result
                            + 1;
               END IF;
            END IF;

            MONTH := ADD_MONTHS (MONTH, 1);
         END LOOP;
      END IF;

      RETURN result;
   END;

   PROCEDURE increaseinterestdebt (
      contractid                     IN   sbcm_contracts.id%TYPE,
      facticalinterestdebtincrease   IN   NUMBER,
      overdueinterestdebtincrease    IN   NUMBER,
      INTPRECISIONincrease           in number,
      dueINTPRECISIONincrease        in number default 0
   )
   IS
   BEGIN
      UPDATE sbcm_contract_state
         SET facticalinterestdebt =
                          facticalinterestdebt
                        + facticalinterestdebtincrease,
             overdueinterestdebt =
                            overdueinterestdebt
                          + overdueinterestdebtincrease
       WHERE id# = contractid;

       update sbcm_deposit_interests
       set interest = facticalinterestdebtincrease,
           overdureinterest = overdueinterestdebtincrease,
           intprecision = INTPRECISIONincrease,
           dueintprecision = dueINTPRECISIONincrease
       where id# = contractid;

   END;

   FUNCTION convertpercents (
      contractid    IN   sbcm_contracts.id%TYPE,
      convertdate   IN   DATE
   )
      RETURN INTEGER
   IS
      firstdate               DATE;
      lastdate                DATE;
      dateinterval            INTEGER;
      convertedfacticaldebt   NUMBER         /*:= 0*/;
      convertedoverduedebt    NUMBER         /*:= 0*/;
      facticaldebt            NUMBER ;
      overduedebt             NUMBER ;
      PERCENT                 NUMBER;
      overduepercent          NUMBER;
      debtamount              NUMBER ;
      creditamount            NUMBER /*(15, 2)*/;
      lamount                 NUMBER /*(15, 2)*/;
      interestaccid           ACCOUNT.id%TYPE;
      overdueinterestaccid    ACCOUNT.id%TYPE;
      incomeinterestaccid     ACCOUNT.id%TYPE;
      tempid                  NUMBER;
      transid                 NUMBER;
      IntPrec                 Number;
      DueIntPrec              Number;
      contractcurrency        avalute.valute%TYPE;
      CalcedPercent           sbcm_exports.c_CalcedInterests%rowtype;

   BEGIN

      /*open sbcm_exports.c_CalcedInterests(contractid);
      fetch sbcm_exports.c_CalcedInterests into CalcedPercent;
      close sbcm_exports.c_CalcedInterests;*/

      select
        intprecision,
        dueintprecision
      into
        IntPrec,
        DueIntPrec
      from sbcm_deposit_interests
      where id# = contractid;

      facticaldebt := sbcm_stored_programs.getfacticaldebt (contractid);
      overduedebt := sbcm_stored_programs.getoverduedebt (contractid);

      IF    ((facticaldebt = 0) AND (overduedebt = 0))
         OR (NOT sbcm_stored_programs.iscalculationenabled (contractid))
      THEN
         raise_application_error (
            -20207,
            '((FacticalDebt = 0.00)AND(OverdueDebt = 0.00)) OR Calculation Disabled!'
         );
      END IF;

      firstdate := sbcm_stored_programs.getlastprocessdate (contractid);
      lastdate := convertdate;

      IF firstdate >= lastdate
      THEN
         raise_application_error (-20206, 'Invalid Convertion Date!');
      END IF;

      dateinterval := getdateinterval (firstdate, lastdate);
      contractcurrency :=
                         sbcm_stored_programs.getcontractcurrency (contractid);
      PERCENT := sbcm_stored_programs.getpercent (contractid);
      overduepercent := sbcm_stored_programs.getoverduepercent (contractid);
      incomeinterestaccid :=
            sbcm_stored_programs.getselectedaccid (
               contractid,
               'inComeAccForInterests'
            );
      tempid := sb_transaction.gen_temp_id ();

      -- Converting Main Debt --

      IF facticaldebt <> 0
      THEN
         interestaccid := sbcm_stored_programs.getinterestaccid (contractid);
         convertedfacticaldebt :=
                       getconverteddebt (dateinterval, facticaldebt, PERCENT)
                       +IntPrec/*CalcedPercent.intprecision*/;

   /*-------Ch 21-dec-2005--------*/
         --IF contractcurrency = 0
   --      THEN
            debtamount := sbcmPrecision2(convertedfacticaldebt);
            creditamount := sbcmPrecision2(convertedfacticaldebt);
     --      raise_application_error(-20007,sbcmPrecision7(convertedfacticaldebt));

      --   ELSE
         /*   debtamount := convertedfacticaldebt;
            creditamount := convertedfacticaldebt;
         END IF;*/

         lamount := NULL;
         transid :=
               sb_transaction.transaction_add (
                  debitid=> interestaccid,
                  creditid=> incomeinterestaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> lamount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=> 'ўесабланмыш фаизл€рд€н э€лир',
                  flags => 0,
                  tempid=> tempid,
                  transactiondate=> convertdate
               );
      END IF;

      IF overduedebt <> 0
      THEN
         overdueinterestaccid :=
                    sbcm_stored_programs.getoverdueinterestaccid (contractid);
         convertedoverduedebt :=
                 getconverteddebt (dateinterval, overduedebt, overduepercent)
                 +DueIntPrec/*CalcedPercent.dueintprecision*/;

        /* IF contractcurrency = 0
         THEN
            debtamount := ROUND (convertedoverduedebt);
            creditamount := ROUND (convertedoverduedebt);
         ELSE*/
            debtamount := sbcmPrecision2(convertedoverduedebt);
            creditamount := sbcmPrecision2(convertedoverduedebt);
    --     END IF;

         lamount := NULL;
         transid :=
               sb_transaction.transaction_add (
                  debitid=> overdueinterestaccid,
                  creditid=> incomeinterestaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> lamount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=> ' ћцдд€ти кечмиш фаизл€рин ўесабланмасындан  э€лир',
                  flags => 0,
                  tempid=> tempid,
                  transactiondate=> convertdate
               );
      END IF;

      updatestatecache (
         contractid,
         convertedfacticaldebt,
         convertedoverduedebt
      );
      increaseinterestdebt (
         contractid,
         sbcmPrecision2(convertedfacticaldebt),
         nvl(sbcmPrecision2(convertedoverduedebt),0),
         nvl(sbcmPrecision7(convertedfacticaldebt),0),
         nvl(sbcmPrecision7(convertedoverduedebt),0)
      );
      setlastprocessdate (contractid, convertdate);
      COMMIT;
      RETURN tempid;
   END;

   FUNCTION getlastdate (
      contractid       IN   sbcm_contracts.id%TYPE,
      convertingdate   IN   DATE
   )
      RETURN DATE
   IS
      result      DATE;
      closedate   DATE;
   BEGIN
      closedate := sbcm_stored_programs.sbcmgetolddate (contractid);

      IF convertingdate = closedate
      THEN
         result :=
                 convertingdate
               + sbcm_stored_programs.booltoint (
                    sbcm_stored_programs.usingright
                 );
      ELSE
         result := convertingdate;
      END IF;

      RETURN result;
   END;

   FUNCTION converdeposits (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE
   )
      RETURN INTEGER
   /*
      Result :
               1 - Capitalization Added ;
               2 - Interests Withdrawed ;
               0 - No Operation Processed;
   */
   IS
      outcomeforinterestaccid       INTEGER;
      interestaccid                 INTEGER;
      contractaccid                 INTEGER;
      facticaldebt                  NUMBER  := 0;
      converteddebt                 NUMBER  := 0;
      debtamount                    NUMBER  := 0;
      creditamount                  NUMBER  := 0;
      firstdate                     DATE;
      lastdate                      DATE;
      dateinterval                  INTEGER;
      PERCENT                       NUMBER ;
      transactionid                 INTEGER;
      contractnum                   VARCHAR2 (256);
      additionaldeposittypea        VARCHAR2 (32);
      additionaldeposittype         VARCHAR2 (32);
      lastwcdate                    DATE;
      wcinterval                    INTEGER;
      daysprocessed                 INTEGER;
      TEMPORARY                     INTEGER;
      actualwcdate                  DATE;
      interestbeforewc              NUMBER  := 0;
      interestafterwc               NUMBER  := 0;
      transactiononcapitalization   BOOLEAN;
      transactiononwithdraw         BOOLEAN;
      totalinterest                 NUMBER  := 0;
      processwc                     BOOLEAN        := FALSE;
      result                        INTEGER;
      intprec                       number;
      CalcAccRate                   Number;

   BEGIN
    SB_ACA.CheckObjectAccess('DEPOSITMANAGER','update');  --adm
      /* ----  Initialization  ---- */
      result := 0;
      facticaldebt := sbcm_stored_programs.getfacticaldebt (contractid); -- Main Debt
      outcomeforinterestaccid :=
            sbcm_stored_programs.getselectedaccid (
               contractid,
               'outComeAccForDeposit'
            ); -- Out come Account for Deposit
      additionaldeposittypea :=
          LOWER (sbcm_stored_programs.getadditionaldeposittypea (contractid));
      additionaldeposittype :=
           LOWER (sbcm_stored_programs.getadditionaldeposittype (contractid));
      PERCENT := sbcm_stored_programs.getpercent (contractid); -- Percent
      interestaccid := sbcm_stored_programs.getinterestaccid (contractid); -- Interest Account
      contractaccid := sbcm_stored_programs.getcontractaccid (contractid);
      contractnum := sbcm_stored_programs.contractnumasvarchar2 (contractid); -- Number of Contract
      firstdate := sbcm_stored_programs.getlastprocessdate (contractid); -- Lats Process Date of Contract
      lastdate := hdate; -- Convertion Date
      transactiononcapitalization :=
            (sbcm_stored_programs.getreference (
                'cmrTransactionOnCapitalization'
             ) = 'ON'
            );
      transactiononwithdraw :=
            (sbcm_stored_programs.getreference ('cmrTransactionOnWithdraw') =
                                                                         'ON'
            );
      wcinterval := sbcm_stored_programs.getwcdateinterval (contractid);
      lastwcdate := sbcm_stored_programs.getlastwcdate (contractid);
      daysprocessed := getdateinterval (lastwcdate, hdate);

      select intprecision into intprec
      from sbcm_deposit_interests where id# = contractid;


      /* ---- End Initialization ---- */

      /*  Checking  Validate  */
      IF (facticaldebt = 0)and(CalcAccRate = 1)
      THEN
         raise_application_error (-20207, 'Contract has not Rests .^');
      END IF;

      IF NOT sbcm_stored_programs.iscalculationenabled (contractid)
      THEN
         raise_application_error (
            -20207,
            'Calculation Percents is Disabled .^'
         );
      END IF;

      IF firstdate >= lastdate
      THEN
         raise_application_error (-20206, 'Invalid Convertion Date . ^');
      END IF;

      IF      (additionaldeposittype = 'collection')
          AND (   (    (additionaldeposittypea = 'capitalization')
                   AND iscapitalizationon
                  )
               OR ((additionaldeposittypea = 'withdraw') AND iswithdrawon)
              )
      THEN
         raise_application_error (
            -20287,
            '%Can not Perform this operation for Collection Deposits.^'
         );
      END IF;

      /*   End  Checking  Validate  */

      /* Converting Interest */

      IF      (   iscapitalizationon
               OR iswithdrawon
              )
          AND (wcinterval > 0)
          AND (daysprocessed >= wcinterval)
      THEN

         TEMPORARY :=   daysprocessed
                      - wcinterval;
         actualwcdate :=   hdate
                         - TEMPORARY;
         interestbeforewc := getconverteddebt (
                                getdateinterval (firstdate, actualwcdate),
                                facticaldebt,
                                PERCENT
                             )+intprec;

         IF  additionaldeposittypea = 'capitalization' AND iscapitalizationon
         THEN
            increaseinterestdebt (
                             contractid,
                             sbcmPrecision2(interestbeforewc),
                             0,
                             sbcmPrecision7(interestbeforewc));
            totalinterest :=
                    sbcm_stored_programs.getfacticalinterestdebt (contractid);
            processwc := TRUE;
            interestafterwc := getconverteddebt (
                                  getdateinterval (actualwcdate, lastdate),
                                    facticaldebt
                                  + totalinterest,
                                  PERCENT
                               )+intprec;
            increaseinterestdebt (
                          contractid,
                          sbcmPrecision2(interestafterwc), 0,
                          sbcmPrecision7(interestafterwc));
            result := 1;
         ELSIF  additionaldeposittypea = 'withdraw' AND iswithdrawon
         THEN
    --     raise_application_error(-20007,'Saalm');
            increaseinterestdebt (contractid, sbcmPrecision2(interestafterwc), 0,0);
            totalinterest :=
                    sbcm_stored_programs.getfacticalinterestdebt (contractid);
            processwc := TRUE;
            interestafterwc := getconverteddebt (
                                  getdateinterval (actualwcdate, lastdate),
                                  facticaldebt,
                                  PERCENT
                               )+intprec;
            increaseinterestdebt (contractid
                                 ,sbcmPrecision2(interestafterwc),
                                 0,
                                 sbcmPrecision7(interestafterwc));
            result := 2;
         END IF;

         updatelastwcdate (contractid, actualwcdate);
         converteddebt :=   interestafterwc
                          + interestbeforewc;
      ELSE

         converteddebt :=
                          CalcPercent(
                           facticaldebt,
                           PERCENT,
                           getdateinterval (firstdate, lastdate)
                           )+intprec;

         IF additionaldeposittype = 'collection'
         THEN
            converteddebt :=
                       converteddebt
                      + convertfloatableinterest (
                           contractid,
                           getdateinterval (firstdate, lastdate))+intprec;
         END IF;

         increaseinterestdebt (contractid,

                               sbcmPrecision2(converteddebt),
                               0,
                               sbcmPrecision7(converteddebt));
      END IF;

      debtamount := sbcmPrecision2(converteddebt);

      creditamount := NULL;

      IF debtamount <> 0
      THEN
         transactionid :=
               sb_transaction.transaction_add (
                  debitid=> outcomeforinterestaccid,
                  creditid=> interestaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> NULL,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    'ƒепозитл€рин фаиз х€ржл€ри  є '
                           || contractnum,
                  flags => 0,
                  transactiondate=> hdate
               );
      END IF;

      updDepositInr(contractid,transactionid);

      setlastprocessdate (contractid, hdate);
      sbcm_stored_programs.sbdmsettotalpercents (contractid, converteddebt);

      IF processwc
      THEN
   --    Raise_application_error(-20007,'Salam');

         IF additionaldeposittypea = 'capitalization'
         THEN
            sbcm_payment.capitalization (
               contractid,
               hdate,
               totalinterest,
               transactiononcapitalization
            );
         ELSIF additionaldeposittypea = 'withdraw'
         THEN
--  Raise_application_error(-20007,'SSSS');

            sbcm_payment.withdrawmoney (
               contractid,
               hdate,
               0,
               totalinterest,
               transactiononwithdraw
            );
         END IF;
         commit work;
      END IF;

   /*------------------------------------------------------------------------*/

     /* select nvl(CONTRACTFORACCRATE,1) into CalcAccRate
      from sbcm_contracts where id = contractid;

      outcomeforinterestaccid :=
            sbcm_stored_programs.getselectedaccid (
               contractid,
               'outComeAccForAccRate'
            ); -- Out come Account for Account^s Rates

      if CalcAccRate = 0 then
          converteddebt :=
                         CalcPercent(
                           sbcm_stored_programs.Get_OstatAccount(contractaccid),
                           PERCENT,
                           getdateinterval (firstdate, lastdate)
                           )+intprec;


         increaseinterestdebt (contractid,
                               sbcmPrecision2(converteddebt),
                               0,
                               sbcmPrecision7(converteddebt));
         debtamount := sbcmPrecision2(converteddebt);

         creditamount := NULL;
         transactionid :=
               sb_transaction.transaction_add (
                  debitid=> outcomeforinterestaccid,
                  creditid=> interestaccid,
                  debitamount=> debtamount,
                  creditamount=> creditamount,
                  lamount=> NULL,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=>    'ўесаб галыгларынын фаиз х€ржл€ри  є '
                           || contractnum,
                  flags => 0,
                  transactiondate=> hdate
               );

      -- raise_application_error(-20007,'Salam');
      end if; */
   /*-------------------------------------------------------------------------*/
      COMMIT;
      RETURN result;
   END;

   /*  Convert  Deposits  */
   PROCEDURE postdifferedtransaction (
      contractid        IN   sbcm_contracts.id%TYPE,
      balanceinterest   IN   NUMBER
   )
   IS
   BEGIN
      INSERT INTO sbcm_deffered_transactions
                  (contractid, balanceinterest)
           VALUES (contractid, balanceinterest);

      COMMIT;
   END;

   PROCEDURE convertinglazypercents (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE
   )
   IS
      firstdate               DATE;
      lastdate                DATE;
      dateinterval            INTEGER;
      convertedfacticaldebt   NUMBER (15, 2);
      convertedoverduedebt    NUMBER (15, 2);
      facticaldebt            NUMBER (15, 2);
      overduedebt             NUMBER (15, 2);
      PERCENT                 NUMBER (7, 2);
      overduepercent          NUMBER (7, 2);
      finterestdebt           NUMBER (18, 2);
      ointerestdebt           NUMBER (18, 2);
      lfacticaldebt           NUMBER (18, 2);
      loverduedebt            NUMBER (18, 2);
--      DecimialKind            BOOLEAN := FALSE;
      CalcDecimials           Integer := 2;
   BEGIN
   SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
      facticaldebt := sbcm_stored_programs.getfacticaldebt (contractid);
      overduedebt := sbcm_stored_programs.getoverduedebt (contractid);

      CalcDecimials :=2;-- TO_NUMBER(sbcm_stored_programs.getreference('cmrCalcDecimials'));
  --    DecimialKind := sbcm_stored_programs.getreference('cmrCalcDecimialsKind') = 'ON';

      IF    ((facticaldebt = 0) AND (overduedebt = 0))
         OR (NOT sbcm_stored_programs.iscalculationenabled (contractid))
      THEN
         raise_application_error (
            -20207,
            '((FacticalDebt = 0.00)AND(OverdueDebt = 0.00)) OR Calculation Disabled!'
         );
      END IF;

      SELECT facticalinterestdebt, overdueinterestdebt
        INTO finterestdebt, ointerestdebt
        FROM sbcm_contract_state
       WHERE id# = contractid;

      if sbcm_stored_programs.usingleft then

      SELECT facticaldebt, overduedebt
        INTO lfacticaldebt, loverduedebt
        FROM sbcm_contract_state
       WHERE id# = contractid;
      else
        lfacticaldebt := facticaldebt;
        loverduedebt := overduedebt;
      end if;
      firstdate := sbcm_stored_programs.getlastprocessdate (contractid);
      lastdate := hdate;

      IF firstdate >= lastdate
      THEN
         raise_application_error (-20206, 'Invalid Convertion Date!');
      END IF;

      dateinterval := getdateinterval (firstdate, lastdate);
      PERCENT := sbcm_stored_programs.getpercent (contractid);
      overduepercent := sbcm_stored_programs.getoverduepercent (contractid);


      -- Converting Main Debt --

      IF facticaldebt <> 0 or lFacticalDebt <> 0
      THEN
--      if not DecimialKind then
         convertedfacticaldebt :=
               ROUND (
                    getconverteddebt (
                       getdateinterval (  lastdate
                                        - 1, lastdate),
                       facticaldebt,
                       PERCENT
                    )
                  + getconverteddebt (
                       getdateinterval (firstdate,   lastdate
                                                   - 1),
                       lfacticaldebt,
                       PERCENT
                    ),CalcDecimials

                                 );
         if   ROUND (
                        (  convertedfacticaldebt
                         + finterestdebt
                        ),
                        CalcDecimials
                     ) <> 0 then
         postdifferedtransaction (
            contractid=> contractid,
            balanceinterest=> ROUND (
                        (  convertedfacticaldebt
                         + finterestdebt
                        ),
                        CalcDecimials
                     )
         );
         end if;
      END IF;

      IF overduedebt <> 0 or lOverdueDebt <> 0
      THEN
         convertedoverduedebt :=
               ROUND (
                    getconverteddebt (
                       getdateinterval (  lastdate
                                        - 1, lastdate),
                       overduedebt,
                       overduepercent
                    )
                  + getconverteddebt (
                       getdateinterval (firstdate,   lastdate
                                                   - 1),
                       loverduedebt,
                       overduepercent
                    ),
                  CalcDecimials
               );
         if ROUND (
                        (  convertedoverduedebt
                         + ointerestdebt
                        ),
                        CalcDecimials
                     ) <> 0 then
         postdifferedtransaction (
            contractid=> contractid,
            balanceinterest=> ROUND (
                        (  convertedoverduedebt
                         + ointerestdebt
                        ),
                        CalcDecimials
                     )
         );
         end if;
      END IF;

      COMMIT;

   END;

   PROCEDURE deldefferedtransactions
   IS
   BEGIN
      DELETE FROM sbcm_deffered_transactions;

      COMMIT;
   END;

   PROCEDURE applydefferedtransactions (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE
   )
   IS
      facticaldebt            NUMBER (18, 2);
      overduedebt             NUMBER (18, 2);
      finterestdebt           NUMBER (18, 2);
      ointerestdebt           NUMBER (18, 2);
      balanceinterest         NUMBER (18, 2);
      debitid                 INTEGER;
      creditid                INTEGER;
      debitamount             NUMBER (18, 2);
      creditamount            NUMBER (18, 2);
      lamount                 NUMBER (18, 2);
      binterest               NUMBER (18, 2);
      convertedfacticaldebt   NUMBER (18, 2) := 0;
      convertedoverduedebt    NUMBER (18, 2) := 0;
      transid                 INTEGER;
      pcid                    INTEGER;
      contractnum             VARCHAR2 (256);
   BEGIN
      creditid :=
            sbcm_stored_programs.getselectedaccid (
               contractid,
               'inComeAccForInterests'
            );
      facticaldebt := sbcm_stored_programs.getfacticaldebt (contractid);
      overduedebt := sbcm_stored_programs.getoverduedebt (contractid);

      setlastdebts (contractid);

      SELECT contractno
        INTO contractnum
        FROM sbcm_contracts
       WHERE id = contractid;

      SELECT facticalinterestdebt, overdueinterestdebt
        INTO finterestdebt, ointerestdebt
        FROM sbcm_contract_state
       WHERE id# = contractid;

      pcid := contractid;

      SELECT balanceinterest
        INTO binterest
        FROM sbcm_deffered_transactions
       WHERE contractid = pcid;

      IF facticaldebt <> 0
      THEN
         debitid := sbcm_stored_programs.getinterestaccid (contractid);
         debitamount :=   binterest
                        - finterestdebt;
         convertedfacticaldebt := debitamount;
      ELSE
         debitid := sbcm_stored_programs.getoverdueinterestaccid (contractid);
         debitamount :=   binterest
                        - ointerestdebt;
         convertedoverduedebt := debitamount;
      END IF;

      creditamount := debitamount;
      lamount := NULL;
      contractnum :=    'ўесабланмыш фаизл€рд€н э€лир є'
                     || contractnum;

      IF debitamount <> 0
      THEN
         transid :=
               sb_transaction.transaction_add (
                  debitid=> debitid,
                  creditid=> creditid,
                  debitamount=> debitamount,
                  creditamount=> NULL,
                  lamount=> lamount,
                  debitrate=> 0,
                  creditrate=> 0,
                  trname=> contractnum,
                  flags => 0,
                  transactiondate=> hdate
               );
      END IF;

      increaseinterestdebt (
         contractid,
         convertedfacticaldebt,
         convertedoverduedebt,0
      );
      setlastprocessdate (contractid, hdate);
      COMMIT;
   END;

   PROCEDURE updatelastwcdate (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE
   )
   IS
   BEGIN
      IF NOT hdate IS NULL
      THEN
         UPDATE sbcm_contract_state
            SET stopcalculationdate = hdate
          WHERE id# = contractid;
      END IF;
   END;

   FUNCTION capitalization_add (
      contractid   IN   sbcm_contracts.id%TYPE,
      hdate        IN   DATE
   )
      RETURN BOOLEAN
   IS
   BEGIN
      NULL;
   END;

   function sbcmPrecision7(p_Value in Number)
   return Number
   is
     Result Number;
     Temp Number := p_Value;
   begin
     Temp := Temp * 100 - Trunc(Temp * 100);
     Result := Temp / 100;
     return Result;
   end;

   function sbcmPrecision2(p_Value in Number)
   return Number
   is
     Result Number;
     Temp Number := p_Value;
   begin
     Temp := Temp * 100 - Trunc(Temp * 100);
     Result := p_Value - Temp / 100;
     return Result;
   end;


    function CalcPercent(
            p_Sum in Number,
            p_Rate in Number  ,
            p_Coefficient in Number ,
            p_Delimmer in Number default 360
            )
   return number
   is
     Result Number (18,6);
   begin
     Result := ( p_Sum * p_Rate * p_Coefficient ) / ( p_Delimmer * 100 );
     return Result;
   end;

   Procedure CancelDepositIntCalc(p_contractID in integer)
   is

     cursor c_state(cid in integer)
     is
     select
        facticaldebt,
        overduedebt,
        facticalinterestdebt,
        overdueinterestdebt,
        stopcalculationdate,
        lastprocessdate,
        calculationenabled,
        lastfacticaldebt,
        lastoverduedebt
     from sbcm_contract_state
     where id# = cid;

     cursor c_calcdeposit(cid in integer)
     is
     SELECT
        hdate,
        interest,
        overdureinterest,
        intprecision,
        dueintprecision,
        inttrid,
        dueinttrid,
        withdrawtrid
     FROM sbcm_deposit_interests
     where id# = cid;

     StateInfo c_state%rowtype;
     CalcInfo c_calcdeposit%rowtype;

     intprec number;
     dueintprec number;

     inttrid  integer;
     dueinttrid  integer;
     withdrawtrid integer;
     Result integer;


   begin

     if sbcm_stored_programs.checkcontractstate(p_contractid) = -10 then

     open c_state(p_contractID);
     fetch c_state into StateInfo;
     close c_state;

     open c_calcdeposit(p_contractID);
     fetch c_calcdeposit into CalcInfo;
     close c_calcdeposit;

     intprec := CalcInfo.intprecision;
     dueintprec := CalcInfo.dueintprecision;

     inttrid := CalcInfo.inttrid;
     dueinttrid := CalcInfo.dueinttrid;
     withdrawtrid := CalcInfo.withdrawtrid;
 --  raise_application_error(-20007,'Dedimmi = '||inttrid);

      if (inttrid is not null) and (transactionexist(inttrid))then
         SB_TRANSACTION.Transaction_Delete(IntTrID);
      end if;

      if (DueIntTrID is not null) and (transactionexist(DueIntTrID)) then
        SB_TRANSACTION.Transaction_Delete(DueIntTrID);
      end if;

      if (withdrawtrid is not null) and (transactionexist(withdrawtrid)) then
          SB_TRANSACTION.Transaction_Delete(withdrawtrid);
      end if;

     update sbcm_contract_state
     set
       lastprocessdate  = lastprocessdate - 1,
       facticalinterestdebt = facticalinterestdebt - CalcInfo.interest,
       overdueinterestdebt = overdueinterestdebt - CalcInfo.overdureinterest
     where ID# = p_contractID;  -- // New

    update sbcm_deposit_interests
       set
           INTTRID = null ,
           DUEINTTRID = null ,
           intprecision = IntPrec ,
           DUEintprecision = DueIntPrec
     where ID# = p_contractID;

     Commit work;
     end if;
   end;

   procedure updDepositInr(p_id in integer,trid in integer)
   is
   begin

      update sbcm_deposit_interests
      set inttrid = trid
      where id#= p_id;

      commit;
   end;

   function transactionexist(p_id in integer)
   return boolean
   is

   cursor c_pr(pid in integer)
   is
   select id from provarch
   where id  = pid;

   cursor c_laz(pid in integer)
   is
   select id from lazytransaction
   where id  = pid;

   pr c_pr%rowtype;
   laz c_laz%rowtype;

   Result boolean;

   begin

     open c_pr(p_id);
     fetch c_pr into pr;

     open c_laz(p_id);
     fetch c_laz into laz;

     result := (c_pr%found) or (c_laz%found);
     close c_pr;
     close c_laz;

     return result;
   end;

END;
