/

CREATE OR REPLACE 
PACKAGE sbcm_prolongation
  IS					
  procedure  AddProlongation(
             ContractID IN  SBCM_Contracts.ID%type
						,HDate IN Date
						,NewDate IN Date
            );
  Procedure  DelLastProlongation(ContractID IN SBCM_Prolongations.ID%type);
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sbcm_prolongation
IS	
procedure  UpdateCloseDate(
               ContractID IN SBCM_Contracts.ID%type
							,NewDate IN Date 
							)
 Is
 begin
   update  SBCM_Contracts 
	 Set
	   CloseDate = NewDate
	 Where 
	     ID = ContractID;	 
 end;
 		
procedure  DelProlongation(ProlongID IN SBCM_Prolongations.ID%type)
 Is
 begin
   Delete 
	   From SBCM_Prolongations
   Where  ID = ProlongID; 
 end;
  
Procedure  DelLastProlongation(ContractID IN SBCM_Prolongations.ID%type)
 Is
  cursor  LastProlongation(ContID SBCM_Contracts.ID%type) is
	Select
	  ID	 
	 ,OldDate From SBCM_Prolongations
	Where
	  ID = 	
	(select
	  Max(ID) From  SBCM_Prolongations
	 Where 
	   ID# = ContID);				
	
	
   p_ID   SBCM_Prolongations.ID%type;	
	 NewDate Date;	 
 begin
 SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
  Open  LastProlongation(ContractID);
	 Fetch  LastProlongation Into p_ID,NewDate;
	Close LastProlongation;	
	DelProlongation(p_ID);
	UpdateCloseDate(
	     ContractID
			,NewDate  
	    );
	commit;		
Exception  
   When  OTHERS  Then
	 begin
	   if LastProlongation%IsOpen  then
		   Close LastProlongation;
		 end if;
		Raise_Application_Error(-20199,'Error :Can not Delete Last Prolongation!');   
	 end;			 
 end;
 					 
Procedure  NewProlongation(
           p_ID#  IN  SBCM_Prolongations.ID#%type
					,p_HDate IN Date
					,p_OldDate IN Date					
					,p_NewDate IN Date  
					)	
 Is
 begin
   Insert Into  SBCM_Prolongations(
	               ID#
								,HDate
								,OldDate
								,NewDate 
	              )
                Values(
								 p_ID#
								,p_HDate
								,p_OldDate
								,p_NewDate  
          			);																
 end;
 --   Adding  New  Prolongation --
procedure  AddProlongation(
             ContractID IN  SBCM_Contracts.ID%type
						,HDate IN Date
						,NewDate IN Date
            )
 Is
   OldDate Date;
 begin
  SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
   OldDate :=SBCM_Stored_Programs.SBCMGetOldDate(
	                                ContractID
																	);   																	
   UpdateCloseDate(
	     ContractID
			,NewDate 
	    );																	
	 NewProlongation(
	     ContractID
			,HDate
			,OldDate
			,NewDate 
	    );
	commit;		
 end;						    
END;
/

CREATE OR REPLACE 
PACKAGE sbcm_reserve_cont
  IS

  procedure  ChangePrimaryReserve(
                 ContractID in integer ,
                 HDate in date ,
                 newReserveID in integer ,
                 Amount in number ,
                 TransactionsON in boolean ,                 
                 ReserveOutTransactionID in out integer ,
                 ReserveInTransactionID  in out integer ,
                 commitOnChange in Boolean default FALSE                                    
                 );
  procedure  ChangeSecondaryReserve(
                 ContractID in integer ,
                 HDate in date ,
                 newReserveID in integer ,
                 Amount in number ,
                 TransactionsON in boolean ,                 
                 ReserveOutTransactionID in out integer ,
                 ReserveInTransactionID  in out integer ,
                 commitOnChange in Boolean default FALSE                                    
                 );
  procedure ChangeReserve(
            ContractID in integer ,
            HDate in date ,
            newReserveID in integer ,
            newExpiredReserveID in integer ,
            changePReserve in boolean ,
            changeSReserve in boolean ,
            TransactionsON in boolean     
            );
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sbcm_reserve_cont
IS

   procedure  SetPrimaryReserve(
                 ContractID in integer ,
                 Value in integer 
                 )
   is
   begin
     update sbcm_contracts
     set 
       ReliabilityID = Value
     where 
       ID = ContractID;  
   end;
   
   procedure  SetSecondaryReserve(
                 ContractID in integer ,
                 Value in integer 
                 )
   is
   begin
     update sbcm_contracts
     set 
       OverdueReliabilityID = Value
     where 
       ID = ContractID;  
   end; 

   procedure  ChangePrimaryReserve(
                 ContractID in integer ,
                 HDate in date ,
                 newReserveID in integer ,
                 Amount in number ,
                 TransactionsON in boolean ,                 
                 ReserveOutTransactionID in out integer ,
                 ReserveInTransactionID  in out integer ,
                 commitOnChange in Boolean default FALSE                                    
                 )
   is
   oldReservePercent   number(5,2);
   newReservePercent   number(5,2);
   CreditRest number(17,2);
   AccForOutReserve Account.ID%type;
   ReserveAccID integer;
   ReserveBackAmount number(17,2);
   ReserveForwardAmount number(17,2);
   outTransactionDesc varchar2(64) := ' редит€ айрылмыш ещтиййат азалдылыр є ';
   inTransactionDesc  varchar2(64) := ' редит€ айрылмыш ещтиййат артырылыр є ';    
   begin
     if  TransactionsON  then
     outTransactionDesc := outTransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);
     CreditRest := sbcm_stored_programs.getfacticaldebt(ContractID);
     oldReservePercent := sbcm_stored_programs.getreliabilitypercent(ContractID);
     newReservePercent := sbcm_stored_programs.getreservepercentbyID(newReserveID);     
     ReserveAccID := sbcm_stored_programs.getreserveaccID(ContractID);
     AccForOutReserve := sbcm_stored_programs.getselectedaccid(ContractID,'outComeAccForReserve');
     ReserveBackAmount := ROUND(CreditRest * oldReservePercent / 100 , 2 ); -- % --
     if  ReserveBackAmount > 0 then
     ReserveOutTransactionID := 
     SB_TRANSACTION.Transaction_Add (
                      DebitID  => ReserveAccID ,
                      CreditID => AccForOutReserve ,
                      DebitAmount => ReserveBackAmount ,
                      CreditAmount=> null ,
                      lAmount  => null ,
                      DebitRate  => 0 ,
                      CreditRate => 0 ,
                      trName => outTransactionDesc ,
                      flags  => 0 ,
                      TransactionDate => HDate
                     );
     end if;
     
     ReserveForwardAmount := ROUND((CreditRest + Amount) * newReservePercent / 100 , 2 ); -- % --
     inTransactionDesc := inTransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);     
     if  ReserveForwardAmount > 0 then
     ReserveOutTransactionID := 
     SB_TRANSACTION.Transaction_Add (
                      DebitID  => AccForOutReserve ,
                      CreditID => ReserveAccID ,
                      DebitAmount => null ,
                      CreditAmount=> ReserveForwardAmount ,
                      lAmount  => null ,
                      DebitRate  => 0 ,
                      CreditRate => 0 ,
                      trName => inTransactionDesc ,
                      flags  => 0 ,
                      TransactionDate => HDate
                     );
     end if;
     
     end if; --TransactionsON
     
     SetPrimaryReserve(ContractID , newReserveID);
     if  commitOnChange  then  commit;  end if;
    
   end;  

   procedure  ChangeSecondaryReserve(
                 ContractID in integer ,
                 HDate in date ,
                 newReserveID in integer ,
                 Amount in number ,
                 TransactionsON in boolean ,                 
                 ReserveOutTransactionID in out integer ,
                 ReserveInTransactionID  in out integer ,
                 commitOnChange in Boolean default FALSE                                    
                 )
   is
   oldReservePercent   number(5,2);
   newReservePercent   number(5,2);
   CreditRest number(17,2);
   AccForOutReserve Account.ID%type;
   ReserveAccID integer;
   ReserveBackAmount number(17,2);
   ReserveForwardAmount number(17,2);
   outTransactionDesc varchar2(96) := 'Ёежикдирилмиш кредит€ айрылмыш ещтиййат азалдылыр є ';
   inTransactionDesc  varchar2(96) := 'Ёежикдирилмиш кредит€ айрылмыш ещтиййат артырылыр є ';    
   begin
     if  TransactionsON  then
     outTransactionDesc := outTransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);
     CreditRest := sbcm_stored_programs.getoverduedebt(ContractID);
     oldReservePercent := sbcm_stored_programs.getoverduereliabilitypercent(ContractID);
     newReservePercent := sbcm_stored_programs.getreservepercentbyID(newReserveID);     
     ReserveAccID := sbcm_stored_programs.getoverduereserveaccID(ContractID);
     AccForOutReserve := sbcm_stored_programs.getselectedaccid(ContractID,'outComeAccForExpReserve');
     ReserveBackAmount := ROUND(CreditRest * oldReservePercent / 100 , 2 ); -- % --
     if  ReserveBackAmount > 0 then
     ReserveOutTransactionID := 
     SB_TRANSACTION.Transaction_Add (
                      DebitID  => ReserveAccID ,
                      CreditID => AccForOutReserve ,
                      DebitAmount => ReserveBackAmount ,
                      CreditAmount=> null ,
                      lAmount  => null ,
                      DebitRate  => 0 ,
                      CreditRate => 0 ,
                      trName => outTransactionDesc ,
                      flags  => 0 ,
                      TransactionDate => HDate
                     );
     end if;
     
     ReserveForwardAmount := ROUND((CreditRest + Amount) * newReservePercent / 100 , 2 ); -- % --
     inTransactionDesc := inTransactionDesc || sbcm_stored_programs.ContractNumAsVarchar2(ContractID);     
     if  ReserveForwardAmount > 0 then
     ReserveOutTransactionID := 
     SB_TRANSACTION.Transaction_Add (
                      DebitID  => AccForOutReserve ,
                      CreditID => ReserveAccID ,
                      DebitAmount => null ,
                      CreditAmount=> ReserveForwardAmount ,
                      lAmount  => null ,
                      DebitRate  => 0 ,
                      CreditRate => 0 ,
                      trName => inTransactionDesc ,
                      flags  => 0 ,
                      TransactionDate => HDate
                     );
     end if;
     
     end if; --TransactionsON
     
     SetSecondaryReserve(ContractID , newReserveID);
     if  commitOnChange  then  commit;  end if;
    
   end;  

  procedure ChangeReserve(
            ContractID in integer ,
            HDate in date ,
            newReserveID in integer ,
            newExpiredReserveID in integer ,
            changePReserve in boolean ,
            changeSReserve in boolean ,
            TransactionsON in boolean     
            )
   is
   InTransactionID integer;
   OutTransactionID integer;
   begin
   SB_ACA.CheckObjectAccess('CREDITMANAGER','update');  --adm
     if changePReserve then
     ChangePrimaryReserve(
           ContractID ,
           HDate ,
           newReserveID ,
           0 ,
           TransactionsON ,
           InTransactionID ,
           OutTransactionID    
           ); 
     end if;
     if changeSReserve then
     ChangeSecondaryReserve(
           ContractID ,
           HDate ,
           newExpiredReserveID ,
           0 ,
           TransactionsON ,
           InTransactionID ,
           OutTransactionID    
           ); 
     end if;

     commit;
     
   end;         
    
END;
/

