function  DaysOfBankYear return Integer
 Is
  Result VarChar2(3);
 begin
   Result :=GetReference('cmrYearDayCount');
	return TO_NUMBER(Result); 
 end;

function IsCalculationEnabled(ContractID IN SBCM_Contracts.ID%type) 
