function  GetSelectedAccID(
           ContractID IN SBCM_Contracts.ID%type
					,SettingName IN SBCM_Movie_Names.Name%type 
          ) return Account.ID%type
 Is
   CategoryID Number;
	 ParentID Number;
	 CurrencyID Number;
	 Result Account.ID%type;
 begin 
   CurrencyID :=GetContractCurrency(ContractID);
   CategoryID :=GetClientCategoryFromID(ContractID);
	 ParentID :=GetMovieIDByName(CategoryID,SettingName);
	 Result :=GetAccIDFromSettings(ParentID,CurrencyID);
	 if  Result is Null  then
	   RAISE_APPLICATION_ERROR(-20076,'Selected AccID  Not Found!^');
	 end if; 
	 return Result;
	 	 
 end;					
