	begin
/*	  open c_UserNameById(ID);
		fetch c_UserNameById into Result;
		close c_UserNameById;
   		return Result;
*/
    return sb_aca.getuserbyid(ID);--adm
	end;

	function GetSessionID
		return integer
	as
		cursor c_SessionIDByAudSID(v_AudSID integer)
		is
			select SID from sys.v_$session
			where AudSID = v_AudSID;
		Result integer;
	begin
   -- sb_aca.checkuserconnected(user);
		open c_SessionIDByAudSID(UserEnv('SESSIONID'));
		fetch c_SessionIDByAudSID into Result;
		if c_SessionIDByAudSID%notfound then
			Result := null;
		end if; 
		close c_SessionIDByAudSID;
		if Result is null then
			raise_application_error(sbdecls.Error_SessionNotFound, 'Session not found');
		end if;
		return Result;	 
	end;
  	
  procedure ChangeUserPsw (NewPsw in varchar)
  is
    ExecuteableQuery varchar(255);
    UserName varchar(255) := USER;                         
  begin
