  	return integer
  is
  	Result integer;
  begin
    insert into modules (
      NAME,
      DESCRIPTION)
    values  (
      v_name,
      v_description
		)
  	returning ID into Result;
  	return Result;
  end;
  
  procedure upd_module (v_id number, v_name varchar ,v_description varchar)
  is
  begin
          update modules
          set
                  NAME = v_name,
      DESCRIPTION = v_description
    where
                  ID = v_id;
