CREATE OR REPLACE 
PACKAGE sbmsg
  IS
	
	function get_message(MsgID integer)
		return varchar2;
	function get_message(MsgName varchar2)
		return varchar2;
	
  function format_msg(Message varchar2, ParamStr varchar2)
		return varchar2;
  function get_error(
		ErrorCode integer, 
		Message out varchar2)
	return boolean;
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY sbmsg
IS

	function get_message(MsgID integer)
		return varchar2
	is
		Result SB_MESSAGES.TEXT%type;
	begin
		select TEXT	
			into Result
			from SB_MESSAGES
		where
			ID = MsgID;
		return Result;
	exception
		when NO_DATA_FOUND then
			raise_application_error(
				sbdecls.Error_MessageNotFound,
				'Message with ID '||TO_CHAR(MsgID)||' could not be found');
	end;
	
	function get_message(MsgName varchar2)
		return varchar2
	is
		Result SB_MESSAGES.TEXT%type;
	begin
		select TEXT	
			into Result
			from SB_MESSAGES
		where
			Name = MsgName;
		return Result;
	exception
		when NO_DATA_FOUND then
			raise_application_error(
				sbdecls.Error_MessageNotFound,
				'Message "'||MsgName||'" could not be found'
			);
	end;
	
	function format_msg(Message varchar2, ParamStr varchar2)
		return varchar2
	is
		subtype t_params is sbutil.t_params;
		ParamCount integer;
		Params t_params;
	begin
		Params := sbutil.comma_to_params(ParamStr, ParamCount);
		return sbutil.expand_macroses(Message, Params);
	end;
		
	function get_error(
		ErrorCode integer, 
		Message out varchar2)
	return boolean
	is
	begin
		begin
			select text
				into Message
			from SB_ERRORS
			where ID = ErrorCode;
		exception
		when NO_DATA_FOUND then
			return False;
		end;
		
		return True;
	end;

END;
/

