  function add_custinfo (
    v_idcust          number,
    v_soname          varchar2 default null,
    v_name            varchar2 default null,
    v_lastname        varchar2 default null,
    v_birthday        date default null,
    v_birthplace      varchar2 default null,
    v_passer          varchar2 default null,
    v_paspnum         number default null,
    v_paspdate        date default null,
    v_paspplace       varchar2 default null,
    v_city            varchar2 default null,
    v_address         varchar2 default null,
    v_workplace       varchar2 default null,
    v_phone_w         varchar2 default null,
    v_phone_h         varchar2 default null,
    v_phone_m         varchar2 default null,
    v_e_mail          varchar2 default null,
    v_url             varchar2 default null,
    v_recomendation   varchar2 default null,
    v_garanted        varchar2 default null,
    v_photo           varchar2 default null,
    v_custsign        blob default null
  )
  return integer
  is
    CustInfoID integer;
  begin
    insert into custinfo
                (idcust, soname, name, lastname, birthday,
                 birthplace, passer, paspnum, paspdate, paspplace,
                 city, address, workplace, phone_w, phone_h,
                 phone_m, e_mail, url, recomendation, garanted
                 )
         values (v_idcust, v_soname, v_name, v_lastname, v_birthday,
                 v_birthplace, v_passer, v_paspnum, v_paspdate, v_paspplace,
                 v_city, v_address, v_workplace, v_phone_w, v_phone_h,
                 v_phone_m, v_e_mail, v_url, v_recomendation, v_garanted
                 );

    select tr_seg_CUSTINFO.currval
      into CustInfoID
      from dual;

    return CustInfoID;
  end;

  function del_custinfo (v_id number)
  return integer
  is
    CustomerID integer;
    CustInfoCount integer;
  begin
    select IDCust
      into CustomerID
      from CustInfo;

    delete from CUSTINFO
          where Id = v_id;

    select count(*)
      into CustInfoCount
      from CustInfo
    where IDCust = CustomerID;

    return CustInfoCount;
  end;
  
  procedure upd_tenostat(
    v_acc_id integer,
    v_LastOpDate date, 
    Amount number,
    LAmount number,
    DebitTurnover number,
    DebitLTurnover number,
    CreditTurnover number,
    CreditLTurnover number)
  as
  begin
    update tenostat
    set
        OSTAT = Amount,
        POK_OSTAT = LAmount,
        DatDate = v_LastOpDate,
        OBR_D = DebitTurnover,
        POK_OBR_D = DebitLTurnover,
        OBR_K = CreditTurnover,
        POK_OBR_K = CreditLTurnover
    where
        acc_id = v_acc_id;
    if SQL%rowcount = 0 then
        raise_application_error(
            sbdecls.Error_InvalidParameters, 
            'Account (id='
                ||TO_CHAR(v_acc_id)||
                ') not found');
    end if; 
  end; 
  procedure delete_Custinfo(v_id integer)
  is
  begin
   Delete from custinfo
    where id=v_id;
    commit;
  end;
  procedure del_all_excaccount(v_exchangeID number)
  is
  begin
   SB_ACA.CheckObjectAccess('EXCHANGE','delete');  --adm
  Delete from Exchanges
  where ID=v_exchangeID;
  commit;
  end;
	
Function  GetTakedID return Number
 Is
 TakedID CustInfo.ID%Type;
 Begin
    Select  tr_seg_CUSTINFO.currval Into	TakedID
		     From dual;
	return  TakedID; 			   							
 End;
end;
