  procedure CheckRDSettings(AccID integer, CurrencyID integer) as
  begin
    if AccID is null then
      raise_application_error(
        sbdecls.Error_RateDifferenceSettings,
           'Rate difference settings not set for currency #'
        || TO_CHAR(CurrencyID)
      );
    end if;
