--------------------------------------------------------
Function calc_rate_difference return integer as 
		-- TempID of new transactions set
  cursor c_RateDifference(TekDate date, PredDate date) is (
                  SELECT
                    a.id,
                  	v.valute as currencyid,
                  	a.val_acc as AccCurrencyID,
                    v.debet as debet,
                    v.kredit as kredit,
                    t.ostat as ostat,
                    o.ostat- o2.ostat as deltarate,
                    Abs(t.ostat * o.ostat - t.pok_ostat) as sum_transaction 
                  --  Abs(t.ostat * o.ostat - t.ostat * o2.ostat)
                  FROM
                    ACCOUNT a,
                    archost t,
                    bal_spr1 b,
                    operkurs o,
                    operkurs o2,
                    avalute v
                  WHERE
                    (a.val_acc <> 0)
                  	and (t.datdate = PredDate)
                    AND (t.acc_id = a.id)
                    AND (a.bal_cn1 = b.bal_cn)
                    AND (b.RateDifference = 1)
                    AND (a.close_dat IS NULL)
                    AND (a.val_acc = v.valute)
                    and (o.val_kod = a.val_acc)
                    AND (o.val_kod = o2.val_kod)
                    AND (t.ostat <>0)
                    AND (o.ostat - o2.ostat<>0) 
                    AND (o.dat = TekDate)
                    AND (o2.dat = PredDate));
	
  DebitAccID integer;
  CreditAccID integer;
		DebitCurrencyID integer;
		CreditCurrencyID integer;
		DebitAmount number;
		CreditAmount number;
		DebitRate number;
		CreditRate number;
  Amount number(14, 2);
		TempTrID integer;
  RateData c_RateDifference%rowtype;
  TrName varchar2(64) := 'ћ€з€нн€ ф€рги';
  TrCount  Integer := 0;

  TekDate Date;
  PredDate Date;

  begin
    select Tek_Dat, Pred_dat into TekDate, PredDate from sysdat;
		
    for RateData in c_RateDifference(TekDate, PredDate)
    loop
      /* analize what's changed */
      DebitAccID := null; -- if not modified in next statement - no transaction needed
      if ((RateData.ostat > 0) and (RateData.DeltaRate < 0))
         or ((RateData.ostat < 0) and (RateData.DeltaRate > 0))
      then
        DebitAccID := RateData.ID;
        CreditAccID := RateData.Kredit;
        DebitCurrencyID:=RateData.AccCurrencyID;
        CreditCurrencyID:=0;        
        CheckRDSettings(CreditAccID, RateData.CurrencyID);
      elsif (RateData.ostat < 0) and (RateData.DeltaRate < 0)
            or (RateData.ostat > 0) and (RateData.DeltaRate > 0)
      then
        DebitAccID := RateData.Debet;
        CreditAccID := RateData.ID;
        DebitCurrencyID:=0;
        CreditCurrencyID:=RateData.AccCurrencyID;        
        CheckRDSettings(DebitAccID, RateData.CurrencyID);
      end if;
			if DebitCurrencyID = 0 then
				DebitAmount := RateData.sum_transaction;
			else
				DebitAmount := 0; 
			end if;
			if CreditCurrencyID = 0 then
				CreditAmount := RateData.sum_transaction;
			else
				CreditAmount := 0; 
			end if;
      /* add transaction */
      if DebitAccID is not null
      then
				TempTrID :=
    			SB_TRANSACTION.transaction_add(
--    				TempID => TempID,
    				DebitID  => DebitAccID,
    				CreditID => CreditAccID,
    				DebitAmount => DebitAmount,	-- debit
    				CreditAmount => CreditAmount,
    				LAmount => RateData.sum_transaction,
   					OperationType => 1,
    				DebitRate => 0,
    				CreditRate => 0,
    				TrName => TrName,
    				Flags => sbdecls.atfCommitImmediate
								);
      TrCount := TrCount + 1;                
      end if;
    end loop;
		commit;
    return TrCount;
end;
