CREATE OR REPLACE 
PACKAGE sbsec
IS

	/* *********************************************** */
  /*      SmartBank Security Management  package     */
	/*  Copyright 2002, Smart Systems Technology, Ltd. */
  /* *********************************************** */

--- 
--- 
---	Package contains security management routines
---
---

	/* types & constants */

	subtype t_sid is SECURITY_sid$.id%type; 
	subtype t_object_type is SECURITY_sid$.type#%type;
	subtype t_client is security_clients$.ID%type;
	subtype t_user is t_client;
	subtype t_group is t_client;
	subtype t_access is SECURITY_access$.id%type;
	subtype t_access_name is SECURITY_access$.name%type;

	default_object constant t_object_type := null;

	/* procedures */

  function access_reg(
		name t_access_name,
		description varchar2
	)
		return t_access;
  procedure access_unreg(
		access_id t_access
	);
  procedure access_unreg(
		access_name t_access_name
	);
  procedure access_user_grant(
		sid t_sid, 
		user_id t_user, 
		access_id t_access);
  procedure access_user_grant(
		sid t_sid,
		user_id t_user,
		access_name t_access_name);
  procedure access_user_revoke(
		sid t_sid,
		user_id t_user,
		access_id t_access);
  procedure access_user_revoke(
		sid t_sid,
		user_id t_user,
		access_name t_access_name);
  function build_default(sid t_sid)
		return boolean;
  procedure group_delete(GroupID integer);
  procedure sid_destroy(sid t_sid);
  function sid_create(
		user# integer default sbutil.get_user_id,
		group# integer default sbutil.get_group_id,
		type# t_object_type default default_object
	)
		return t_sid;
  procedure user_create_repository(UserID integer, Password varchar2);
  procedure user_delete(UserID integer);
  function get_type_id (type_name varchar2)
		return t_object_type;
  procedure user_set_password(UserID varchar2, NewPassword varchar2);
  procedure group_membership_add(ClientID integer, GroupID integer);
  procedure group_membership_array(ClientID integer, arr varchar2);
  procedure group_membership_revoke(ClientID integer, GroupID integer);
  function group_add(name varchar2, description varchar2)
		return t_user;
  procedure group_edit(GroupID integer, NewName varchar2, NewDescription varchar2);
  procedure user_edit(UserID integer, UserName varchar2, NewDescription varchar2, v_filial number);
  procedure group_roles_array(group# integer, arr varchar2);
  procedure user_role_add(UserName varchar2, RoleName varchar2);
  function access_check_int(
		client# integer,
		sid# integer,
		Access# integer)
	return integer;
  procedure sid_rights_array(
		sid integer, 
		ClientID integer, 
		arr varchar2);
  procedure sid_try_delete(sid# integer);
  function GetLoggedUser
		return integer;
  function GetUserName(v_user_id t_user)
		return varchar2;
  function client_sid_get(clientID integer)
		return t_sid;
  procedure client_sid_set(clientID integer, SID t_sid);
  function right_check(
		AccessName varchar2,
		user# integer default sblogin.UserID)
	return boolean;
  procedure right_check(
		AccessName varchar2,
		user# integer default sblogin.UserID);
  function client_id_get(name varchar2)
		return integer;
  function access_check(
		client# integer, 
		sid# integer, 
		access# integer)
	return boolean;
  function access_check(
		SAccessArr varchar2,
		client# integer default sblogin.UserID,
		sid# integer default null)
	return boolean;
  procedure access_check(
		SAccessArr varchar2,
		client# integer default sblogin.UserID,
		sid# integer default null);
  function module_get_sid(ModuleName varchar2)
		return t_sid;
  function link_add(sid# integer, user# t_user)
	return integer;
  procedure link_remove(link# integer);
  function get_access_descr(access# varchar2)
		return varchar2;
  procedure user_recreate_repository(UserID integer);
  function user_add(
      UserName varchar2, 
   			Description varchar2,
      DefaultGroupID integer,
      Password varchar2,
      CreateUser boolean default True,
      CreateRepository boolean default True,
   			GroupIDs varchar2 default null,
			   RightIDs varchar2 default null,
						v_Filial number default 0)
    return t_user;
  function group_is_member(client# integer, group# integer)
		return boolean;
  function client_is_user(ClientID integer)
		return boolean;
  function client_type_get(ClientID integer)
		return integer;
  function client_is_group(ClientID integer)
		return boolean;
END;
/

CREATE OR REPLACE 
PACKAGE BODY sbsec
IS

	Merr_InvalidSID constant varchar2(37) := 'Invalid security descriptor specified';
	Merr_InvalidSecurityLink constant varchar2(21) := 'Invalid security link';
    
  SecurityClientType_User  constant integer := 1;
  SecurityClientType_Group constant integer := 2;
	
	subtype t_str_array is sbutil.t_str_array;

  cursor c_group_roles(group# integer)
  is
  		select r.RoleID, u.name as Name
  	from security_group_roles r, sys.user$ u 
  		where
  			(r.GroupID = Group#)
  		and (u.user# = r.RoleID)
  for update;

	function sid_create(
		user# integer default sbutil.get_user_id,
		group# integer default sbutil.get_group_id,
		type# t_object_type default default_object
	)
		return t_sid
	as
		Result t_sid;
	begin
		dbms_output.put_line('create_sid called. Type: '||TO_CHAR(type#));
		insert into SECURITY_sid$ (
			user#, group#, type#)
		values (
			user#, group#, type#)
		returning ID into Result;

--		dbms_output.put_line('SBSEC.create_sid: created sid = '||Result);
		return Result; 
	end;

	procedure invalid_sid
	as
	begin
		raise_application_error(
			sbdecls.Error_InvalidSID, 
			Merr_InvalidSID);
	end;

  procedure sid_destroy(sid t_sid)
	as
	begin
--		dbms_output.put_line('destroy_sid called');
		delete from SECURITY_sid$
		where id = sid;
		if SQL%rowcount = 0 then
			invalid_sid;
		end if; 
	end;
	
	function sid_get_user_id(sid integer)
		return integer
	as
		Result integer;
	begin
		select user#
			into Result
			from security_sid$
		where
			ID = sid;
		return Result;
	end;
---------------------------------------------------
	function get_access_id(AName varchar2)
		return integer
	as
		Result integer;
	begin
--		dbms_output.put_line(SUBSTR('get_access_id called. Name: '||AName, 1, 255));
		select id	into Result from SECURITY_access$
		where name = AName;
		return Result;
	end;
-----------------------------------------
	function GetLoggedUser return integer as
	begin
		return sblogin.UserID;
	end;
	
	function GetUserName(v_user_id t_user)
		return varchar2
	as
		UserName security_clients$.name%type;
	begin
		select Name
			into UserName
			from user$
			where id = v_user_id;
		return UserName;
	end;

	function get_access_name(access# varchar2)
		return varchar2
	as
		Result SECURITY_access$.name%type;
	begin
		select name into Result
			from SECURITY_access$
			where ID = access#;
		return Result;
	end;

	function get_access_descr(access# varchar2)
		return varchar2
	as
		Result SECURITY_access$.description%type;
	begin
		select description into Result
			from SECURITY_access$
			where ID = access#;
		return Result;
	end;

	procedure DumpGrantUserAccessParams(
		sid t_sid, 
		user_id t_user, 
		access_id t_access,
		access_name varchar2)
	as
		AccessID t_access;
		AccessName t_access_name;
	begin
/*
		if access_id is null then
			if access_name is null then
  			AccessName := '(no name)';
				AccessID := -1;
			else
				AccessName := access_name;
				AccessID := get_access_id(AccessName);
			end if;
		else
			AccessID := access_id;
			AccessName := get_access_name(AccessID);
		end if;

		dbms_output.put_line('==========================');
		dbms_output.put_line('grant_user_access params:');
		dbms_output.put_line('==========================');
		dbms_output.put_line('sid: '||TO_CHAR(sid));
		dbms_output.put_line('user: '||TO_CHAR(user_id)||' ('||GetUserName(user_id)||')');
		dbms_output.put_line('access: '||TO_CHAR(AccessID)||' ('||AccessName||')');
		dbms_output.put_line('===end=of==params=dump====');
*/		
        null;
	end;

	function get_client_link(
		v_sid# integer, 
		v_client# integer)
	return integer
	as
		Result integer;
	begin
		select id into result
			from SECURITY_sid_client_link
			where (sid# = v_sid#) and (client# = v_client#);
		return result;
	exception
	when NO_DATA_FOUND then
		return -1;
	end;

	function link_add(sid# integer, user# t_user)
	return integer
	as
		Result integer;
	begin
		insert into SECURITY_sid_client_link (
			sid#, client#)
		values (
			sid#, user#)
		returning ID into Result;
		return Result;
	end;

	procedure link_access_add(link# integer, access# integer)
	as
		AccessID integer;
	begin
		insert into SECURITY_sid_link_access (
			link#, access#)
		values (
			link#, access#)
		returning ID into AccessID;
--		dbms_output.put_line('Created AccessID: '||TO_CHAR(AccessID));
	end;
	
	procedure link_access_remove(link# integer)
	as
	begin
		delete from SECURITY_sid_link_access
		where ID = link#;
	end;

	procedure access_user_grant(
		sid t_sid, 
		user_id t_user, 
		access_id t_access)
	as
		LinkID integer;
	begin
--		dbms_output.put_line('grant_user_access called');
		DumpGrantUserAccessParams(sid, user_id, access_id, null);

		LinkID := get_client_link(sid, user_id);
		if LinkID = -1 then
--			dbms_output.put_line('creating access link');
			LinkID := link_add(sid, user_id);
		end if;
--		dbms_output.put_line('LinkID: '||TO_CHAR(LinkID));
		link_access_add(LinkID, access_id);
	end;

  procedure access_user_grant(
		sid t_sid,
		user_id t_user,
		access_name t_access_name)
	as
	begin
--		dbms_output.put_line('grant_user_access-2 called');
		DumpGrantUserAccessParams(
			sid, user_id, null, access_name
		);
		access_user_grant(sid, user_id, get_access_id(access_name));
	end;

	procedure access_user_revoke(
		sid t_sid,
		user_id t_user,
		access_id t_access)
	as
		cursor c_sid_link_access
		is
			select *
  		from SECURITY_sid_link_access
  		where 
  			link# = (
  				select ID  
  					from SECURITY_sid_client_link
  					where (sid# = sid) and (client# = user_id))
  			and (access# = access_id)
		for update;
	begin
--		dbms_output.put_line('revoke_user_access called');
		DumpGrantUserAccessParams(sid, user_id, access_id, null);
		
		for la in c_sid_link_access
		loop
			link_access_remove(la.ID);
		end loop;
	end;

	procedure access_user_revoke(
		sid t_sid,
		user_id t_user,
		access_name t_access_name)
	as
	begin
--		dbms_output.put_line('revoke_user_access-2 called');
--		DumpGrantUserAccessParams(sid, user_id, null, access_name);
		access_user_revoke(sid, user_id, get_access_id(access_name)); 
	end;

	function access_reg(
		name t_access_name,
		description varchar2
	)
		return t_access
	as
		Result t_access;
	begin
		insert into SECURITY_access$ (
			name, description)
		values (
			name, description
		)
		returning ID into Result;
		return Result;
	end;

	procedure access_unreg(
		access_id t_access
	)
	as
	begin
--		dbms_output.put_line('unreg_access called');
		delete from SECURITY_access$
		where ID = access_id;
	end;
 
	procedure access_unreg(
		access_name t_access_name
	)
	as
	begin
--		dbms_output.put_line('unreg_access-2 called');
		delete from SECURITY_access$
		where name = access_name;
	end;

	function get_object_type(sid# t_sid)
		return t_object_type
	as
		Result t_object_type;
	begin
		select type# into Result
			from SECURITY_sid$
			where id = sid#;
		return Result;
	exception
		when NO_DATA_FOUND then
			invalid_sid;
	end;

	procedure link_remove(link# integer)
	as
	begin
		delete from SECURITY_sid_client_link
		where ID = link#;
		if SQL%rowcount = 0 then
			raise_application_error(sbdecls.Error_InvalidParameters, Merr_InvalidSecurityLink);
		end if;
	end;

	function build_default(sid t_sid)
		return boolean
	as
		obj_type integer;
		LinkID integer;
		cursor c_client is
			select ID, sid, client#
			from security_default_user
			where objtype# = obj_type;
		client c_client%rowtype;
		Result boolean := FALSE;
	begin
--		dbms_output.put_line(substr('build_default_security called',1,255));
		select type# into obj_type
			from SECURITY_sid$
			where id = sid;
		delete from SECURITY_sid_client_link
			where sid# = sid;

		for client in c_client 
		loop
--			dbms_output.put_line(substr('Value of client.client#='||client.client#,1,255));
--			dbms_output.put_line(substr('Value of sid='||sid,1,255));

			insert into SECURITY_sid_client_link (
				sid#, client#)
			values (
				sid, client.client#);

			select sid_client_link_id_gen.currval
				into LinkID
				from dual;

--			dbms_output.put_line(substr('Value of LinkID='||LinkID,1,255));

			insert into SECURITY_sid_link_access (
				link#, access#)
			select LinkID, access#
				from security_default_access
				where link# = client.ID;

--			dbms_output.put_line(substr(TO_CHAR(SQL%rowcount)||' row(s) appended',1,255));

			Result := TRUE;

		end loop;

		return Result;

	end;

	function get_type_id (type_name varchar2)
		return t_object_type
	as
		Result integer;
	begin
		select id into Result
			from security_object_type
			where name = type_name;
		return Result;		
	end;

  function get_user_id
  return integer
  as
    Result integer;
		UserID integer;
  begin
		UserID := sbutil.get_user_id;
		select id into Result
			from security_clients$
			where SysID = UserID;
		return Result;
  end;

	function group_add(name varchar2, description varchar2)
		return t_user
	as
		Result integer;
	begin
--		dbms_output.put_line(substr('group_add called. name='||name,1,255));

		insert into security_clients$ (name, description, flags, type#, sid#)
		values (name, description, 0, SecurityClientType_Group, null)
        returning ID into Result; 

		client_sid_set(
			Result, 
			sid_create(
				GetLoggedUser, 
				Result, 
				get_type_id('Group')
			)
		);
			
		return Result;	
	end;
    
  procedure group_edit(GroupID integer, NewName varchar2, NewDescription varchar2)
  as
  begin
--    dbms_output.put_line(substr('group_edit called. ID='||TO_CHAR(GroupID)||', Name='||NewName,1,255));

    update security_clients$ 
    set 
      name = NewName,
			description = NewDescription
    where
      ID = GroupID;
  end;
  
  procedure group_delete(GroupID integer)
  as
  begin
--    dbms_output.put_line(substr('group_delete called. ID='||TO_CHAR(GroupID),1,255));
		client_sid_set(GroupID, null);
		sid_try_delete(client_sid_get(GroupID));
    delete from security_clients$
    where
        ID = GroupID;
  end;
  
  function build_create_user_params(UserID integer, Password varchar2)
    return varchar2
  is
    UserName varchar2(64);
  begin
    select name
      into UserName 
      from user$
    where ID = UserID;
    return 'PublicPrefix=,UserName='||UserName||',UserNamePrefix='||UserName||',Password='||Password;
  end;

  procedure user_create_repository(UserID integer, Password varchar2)
  as
  begin
    dbms_output.put_line('user_create_repository in execution. UserID='||TO_CHAR(UserID));
    sbinstall.execute_task(
      'user_create',
      build_create_user_params(UserID, Password),
      False);
  end;
	
	procedure user_drop_repository(UserID integer)
	as
	begin
--		dbms_output.put_line('user_drop_repository in execution. UserID='||TO_CHAR(UserID));
    sbinstall.execute_task(
      'user_delete',
      'UserName='||GetUserName(UserID),
      False);
	end;
	
	procedure user_recreate_repository(UserID integer)
	as
		cursor c_user_objects(UserID integer)
		is
			select * from all_objects
			where owner = (
				select username from ALL_USERS
				where user_id = (
					select SysID from security_clients$ where ID = UserID
				)			
			);
		DropCmd varchar2(128);
		c integer;
		rown integer;
	begin
		for r_user_object in c_user_objects(UserID)
		loop
			DropCmd := 'DROP ' || r_user_object.object_type || ' ' || r_user_object.owner || '.' || r_user_object.object_name;
			dbms_output.put_line(DropCmd);
			c := dbms_sql.open_cursor();
			dbms_sql.parse(c,DropCmd,dbms_sql.NATIVE);
			rown := dbms_sql.execute(c);
			dbms_sql.close_cursor(c);
		end loop;		
    sbinstall.execute_task(
      'user_add',
      build_create_user_params(UserID, ''),
      False);
	end;
-------------------------------------------------  
  function user_add(
      UserName varchar2, 
   	  Description varchar2,
      DefaultGroupID integer,
      Password varchar2,
      CreateUser boolean default True,
      CreateRepository boolean default True,
   	  GroupIDs varchar2 default null,
      RightIDs varchar2 default null,
      v_Filial number default 0)
    return t_user 
  as
    Result t_user;
		RightsSID t_sid;
		SysUserID integer;
  begin
		access_check('Right_SecurityUserAdd');
		
--    dbms_output.put_line(substr('user_add called. Name='||UserName,1,255));
    insert into security_clients$ (
      name, description, flags, type#, Group#, filialID)
    values (
      UserName, description, 0, SecurityClientType_User, null, v_Filial 
		)
    returning ID into Result;
		
		RightsSID :=
			sid_create(
				Result, 
				DefaultGroupID, 
				get_type_id('User')
			);
		client_sid_set(
			Result,
			RightsSID
		);
		
--    if CreateUser then
      user_create_repository(Result, Password);
			
	select user#	into SysUserID from sys.user$ 	where	upper(name)=upper(UserName);
	update security_clients$ set SysID = SysUserID	where ID = Result; 
--      end if;
			
			user_set_password(Result, Password);
			
			if GroupIDs is not null then
				group_membership_array(Result, GroupIDs);
			end if;
			
			if RightIDs is not null then
				sid_rights_array(RightsSID, Result, RightIDs);
			end if; 
			
			user_recreate_repository(Result);
  		
    return Result;
  end;
---------------------------------------------
	procedure user_edit(
	  UserID integer
	, UserName varchar2
	, NewDescription varchar2
	, v_Filial number)
	as
	begin
		update security_clients$
		set
			Name = UserName,
			Description = NewDescription,
   filialID=v_filial
		where
			ID = UserID;
	end;
---------------------------------------------
  procedure user_delete(UserID integer)
  as
  begin
		access_check('Right_SecurityUserDrop');
--    dbms_output.put_line(substr('user_delete called. ID='||TO_CHAR(UserID),1,255));
		user_drop_repository(UserID);
    delete from security_clients$
    where
      ID = UserID;
  end;
	
