CREATE OR REPLACE 
PACKAGE sburep
  IS
	
	/*
	|| SmartBank Universal Report Package
	 */

  function exec_macros(macros varchar2, Periodic boolean, StartDate date, EndDate date)
		return number;
END;
/

CREATE OR REPLACE 
PACKAGE BODY sburep
IS

	function exec_block(block varchar2, Periodic boolean, StartDate date, EndDate date)
		return number
	as
		BracketLeftPos integer;
		BracketRightPos integer;
		FunctionName varchar2(16);
		ParamList varchar2(256);
		SCurrencyID varchar2(3);
		CurrencyID integer;
		params sbutil.t_str_array;
		pcount integer;
		Query varchar2(1024);
		CurrentDate date;
		ParsedParams varchar2(256);
		Result number := 0;
	begin
		dbms_output.put_line('Executing block: '||block);
		if BracketLeftPos = 0 then
			raise_application_error(sbdecls.Error_InvalidParameters, 'Missing left bracket');
		end if;    
		BracketLeftPos := instr(block, '(');	
		FunctionName := substr(block, 1, BracketLeftPos-1);
		dbms_output.put_line('Function name: '||FunctionName);
		
		BracketRightPos := instr(block, ')', BracketLeftPos+1);
		if BracketRightPos = 0 then
			raise_application_error(sbdecls.Error_InvalidParameters, 'Missing right bracket');		
		end if;
		
		ParamList := substr(block, BracketLeftPos+1, BracketRightPos-BracketLeftPos-1);
		dbms_output.put_line('Params: '||ParamList);
		
		params := sbutil.comma_to_array(ParamList,pcount);
		SCurrencyID := params(1);
		if SCurrencyID = '*' then
			CurrencyID := -1;
		else
			CurrencyID := TO_NUMBER(SCurrencyID);
		end if;

		params.DELETE(1);
		dbms_output.put_line('CurrencyID: '||SCurrencyID);
		dbms_output.put_line('Param count: '||TO_CHAR(params.COUNT));
		
		if Periodic then
		
			CurrentDate := StartDate;
			loop
				Result := 
					Result + 
						sburep_utl.call_macro_function(
						FunctionName,
						CurrencyID,
						CurrentDate,
						params);
				CurrentDate := CurrentDate + 1;
				exit when CurrentDate > EndDate;
			end loop;
		else
			Result := 
				Result + 
					sburep_utl.call_macro_function(
					FunctionName,
					CurrencyID,
					StartDate,
					params);			
			
		end if;
		
		return Result;
	end;	

	function exec_macros(macros varchar2, Periodic boolean, StartDate date, EndDate date)
		return number
	is
		Operation char;
		Block varchar2(64);
		BlockResult integer;
		P integer;
		LastP integer := 0;
		MaxP integer := Length(macros)+1;
		Result number := 0;
	begin
		loop
			P := sburep_utl.find_ch_pos('+', '-', macros, Operation, LastP+1);
			if P = 0 then
				P := MaxP;
			end if;
			block := substr(macros, lastP+1, P-LastP-1);
			
			BlockResult := exec_block(block, Periodic, StartDate, EndDate);
			if Operation = '+' then
				Result := Result + BlockResult;
			elsif Operation = '-' then
				Result := Result - BlockResult;
			elsif Operation = '*' then
				Result := Result * BlockResult;
			elsif Operation = '/' then
				Result := Result / BlockResult;								
			end if;
			
			lastP := P;
			exit when P = MaxP;
		end loop;
		
		return Result;
	end;
	 
END;
/

