			TargetDate date, 
			params varchar2)
  	return number
  is
  begin
		return ExecStdQuery(CurrencyID, TargetDate, params, '', CustomQueryPart_Account);		
  end;
  
  function acc_lbalance(
			CurrencyID integer, 
			TargetDate date, 
			params varchar2)
  	return number
  is
  begin
		return ExecStdQuery(CurrencyID, TargetDate, params, 'pok', CustomQueryPart_Account);		
