  function gen_unique_id
  return integer
  as
    Result integer;
  begin
    select SB_UNIQUE_ID.nextval
    into Result
    from dual;

    return Result;
  end;

  function get_user_id
  return integer
  as
    Result integer;
  begin
    select USER_ID into Result
    from all_users
    where UPPER(USERNAME) = UPPER(user);
    return Result;
  end;

	function get_group_id(user# integer)
	return integer
	as
		Result integer;
	begin
		/*select group#
		into Result
		from user$
		where SysID = user#;
		return Result;*/ --adm
    return 1;
	end;

	function get_group_id
		return integer
	as
	begin
		return get_group_id(get_user_id);
	end;

	function comma_to_array(
			text varchar2,
			p_count out integer,
			comma_delimiter varchar2 default CommaDelimiter)
		return t_str_array
	as
		cd_pos integer;
		last_cd_pos integer := 0;
		text_length integer := length(text);
    Result t_str_array;-- := t_str_array();
		Ind integer := 1;
	begin
		p_count := 0;
		if text_length <> 0 then
    	loop
        exit when cd_pos = text_length+1;
      	cd_pos := instr(text, comma_delimiter, last_cd_pos+1);
  			if cd_pos = 0 then
  				cd_pos := text_length+1;
  			end if;
  			p_count := p_count + 1;
  --			Result.EXTEND;
        Result(Ind) := substr(text, last_cd_pos+1, cd_pos-last_cd_pos-1);
  			Ind := Ind + 1;
        last_cd_pos := cd_pos;
      end loop;
		end if;
    return Result;
	end;

	function array_to_comma(arr t_str_array)
		return varchar2
	is
		item varchar2(64);
		Ind binary_integer := arr.FIRST;
		CommaFrag varchar2(3) := '';
		Result varchar2(1024) := '';
	begin
		dbms_output.put_line('arr.count: '||to_char(arr.count));

		for Ind in arr.FIRST .. arr.LAST
		loop
			item := arr(Ind);
			Result := Result || CommaFrag || item;
			CommaFrag := ', ';
		end loop;

/*
		loop
			exit when Ind >= arr.COUNT;
			item := arr(Ind);
			Ind := arr.NEXT(ind);
			Result := Result || CommaFrag || item;
			CommaFrag := ', ';
		end loop;
*/
		return Result;
	end;

	function comma_to_params(
			text varchar2,
			p_count out integer,
			comma_delimiter varchar2 default CommaDelimiter,
			param_delimiter varchar2 default ParamDelimiter)
		return t_params
	as
  	cd_pos integer;	-- comma delimiter position
		pd_pos integer; -- param delimiter position
    last_cd_pos integer := 0;
    Result t_params := t_params();
		ParamStr varchar2(1024);
		text_length integer := length(text);
	begin
		p_count := 0;
  	loop
      exit when (cd_pos = text_length+1) or (text is Null) or (text = '');

    	cd_pos := instr(text, comma_delimiter, last_cd_pos+1);
			if cd_pos = 0 then
				cd_pos := text_length+1;
			end if;

			ParamStr := substr(text, last_cd_pos+1, cd_pos-last_cd_pos-1);
			pd_pos := instr(ParamStr, param_delimiter);

			p_count := p_count + 1;
			Result.EXTEND;

      Result(p_count).param :=
				substr(ParamStr, 1, pd_pos-1);

			Result(Result.LAST).value :=
				substr(
					ParamStr,
					pd_pos+1,
					length(ParamStr));

      last_cd_pos := cd_pos;

    end loop;
    return Result;
	end;

	function get_param_value(
		params t_params,
		name varchar2,
		ErrorIfNotFound boolean default False
	)
		return varchar2
	as
		Ind BINARY_INTEGER := params.FIRST;
	begin
		loop
			exit when Ind is null;
			if params(Ind).param = name then
				return params(Ind).value;
			end if;
			Ind := params.NEXT(Ind);
		end loop;
		if ErrorIfNotFound then
			raise_application_error(
				sbdecls.Error_InvalidParameters,
				'Invalid parameter name');
		else
			return null;
		end if;
	end;

	function expand_macroses(text varchar2, Params t_params)
		return varchar2
	is
	  p integer := -1;
  	lastp integer := 1;
	  varname varchar2(64);
		AText varchar2(2000) := text;
		Result varchar2(2000);
	begin
		Result := AText;
		loop
		  loop
  		  p := instr(Result, '$(', lastp);
    		if p = 0 then
      		exit;
		    end if;
  		  varname := SUBSTR(Result, p+2, instr(Result, ')', p)-p-2);
				Result := replace(Result, '$('||varname||')', get_param_value(params,
varname));
	    	lastp := p+2;
	  	end loop;
			exit when Result = AText;
			AText := Result;
		end loop;
		return Result;
	end;
  
  function  FlagExsist(AccID in Integer,FlagChar in Char)
  return 
    Boolean
  is
    AccountType Account.TipAcc%type;
    Result Boolean;
  begin
    select  upper(TipAcc) 
    into AccountType
    from Account
    where ID = AccID;
    
    Result := FlagExsist(AccountType,FlagChar);
        
    return   Result;
  end;      

  function  FlagExsist(AccountType in Account.TipAcc%type,FlagChar in Char)
  return 
    Boolean
  is
    Result Boolean;
    Pos integer := 0;    
  begin
  
    if (AccountType is null) or (AccountType = '') then
    return false;
    end if;
    
    if (FlagChar is null) or (FlagChar = '') then
    raise_application_error(-20032,'FlagChar can"t be null! ');
    end if;
     
    Pos := instr(upper(AccountType) ,upper(FlagChar));
    Result  := ( Pos > 0 );
    return   Result;
  end;        

  function  FindAccFlag(AccID in Integer,FlagName in Varchar2)
  return 
    Boolean
  is
    AccountType Account.TipAcc%type;
    Result Boolean;
    FlagChar char(1);    
  begin
    select  upper(TipAcc) 
    into AccountType
    from Account
    where ID = AccID;
    
    select symbol 
    into FlagChar
    from Account_Flags
    where name = FlagName;
    
    Result := FlagExsist(AccountType,FlagChar);
           
    return   Result;
  end;      

 /* function  FlagsExsist(
     AccountType in Account.TipAcc%type ,
     Flags in Varchar2 ,
     sPartial in Boolean default false
     )
  return 
    Integer
  is
    Result Integer := 0;
    StrLength Integer;
    AccFlags Account.tipacc%type := Flags;
    flgExsist Boolean := TRUE;
    ch char(1);            
  begin
    
    AccFlags := Replace(AccountType,CommaDelimiter);
    StrLength := Length(AccFlags);
    
    if (AccFlags is NULL) or (StrLength < 1) then
      return 0;
    end if;
      
    for  POS  in  1..StrLength
    loop
      ch := substr(AccFlags,POS,1);
      flgExsist :=flgExsist and FlagExsist(ch,AccountType);
      exit when flgExsist;            
    end loop;
    
    if flgExsist then
      Result  := 1;
    else
      Result  := 0;
    end if;
      
    return   Result;
  end;          
*/    
end;
/

CREATE OR REPLACE 
package smp_maintenance AS
	procedure RESET_SYSMAN;
end;
/

CREATE OR REPLACE 
package body smp_maintenance AS


/*-------------------------------------------------------------------*/
/* Reset Sysman			                                             */
/* This procedure resets the sysman password to its initial state.   */
/* the initial value is the same as the encrypted form found in      */
/* the em base creation scripts.                                     */
/*-------------------------------------------------------------------*/
PROCEDURE reset_sysman IS
	BEGIN
		update SMP_VDU_PRINCIPALS_TABLE set password = '9ed0fa64a76b4bd912310580f74926ca'
		where principal_name = UPPER('SYSMAN');
		commit;
	END;

end SMP_MAINTENANCE;
