CREATE OR REPLACE 
PACKAGE BODY swiftcontrolnew
IS
   --NEW REFERENCE
   FUNCTION swiftnewreference (val_cod INTEGER)
      RETURN VARCHAR2
   IS
      newref    INTEGER;
      valname   VARCHAR2 (3);
      result    VARCHAR2 (16);
   BEGIN
      SELECT swift_reference.NEXTVAL
        INTO newref
        FROM DUAL;

      SELECT val_name
        INTO valname
        FROM avalute
       WHERE valute = val_cod;

      result :=    TO_CHAR (sbop.get_date, 'yymmdd')
                || valname
                || newref;
      RETURN result;
   END;

   --Delete From Swlift Table 
   PROCEDURE swiftindelete (v_id INTEGER)
   IS
      rwcount   INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO rwcount
        FROM swift_in;

      IF rwcount > 0
      THEN
         DELETE FROM swift_in
               WHERE id = v_id;

         COMMIT;
      END IF;
   END;
------------------------
PROCEDURE Swift_IN_Edit (
 v_ID          Number,
 v_SenderBIC   Varchar,
 v_ReceiverBIC Varchar,
 v_F50_Memo    Varchar,
 v_F70         Varchar,
 v_F71A        Varchar,
 v_F59_Memo    Varchar,
 v_Rec_Account Varchar,
 v_Rec_Acc_ID  Number,
 v_F32A_Curr   Number,
 v_F32A_Amount Number)
IS
BEGIN
  UPDATE Swift_IN
     SET SenderBIC=v_SenderBIC,
         ReceiverBIC=v_ReceiverBIC,
         F50_Memo=v_F50_Memo,
         F70=v_F70,
         F71A=v_F71A,
         F59_Memo=v_F59_Memo,
         Rec_Account=v_Rec_Account,
         Rec_Acc_ID=v_Rec_Acc_ID,
         F32A_Curr=v_F32A_Curr,
         F32A_Amount=v_F32A_Amount
       WHERE id = v_id;
  COMMIT;
END;
-------------
   --Update Swift Config
   PROCEDURE changeconfig (action INTEGER, v_value VARCHAR2)
   IS
      chindir        CONSTANT INTEGER := 1;
      choutdir       CONSTANT INTEGER := 2;
      charchivedir   CONSTANT INTEGER := 3;
      chaccount      CONSTANT INTEGER := 4;
      chcommision    CONSTANT INTEGER := 5;
      chCity         CONSTANT INTEGER := 6;
      chCountry      CONSTANT INTEGER := 7;                
   BEGIN
      IF action = chindir
      THEN
         UPDATE swiftconfig
            SET swindir = v_value;
      ELSIF action = choutdir
      THEN
         UPDATE swiftconfig
            SET swoutdir = v_value;
      ELSIF action = charchivedir
      THEN
         UPDATE swiftconfig
            SET swarchivedir = v_value;
      ELSIF action = chaccount
      THEN
         UPDATE swiftconfig
            SET swaccount = v_value;
      ELSIF action = chcommision
      THEN
         UPDATE swiftconfig
            SET commisionid = TO_NUMBER (v_value, '999999');
      ELSIF action = chCity
      THEN
         UPDATE swiftconfig
            SET City = v_value;
      ELSIF action = chCountry 
      THEN
         UPDATE swiftconfig
            SET Country = v_value;                  
      END IF;

      COMMIT;
   END;

   --Change Transaction Accounts 
   PROCEDURE changeaccount 
   (v_branch Integer,v_valute INTEGER, v_acc_id VarChar2)
   IS
   BEGIN
      DELETE FROM swiftaccounts
            WHERE branch=v_branch and valute = v_valute;

      INSERT INTO swiftaccounts
                  (branch,valute, acc_id)
           VALUES (v_branch,v_valute,v_acc_id);

      COMMIT;
   END;

   --GET REFERENCE
   FUNCTION GetReference (vcurrency VARCHAR2)
      RETURN VARCHAR2
   IS
      nextnumber   INTEGER;
      result       VARCHAR2 (16);
   BEGIN
    if vCurrency = 'AZM' then
      SELECT swift_reference.NEXTVAL
        INTO nextnumber
        FROM DUAL; end if;
        
    if vCurrency = 'USD' then
      SELECT swift_reference_USD.NEXTVAL
        INTO nextnumber
        FROM DUAL; end if;
        
    if vCurrency = 'EUR' then
      SELECT swift_reference_EUR.NEXTVAL
        INTO nextnumber
        FROM DUAL; end if;
        
    if vCurrency = 'GBP' then
      SELECT swift_reference_GBP.NEXTVAL
        INTO nextnumber
        FROM DUAL; end if;
        
    if vCurrency = 'SEK' then
      SELECT swift_reference_SEK.NEXTVAL
        INTO nextnumber
        FROM DUAL; end if;
        
    if vCurrency = 'CHF' then
      SELECT swift_reference_CHF.NEXTVAL
        INTO nextnumber
        FROM DUAL; end if;
        
    if vCurrency = 'CAD' then
      SELECT swift_reference_CAD.NEXTVAL
        INTO nextnumber
        FROM DUAL; end if;
        
    if vCurrency = 'RUB' then
      SELECT swift_reference_RUB.NEXTVAL
        INTO nextnumber
        FROM DUAL; end if;

        
        
      result :=
                  TO_CHAR (SYSDATE, 'YYMMDD')
               || UPPER (vcurrency)
               || nextnumber;
      RETURN result;
   END;

   --GENERATE FILE FOR SWIFT
   FUNCTION generatefile (v_reference VARCHAR, v_opercode VARCHAR)
      RETURN BOOLEAN
   IS
   BEGIN
      DBMS_OUTPUT.put_line (' ');
   END;

