PROCEDURE SetIncomingTransaction 
(v_id       NUMBER,
 v_BranchID NUMBER)
   IS
      v_Kod_Fil        NUMBER;
      v_BIC            VARCHAR(15);
      transactionid    NUMBER;
      accountval_kod   NUMBER;
      v_commisionid    NUMBER;
      v_debitid        NUMBER;
      v_creditid       NUMBER;
      v_amount         NUMBER;
      v_valute         NUMBER;
      v_trname         VARCHAR2 (255);
      debit_id         NUMBER;
      accountclosed    NUMBER;
   BEGIN
   select Kod_Fil into v_Kod_Fil from BankInfo;
   
   SELECT F32A_Curr
           INTO v_valute
           FROM Swift_IN
          WHERE id = v_id;
   
   SELECT SenderBIC
           INTO v_BIC
           FROM Swift_IN
          WHERE id = v_id;
          
   if v_Kod_Fil=v_BranchID then 
      SELECT Rec_Acc_ID
        INTO v_creditid
        FROM Swift_IN
       WHERE id = v_id;
   else
      select Acc_ID
        into v_CreditId
        from SwiftAccounts
       where Branch=v_BranchId and valute=v_valute;
   end if;      

      --Check for closed account 
      SELECT id
        INTO accountclosed
        FROM ACCOUNT
       WHERE (id = v_creditid) AND (close_dat IS NULL);

      --check credit account 
      IF  (v_creditid > 0) AND (accountclosed > 0)
      THEN
         /*SELECT F32A_Curr
           INTO v_valute
           FROM Swift_IN
          WHERE id = v_id;*/
      if v_valute<>0 then
         SELECT Acc_id
           INTO v_debitID
           FROM Swift_CorAccounts
          WHERE (BIC = v_BIC and valute = v_valute);
       else   
         SELECT Acc_id
           INTO v_debitID
           FROM SwiftAccounts
          WHERE (Branch=v_Kod_Fil and valute = 0);
      end if;
          
         SELECT F32A_Amount
           INTO v_amount
           FROM Swift_IN
          WHERE id = v_id;

         SELECT F50_Memo
           INTO v_trname
           FROM Swift_IN
          WHERE id = v_id;
                  
         SELECT val_acc
           INTO accountval_kod
           FROM ACCOUNT
          WHERE (id = v_creditid);

         SELECT commisionid
           INTO v_commisionid
           FROM SwiftConfig;
         --transactions
         transactionid :=
               sb_transaction.transaction_add (
                  debitid=> v_debitid,
                  creditid=> v_creditid,
                  debitamount=> v_amount,
                  creditamount=> NULL,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=>    'ўесаба дахилолма - '
                           || v_trname,
                  flags => 0,
                  parentid=> NULL,
                  
--                               inbalancechar => 0,
--                               outbalancechar => 0,
--                               transactionid => null,
--                               parentid => null,
--                               tempid => null,
                  operationtype=> 18,
                  transactiondate=> getdefaultdate
               );
         -- CHANGE ICON to accept                     
         Swift_IN_ChangeStatus (v_id, 1);
      ELSE
         -- CHANGE ICON to reject                                             
         Swift_IN_ChangeStatus (v_id, 2);
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         Swift_IN_ChangeStatus (v_id, 2);
         dbms_output.put_line(
            SUBSTR (   'Error '
                    || TO_CHAR (SQLCODE)
                    || ': '
                    || SQLERRM, 1, 255)
         );
   COMMIT;
   END;
--------------------------------------------------------------------------------
PROCEDURE Set_OUT_Transaction 
(v_id       NUMBER,
 v_BranchID NUMBER,
 v_ValuteID NUMBER,
 v_TransValute NUMBER)
   IS
      v_Kod_Fil          NUMBER;
      v_BIC              VARCHAR(15);
      transactionid      NUMBER;
      v_debitid          NUMBER;
      v_creditid         NUMBER;
      v_amount           Number;
      v_commisionid      NUMBER;
      accountval_kod     NUMBER;
      debit_id           NUMBER;
      curs               NUMBER (22, 2);
      iconresult         NUMBER;
      customersid        INTEGER;
      reject_commision   INTEGER;
      bal_cn             INTEGER;
      TransactionsDate   DATE;
      ClientAccount      INTEGER;
      AccName            VARCHAR (90);
      TransName          VARCHAR (250);
      AccountClosed      NUMBER;
      v_LAmount          Number;
BEGIN
   select Kod_Fil into v_Kod_Fil from BankInfo;
  
   SELECT ReceiverBIC
           INTO v_BIC
           FROM Swift_OUT
          WHERE id = v_id;
          
   if v_Kod_Fil=v_BranchID then 
      SELECT F50_Account
        INTO v_debitid
        FROM Swift_OUT
       WHERE id = v_id;
   else
      select Acc_ID
        into v_debitid
        from SwiftAccounts
      where Branch=v_BranchId and Valute=v_TransValute;
   end if;      

          --Check for closed account 
        SELECT count(*)
          INTO AccountClosed
          FROM ACCOUNT
         WHERE (ID = v_debitid) AND (close_dat IS NULL);

          SELECT val_acc
           INTO accountval_kod
           FROM ACCOUNT
          WHERE (id = v_debitId); 

          SELECT Name
           INTO AccName
           FROM ACCOUNT
          WHERE (id = v_debitId); 
          
      if v_TransValute<>0 then
         SELECT Acc_id
           INTO v_creditid
           FROM Swift_CorAccounts
          WHERE (BIC = v_BIC and valute = v_TransValute);
       else   
         SELECT Acc_id
           INTO v_creditid
           FROM SwiftAccounts
          WHERE (Branch=v_Kod_Fil and valute = 0);
      end if;
          
         SELECT F32A_Amount
           INTO v_amount
           FROM Swift_OUT
          WHERE id = v_id;
          
         select Ostat*v_Amount 
           into v_LAmount
           from Operkurs
          where (val_kod = v_TransValute) and (dat = sbop.get_date);    
        
         SELECT CommisionId
           INTO v_commisionid
           FROM SwiftConfig;

         SELECT ostat
           INTO curs
           FROM operkurs
          WHERE (val_kod = accountval_kod) AND (dat = sbop.get_date);

         --Bank daxili hesablardan kommisiya 
         SELECT bal_cn1
           INTO bal_cn
           FROM ACCOUNT
          WHERE (id = v_debitId) AND (close_dat IS NULL);

         IF ((bal_cn >= 3300) AND (bal_cn <= 3999))
         THEN
            CLIENTACCOUNT := 1;
            TransName :=    'SWIFT  ючцрм€ - '
                         || TO_CHAR (v_amount);
         ELSE
            CLIENTACCOUNT := 0;
            TransName :=    'SWIFT  ючцрм€ - '
                         || AccName;
         END IF;
         
    IF (v_debitid>0) AND (AccountClosed>0) THEN 
         TransactionsDate := GetDefaultDate;
         Transactionid :=
               sb_transaction.transaction_add (
                  debitid=> v_debitid,
                  creditid=> v_creditid,
                  debitamount=> NULL,
                  creditamount=> v_amount,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=> TransName,
                  flags => 0,
                  -- inbalancechar => 0,
                  -- outbalancechar => 0,
                  -- transactionid => null,
                  -- parentid => null,
                  -- tempid => null
                  parentid=> NULL,
                  operationtype=> 18,
                  transactiondate=> TransactionsDate
               );

         --CHILD TRANSACTION
         IF CLIENTACCOUNT = 1
         THEN
            sb_complex_transactions.settransactions (
               v_commisionid,
               v_debitid,
               v_creditid,
               v_LAmount,
               v_LAmount,
               TransactionsDate
            );
         END IF; 
         -- CHANGE ICON to accept                     
         UPDATE Swift_OUT
         SET status = 1
         WHERE id = v_id; 
         ELSE
         -- CHANGE ICON to reject                                             
         UPDATE Swift_OUT
         SET status = 2
         WHERE id = v_id;
      END IF;

/*            RAISE_APPLICATION_ERROR (
               -20998,
               SUBSTR (
                     'Error '
                  || TO_CHAR (SQLCODE)
                  || ': '
                  || SQLERRM,
                  1,
                  255));*/  
END;
------------------------------------------------------------------
FUNCTION GetDefaultDate
RETURN DATE
IS
  v_usebankdate   INTEGER;
  result          DATE;
BEGIN
  SELECT UseBankDate
    INTO v_usebankdate
    FROM SwiftConfig;
  IF v_usebankdate = 1
   THEN result := sbop.get_date;
   ELSE result := TRUNC (SYSDATE);
  END IF;

RETURN result;
END;
-------------
PROCEDURE Swift_IN_ChangeStatus (v_id NUMBER, v_status NUMBER)
IS
BEGIN
  UPDATE Swift_IN
         SET status = v_status
       WHERE id = v_id;

  COMMIT;
END;
-------------
FUNCTION Swift_OUT_ChangeStatus (v_id NUMBER, v_status NUMBER)
      RETURN INTEGER
   IS
      result         INTEGER;
      v_accept       INTEGER;
      messagecount   INTEGER;
   BEGIN
      --If message no commited
      IF v_status = 0
      THEN
         UPDATE Swift_OUT
            SET status = v_status
          WHERE id = v_id;

         result := 1;
         COMMIT;
      END IF;

      IF v_status = 2
      THEN
         UPDATE Swift_OUT
            SET status = v_status
          WHERE id = v_id;

         result := 1;
         COMMIT;
      END IF;

      RETURN result;
   END;

   
END;
/

