      v_f59_account         SwiftScheme.f59_account%TYPE,
      v_f59_bic             SwiftScheme.f59_bic%TYPE,
      v_f59_name_address    SwiftScheme.f59_name_address%TYPE,
      v_f70                 SwiftScheme.f70%TYPE,
      v_f71a                SwiftScheme.f71a%TYPE,
      v_f71f                SwiftScheme.f71f%TYPE,
      v_f71f_child          SwiftScheme.f71f_child%TYPE,
      v_f71g                SwiftScheme.f71g%TYPE,
      v_f71g_child          SwiftScheme.f71g_child%TYPE,
