                   f50 = v_f50, 
                   f50_account = v_f50_account, 
                   f50_bic = v_f50_bic,
                   f50_name_address = v_f50_name_address, 
                   f51a = v_f51a, 
                   f51a_a = v_f51a_a, 
                   f51a_b = v_f51a_b, 
                   f52 = v_f52,
                   f52_account = v_f52_account, 
                   f52_bic = v_f52_bic, 
                   f52_name_address = v_f52_name_address, 
                   f53 = v_f53,
                   f53_account = v_f53_account, 
                   f53_bic = v_f53_bic, 
                   f53_name_location = v_f53_name_location, 
                   f54 = v_f54,
                   f54_account = v_f54_account, 
                   f54_bic = v_f54_bic, 
                   f54_name_location = v_f54_name_location, 
                   f55 = v_f55,
                   f55_account = v_f55_account, 
                   f55_bic = v_f55_bic, 
                   f55_name_location = v_f55_name_location, 
                   f56 = v_f56,
                   f56_account = v_f56_account, 
                   f56_bic = v_f56_bic, 
                   f56_name_address = v_f56_name_address, 
                   f57 = v_f57,
                   f57_account = v_f57_account, 
                   f57_bic = v_f57_bic, 
                   f57_name_location = v_f57_name_location, 
                   f59 = v_f59,
                   f59_account = v_f59_account, 
                   f59_bic = v_f59_bic, 
                   f59_name_address = v_f59_name_address, 
                   f70 = v_f70,
                   f71a = v_f71a, 
