                   f71f_child = v_f71f_child, 
                   f71g = v_f71g, 
                   f71g_child = v_f71g_child, 
                   f72 = v_f72,
                   f77b = v_f77b, 
                   f77t = v_f77t
      WHERE 
                   ID= V_ID;              
      COMMIT;
   END;

   procedure swiftscheme_delete(V_ID  INTEGER) 
   is
   begin
     DELETE FROM SWIFTSCHEME 
           WHERE ID = V_ID;
     COMMIT;             
   end;

