PROCEDURE SetIncomingTransaction 
(v_id       NUMBER,
 v_BranchID NUMBER)
   IS
      v_Kod_Fil        NUMBER;
      v_BIC            VARCHAR(15);
      transactionid    NUMBER;
      accountval_kod   NUMBER;
      v_commisionid    NUMBER;
      v_debitid        NUMBER;
      v_creditid       NUMBER;
      v_amount         NUMBER;
      v_valute         NUMBER;
      v_trname         VARCHAR2 (255);
      debit_id         NUMBER;
      accountclosed    NUMBER;
   BEGIN
   select Kod_Fil into v_Kod_Fil from BankInfo;
   
   SELECT F32A_Curr
           INTO v_valute
           FROM Swift_IN
          WHERE id = v_id;
   
   SELECT SenderBIC
           INTO v_BIC
           FROM Swift_IN
          WHERE id = v_id;
          
   if v_Kod_Fil=v_BranchID then 
      SELECT Rec_Acc_ID
        INTO v_creditid
        FROM Swift_IN
       WHERE id = v_id;
   else
      select Acc_ID
        into v_CreditId
        from SwiftAccounts
       where Branch=v_BranchId and valute=v_valute;
   end if;      

      --Check for closed account 
      SELECT id
        INTO accountclosed
        FROM ACCOUNT
       WHERE (id = v_creditid) AND (close_dat IS NULL);

      --check credit account 
      IF  (v_creditid > 0) AND (accountclosed > 0)
      THEN
         /*SELECT F32A_Curr
           INTO v_valute
           FROM Swift_IN
          WHERE id = v_id;*/
      if v_valute<>0 then
         SELECT Acc_id
           INTO v_debitID
           FROM Swift_CorAccounts
          WHERE (BIC = v_BIC and valute = v_valute);
       else   
         SELECT Acc_id
           INTO v_debitID
           FROM SwiftAccounts
          WHERE (Branch=v_Kod_Fil and valute = 0);
      end if;
          
         SELECT F32A_Amount
           INTO v_amount
           FROM Swift_IN
          WHERE id = v_id;

         SELECT F50_Memo
           INTO v_trname
           FROM Swift_IN
          WHERE id = v_id;
                  
         SELECT val_acc
           INTO accountval_kod
           FROM ACCOUNT
          WHERE (id = v_creditid);

         SELECT commisionid
           INTO v_commisionid
           FROM SwiftConfig;
         --transactions
         transactionid :=
               sb_transaction.transaction_add (
                  debitid=> v_debitid,
                  creditid=> v_creditid,
                  debitamount=> v_amount,
                  creditamount=> NULL,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=>    'ўесаба дахилолма - '
                           || v_trname,
                  flags => 0,
                  parentid=> NULL,
                  
--                               inbalancechar => 0,
--                               outbalancechar => 0,
--                               transactionid => null,
--                               parentid => null,
--                               tempid => null,
                  operationtype=> 18,
                  transactiondate=> getdefaultdate
               );
         -- CHANGE ICON to accept                     
         Swift_IN_ChangeStatus (v_id, 1);
      ELSE
         -- CHANGE ICON to reject                                             
         Swift_IN_ChangeStatus (v_id, 2);
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         Swift_IN_ChangeStatus (v_id, 2);
         dbms_output.put_line(
            SUBSTR (   'Error '
                    || TO_CHAR (SQLCODE)
                    || ': '
                    || SQLERRM, 1, 255)
         );
   COMMIT;
   END;
--------------------------------------------------------------------------------
PROCEDURE Set_OUT_Transaction 
(v_id       NUMBER,
 v_BranchID NUMBER,
 v_ValuteID NUMBER)
   IS
      v_Kod_Fil          NUMBER;
      v_BIC              VARCHAR(15);
      transactionid      NUMBER;
      v_debitid          NUMBER;
      v_creditid         NUMBER;
      v_amount           Number;
      v_commisionid      NUMBER;
      accountval_kod     NUMBER;
      debit_id           NUMBER;
      curs               NUMBER (22, 2);
      iconresult         NUMBER;
      customersid        INTEGER;
      reject_commision   INTEGER;
      bal_cn             INTEGER;
      TransactionsDate   DATE;
      ClientAccount      INTEGER;
      AccName            VARCHAR (90);
      TransName          VARCHAR (250);
      AccountClosed      NUMBER;
BEGIN
   select Kod_Fil into v_Kod_Fil from BankInfo;
  
   SELECT ReceiverBIC
           INTO v_BIC
           FROM Swift_OUT
          WHERE id = v_id;
          
   if v_Kod_Fil=v_BranchID then 
      SELECT F50_Account
        INTO v_debitid
        FROM Swift_OUT
       WHERE id = v_id;
   else
      select Acc_ID
        into v_debitid
        from SwiftAccounts
      where Branch=v_BranchId and Valute=v_ValuteId;
   end if;      

          --Check for closed account 
        SELECT count(*)
          INTO AccountClosed
          FROM ACCOUNT
         WHERE (ID = v_debitid) AND (close_dat IS NULL);

          SELECT val_acc
           INTO accountval_kod
           FROM ACCOUNT
          WHERE (id = v_debitId); 

          SELECT Name
           INTO AccName
           FROM ACCOUNT
          WHERE (id = v_debitId); 
          
      if accountval_kod<>0 then
         SELECT Acc_id
           INTO v_creditid
           FROM Swift_CorAccounts
          WHERE (BIC = v_BIC and valute = accountval_kod);
       else   
         SELECT Acc_id
           INTO v_creditid
           FROM SwiftAccounts
          WHERE (Branch=v_Kod_Fil and valute = 0);
      end if;
          
         SELECT F32A_Amount
           INTO v_amount
           FROM Swift_OUT
          WHERE id = v_id;
        
         SELECT CommisionId
           INTO v_commisionid
           FROM SwiftConfig;

         SELECT ostat
           INTO curs
           FROM operkurs
          WHERE (val_kod = accountval_kod) AND (dat = sbop.get_date);

         --Bank daxili hesablardan kommisiya 
         SELECT bal_cn1
           INTO bal_cn
           FROM ACCOUNT
          WHERE (id = v_debitId) AND (close_dat IS NULL);

         IF ((bal_cn >= 3300) AND (bal_cn <= 3999))
         THEN
            CLIENTACCOUNT := 1;
            TransName :=    'SWIFT  ючцрм€ - '
                         || TO_CHAR (v_amount);
         ELSE
            CLIENTACCOUNT := 0;
            TransName :=    'SWIFT  ючцрм€ - '
                         || AccName;
         END IF;
         
    IF (v_debitid>0) AND (AccountClosed>0) THEN 
         TransactionsDate := GetDefaultDate;
         Transactionid :=
               sb_transaction.transaction_add (
                  debitid=> v_debitid,
                  creditid=> v_creditid,
                  debitamount=> NULL,
                  creditamount=> v_amount,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=> TransName,
                  flags => 0,
                  -- inbalancechar => 0,
                  -- outbalancechar => 0,
                  -- transactionid => null,
                  -- parentid => null,
                  -- tempid => null
                  parentid=> NULL,
                  operationtype=> 18,
                  transactiondate=> TransactionsDate
               );

         --CHILD TRANSACTION
       /*  IF CLIENTACCOUNT = 1
         THEN
            sb_complex_transactions.settransactions (
               v_commisionid,
               v_debitid,
               v_creditid,
               v_amount,
               v_amount,
               TransactionsDate
            );
         END IF; */
         -- CHANGE ICON to accept                     
         UPDATE Swift_OUT
         SET status = 1
         WHERE id = v_id; 
         ELSE
         -- CHANGE ICON to reject                                             
         UPDATE Swift_OUT
         SET status = 2
         WHERE id = v_id;
      END IF;

/*            RAISE_APPLICATION_ERROR (
               -20998,
               SUBSTR (
                     'Error '
                  || TO_CHAR (SQLCODE)
                  || ': '
                  || SQLERRM,
                  1,
                  255));*/  
END;
------------------------------------------------------------------
FUNCTION GetDefaultDate
RETURN DATE
IS
  v_usebankdate   INTEGER;
  result          DATE;
BEGIN
  SELECT UseBankDate
    INTO v_usebankdate
    FROM SwiftConfig;
  IF v_usebankdate = 1
   THEN result := sbop.get_date;
   ELSE result := TRUNC (SYSDATE);
  END IF;

RETURN result;
END;
-------------
PROCEDURE Swift_IN_ChangeStatus (v_id NUMBER, v_status NUMBER)
IS
BEGIN
  UPDATE Swift_IN
         SET status = v_status
       WHERE id = v_id;

  COMMIT;
END;
-------------
FUNCTION Swift_OUT_ChangeStatus (v_id NUMBER, v_status NUMBER)
      RETURN INTEGER
   IS
      result         INTEGER;
      v_accept       INTEGER;
      messagecount   INTEGER;
   BEGIN
      --If message no commited
      IF v_status = 0
      THEN
         UPDATE Swift_OUT
            SET status = v_status
          WHERE id = v_id;

         result := 1;
         COMMIT;
      END IF;

      IF v_status = 2
      THEN
         UPDATE Swift_OUT
            SET status = v_status
          WHERE id = v_id;

         result := 1;
         COMMIT;
      END IF;

      RETURN result;
   END;

   
END;
/

CREATE OR REPLACE 
PACKAGE v_extraction
  IS
 
  FUNCTION check_bal_number(balcn in varchar2)
     RETURN  number;
  function get_rate(accid in number, Dat date)
  return number;
  FUNCTION check_account_number(accno in varchar2, val_name out varchar2, accname out varchar2)
     RETURN  number;
  FUNCTION check_account_number(accno in varchar2, val_name out varchar2)
     RETURN  number;
  procedure get_ostat (acc_id in number,
                        begindate in date,
                        type in varchar2,
                        ostat out number,
                        pok_ostat out number);
  function get_ostat (acc_id in number,
                        begindate in date,
                        type in varchar2)
   return number;
  FUNCTION get_acc_param(accid in number, val_name out varchar2, accname out varchar2)
     RETURN  number;
END; -- Package spec
/

CREATE OR REPLACE 
PACKAGE BODY v_extraction
IS

   FUNCTION check_account_number(accno in varchar2, val_name out varchar2, accname out varchar2)
     RETURN  number
   is  
    result integer;
    cursor c_check is
     select acc.id, av.val_name, acc.name  
--       into result, val_name, accname 
       from account acc, avalute av
       where acc_no = accno
       and acc.val_acc = av.valute
       and close_dat is null;
     r_check c_check%rowtype;      
   BEGIN 
      open c_check;
      fetch c_check into r_check; 
      close c_check;
      val_name :=  r_check.val_name;
      accname := r_check.name;
      return r_check.id; 
   EXCEPTION
      WHEN no_data_found THEN
          return 0;
   END;

   FUNCTION check_account_number(accno in varchar2, val_name out varchar2)
     RETURN  number
   is  
    result integer;
   BEGIN 
     select acc.id, av.val_name
       into result, val_name
       from account acc, avalute av
       where acc_no = accno
       and acc.val_acc = av.valute;    
      return result; 
   EXCEPTION
      WHEN no_data_found THEN
          return 0;
   END;   

   FUNCTION get_acc_param(accid in number, val_name out varchar2, accname out varchar2)
     RETURN  number
   is  
    result integer;
   BEGIN 
     select acc.id, av.val_name, name
       into result, val_name, accname
       from account acc, avalute av
       where id = accid
       and acc.val_acc = av.valute;     
      return accid; 
   EXCEPTION
      WHEN no_data_found THEN
          return 0;
   END;    
   
   FUNCTION check_bal_number(balcn in varchar2)
     RETURN  number
   is  
    result integer;
   BEGIN 
     select bal_cn  
       into result 
       from bal_spr1
       where bal_cn = to_number(balcn);    
      return result; 
   EXCEPTION
      WHEN no_data_found THEN
          return 0;
   END;

   
   function get_old_date(accid number, bdate date)
     return date
   is
     result date;
   begin 
     SELECT MAX (arch.datdate)
         into result
         FROM archost arch
         WHERE arch.datdate < bdate
         AND arch.acc_id = accid;
     return result;
     
    exception when no_data_found then
       return null; 
   end;  

   function get_curr_date(accid number, bdate date)
     return date
   is
     result date;
   begin 
     SELECT MAX (arch.datdate)
         into result
         FROM archost arch
         WHERE arch.datdate <= bdate
         AND arch.acc_id = accid;
     return result;
     
    exception when no_data_found then
       return null; 
   end; 
      
   procedure get_ostat (acc_id in number,
                        begindate in date,
                        type in varchar2,
                        ostat out number,
                        pok_ostat out number)
   is
      cursor c_getbeginostat (accid in number, infodate in date) 
       is 
        SELECT arch.ostat, arch.pok_ostat
           FROM archost arch
           WHERE arch.datdate = infodate  
           AND arch.acc_id = accid;
         
     r_ostat c_getbeginostat%rowtype;
     tempdate date;
     ostat_not_found exception;
   begin
    
    if (acc_id is not null) and (begindate is not null) then

      if type = 'OLD' then 
        tempdate:=get_old_date(acc_id, begindate);
      elsif type = 'CURR' then
        tempdate:=get_curr_date(acc_id, begindate);
      else 
        raise ostat_not_found;      
      end if;    
     
    
     open c_getbeginostat(acc_id, tempdate );
      fetch c_getbeginostat into r_ostat; 
     close c_getbeginostat;

     if r_ostat.ostat <> 0 then   
       ostat := r_ostat.ostat;
       pok_ostat := r_ostat.pok_ostat;
     else
       raise ostat_not_found;
     end if;
    else
      raise ostat_not_found;
     end if;  

   exception when  ostat_not_found then
       ostat := 0;
       pok_ostat := 0;        
   end;                          

   
   function get_ostat (acc_id in number,
                        begindate in date,
                        type in varchar2)
   return number                     
   is
      cursor c_getbeginostat (accid in number, infodate in date) 
       is 
        SELECT arch.ostat, arch.pok_ostat
           FROM archost arch
           WHERE arch.datdate = infodate  
           AND arch.acc_id = accid;
         
     r_ostat c_getbeginostat%rowtype;
     tempdate date;
     ostat_not_found exception;
   begin
    
    if (acc_id is not null) and (begindate is not null) then

      if type = 'OLD' then 
        tempdate:=get_old_date(acc_id, begindate);
      elsif type = 'CURR' then
        tempdate:=get_curr_date(acc_id, begindate);
      else 
        raise ostat_not_found;      
      end if;    
     open c_getbeginostat(acc_id, tempdate );
      fetch c_getbeginostat into r_ostat; 
     close c_getbeginostat;

     if r_ostat.ostat <> 0 then   
       return  r_ostat.ostat;
     else
       raise ostat_not_found;
     end if;
    else
      raise ostat_not_found;
     end if;  

   exception when  ostat_not_found then
       return  0;       
   end;                          
   
  function get_rate(accid in number, Dat date)
  return number
  is
   result number;
  begin
    select ostat 
    into result
    from operkurs
     where dat = get_rate.dat
     and val_kod = (select val_acc from account where id = accid); 
    return result;
   exception when  no_data_found then
       return  0;     
  end;
   
END;
/

CREATE OR REPLACE 
PACKAGE wu_control
IS
   PROCEDURE wu_incoming_delete (v_id INTEGER);

   PROCEDURE PrincipialTrans (v_trans INTEGER);

   PROCEDURE WU_Accounts_Add (
      V_ACCID         INTEGER,
      V_currency      INTEGER,
      V_TYPE          VARCHAR,
      V_ACCOUNTTYPE   INTEGER,
      V_branch        INTEGER
   );
  PROCEDURE SetTransaction (INCOMID INTEGER);
  PROCEDURE WU_incoming_ChangeStatus(v_id integer ,V_STATUS INTEGER);
  PROCEDURE ImportReportTable (StDate DATE, EndDate DATE);
  PROCEDURE ConvertFileToTable (Rowbody VARCHAR2, INCOMDATE# OUT  DATE);
END;
/

CREATE OR REPLACE 
PACKAGE BODY wu_control

IS
   PROCEDURE wu_incoming_delete (v_id INTEGER)
   IS
   BEGIN
      DELETE FROM wu_incoming
            WHERE id = v_id;

      COMMIT;
   END;

   FUNCTION GetFileIncomDate (FILENAME VARCHAR2)
      RETURN DATE
   IS
      RESULT   DATE;
   BEGIN
      RESULT := To_Date(FILENAME,'MMDDYY');
      RETURN RESULT; 
   END;

   PROCEDURE ConvertFileToTable (Rowbody VARCHAR2,  INCOMDATE# OUT DATE)
   IS
      SECTIONSYMBOL   CONSTANT VARCHAR2 (1)   := ';';
      SECTIONCOUNT             INTEGER;
      SECTIONPOSITION          INTEGER;
      SECTIONPOSITION_         INTEGER;
      DATA                     VARCHAR2 (100);
      V_KIND                   VARCHAR2 (2);
      V_BRANCH                 VARCHAR2 (10);
      V_incomdate              DATE;
      V_reference              VARCHAR2 (20);
      V_currency               NUMBER;
      V_PRINCIPIAL             NUMBER (15, 2);
      V_CHARGES                NUMBER (15, 2);
      V_Revenue                NUMBER (15, 2);
   BEGIN
      SECTIONCOUNT := 1;
      V_KIND := SUBSTR (ROWBODY, 1, 1);

      LOOP
         SECTIONPOSITION := INSTR (ROWBODY, SECTIONSYMBOL, 1, SECTIONCOUNT);
         EXIT WHEN SECTIONPOSITION = 0;
         SECTIONCOUNT :=   SECTIONCOUNT
                         + 1;
         SECTIONPOSITION_ := INSTR (ROWBODY, SECTIONSYMBOL, 1, SECTIONCOUNT);
         DATA := SUBSTR (
                    ROWBODY,
                      SECTIONPOSITION
                    + 1,
                      SECTIONPOSITION_
                    - (  SECTIONPOSITION
                       + 1
                      )
                 );

         IF SECTIONCOUNT = 2
         THEN
            V_BRANCH := DATA;
         ELSIF SECTIONCOUNT = 3
         THEN
            V_INCOMDATE := TO_DATE (DATA, 'MMDDYYYY');
         ELSIF SECTIONCOUNT = 4
         THEN
            V_REFERENCE := DATA;
         ELSIF SECTIONCOUNT = 5
         THEN
            SELECT VALUTE
              INTO V_CURRENCY
              FROM AVALUTE
             WHERE VAL_NAME = DATA;
         ELSIF SECTIONCOUNT = 6
         THEN
            V_PRINCIPIAL := TO_NUMBER (DATA);
         ELSIF SECTIONCOUNT = 7
         THEN
            V_CHARGES := TO_NUMBER (DATA);
         ELSIF SECTIONCOUNT = 8
         THEN
            V_REVENUE := TO_NUMBER (DATA);
         END IF;
      END LOOP;

      INSERT INTO WU_INCOMING
                  (KIND, BRANCH, INCOMDATE, REFERENCE, CURRENCY,
                   PRINCIPIAL, CHARGES, REVENUE, CONVERTDATE)
           VALUES (V_KIND, V_BRANCH, V_INCOMDATE, V_REFERENCE, V_CURRENCY,
                   V_PRINCIPIAL, V_CHARGES, V_REVENUE, SYSDATE);
      INCOMDATE# :=V_INCOMDATE; 
      COMMIT;
   END;

   PROCEDURE WU_Accounts_Add (
      V_ACCID         INTEGER,
      V_currency      INTEGER,
      V_TYPE          VARCHAR,
      V_ACCOUNTTYPE   INTEGER,
      V_branch        INTEGER
   )
   IS
      EXISTSCUR   INTEGER DEFAULT 0;
   BEGIN
      SELECT COUNT (CURRENCY)
        INTO EXISTSCUR
        FROM WU_ACCOUNTS
       WHERE CURRENCY = V_CURRENCY
         AND TYPE = V_TYPE
         AND ACCOUNTTYPE = V_ACCOUNTTYPE
         AND BRANCHID = V_BRANCH;

      IF EXISTSCUR > 0
      THEN
         UPDATE WU_ACCOUNTS
            SET ACCID = V_ACCID,
                CURRENCY = V_CURRENCY,
                TYPE = V_TYPE,
                ACCOUNTTYPE = V_ACCOUNTTYPE
          WHERE CURRENCY = V_CURRENCY
            AND TYPE = V_TYPE
            AND ACCOUNTTYPE = V_ACCOUNTTYPE
            AND BRANCHID = V_BRANCH;
      ELSE
         INSERT INTO WU_ACCOUNTS
                     (ACCID, CURRENCY, TYPE, ACCOUNTTYPE, BRANCHID)
              VALUES (V_ACCID, V_CURRENCY, V_TYPE, V_ACCOUNTTYPE, V_BRANCH);
      END IF;

      COMMIT;
   END;

   PROCEDURE PrincipialTrans (v_trans INTEGER)
   IS
   BEGIN
      UPDATE wu_config
         SET PRINCIPIALTRANS = v_trans;

      COMMIT;
   END;

   PROCEDURE SetTransaction (INCOMID INTEGER)
   IS
      TransactionID      INTEGER;
      v_debitID          INTEGER;
      v_creditID         INTEGER;
      v_debitID#         INTEGER;
      v_creditID#        INTEGER;
      v_Amount           NUMBER (15, 2);
      principialtrans#   INTEGER;

      CURSOR INCOM
      IS
         SELECT w.*, v.val_name AS valute, wb.BranchName, wb.BranchID
           FROM WU_Incoming w, avalute v, wu_branch wb
          WHERE w.currency = v.valute(+)
            AND w.branch = wb.symbol(+)
            AND ID = INCOMID;

      RINCOM             INCOM%ROWTYPE;
   BEGIN
      OPEN INCOM;
      FETCH INCOM INTO RINCOM;
      CLOSE INCOM;

      IF RINCOM.STATUS > 0
      THEN
         RETURN;
      END IF;

      SELECT PRINCIPIALTRANS
        INTO PRINCIPIALTRANS#
        FROM WU_CONFIG;

      SELECT ACCID
        INTO V_DEBITID
        FROM WU_ACCOUNTS
       WHERE BRANCHID = RINCOM.BRANCHID
         AND TYPE = 'D'
         AND ACCOUNTTYPE = 1
         AND CURRENCY = RINCOM.CURRENCY;

      SELECT ACCID
        INTO V_CREDITID
        FROM WU_ACCOUNTS
       WHERE BRANCHID = RINCOM.BRANCHID
         AND TYPE = 'C'
         AND ACCOUNTTYPE = 1
         AND CURRENCY = RINCOM.CURRENCY;

      TransactionID :=
            sb_transaction.transaction_add (
               debitid=> v_debitID,
               creditid=> v_creditID,
               debitamount=> NULL,
               creditamount=> RINCOM.REVENUE,
               lamount=> NULL,
               debitrate=> NULL,
               creditrate=> NULL,
               trname=>    'Western Union цзр€ э€лир - '
                        || TO_CHAR (RINCOM.INCOMDATE, 'DD.MM.YYYY')
                        || ' - ('
                        || RINCOM.BRANCHNAME
                        || ')',
               flags => 0,
               -- inbalancechar => 0,
               -- outbalancechar => 0,
               -- transactionid => null,
               -- parentid => null,
               -- tempid => null
               parentid=> NULL,
               operationtype=> 17,
               transactiondate=> SBOP.GET_DATE
            );

      IF PRINCIPIALTRANS# = 1
      THEN
         SELECT ACCID
           INTO V_DEBITID#
           FROM WU_ACCOUNTS
          WHERE BRANCHID = RINCOM.BRANCHID
            AND TYPE = 'D'
            AND ACCOUNTTYPE = 0
            AND CURRENCY = RINCOM.CURRENCY;

         SELECT ACCID
           INTO V_CREDITID#
           FROM WU_ACCOUNTS
          WHERE BRANCHID = RINCOM.BRANCHID
            AND TYPE = 'C'
            AND ACCOUNTTYPE = 0
            AND CURRENCY = RINCOM.CURRENCY;

         TransactionID :=
               sb_transaction.transaction_add (
                  debitid=> v_debitID#,
                  creditid=> v_creditID#,
                  debitamount=> NULL,
                  creditamount=> RINCOM.PRINCIPIAL,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=>    'Western Union-кючцрм€си - '
                           || RINCOM.BRANCHNAME,
                  flags => 0,
                  -- inbalancechar => 0,
                  -- outbalancechar => 0,
                  -- transactionid => null,
                  -- parentid => null,
                  -- tempid => null
                  parentid=> NULL,
                  operationtype=> 17,
                  transactiondate=> SBOP.GET_DATE
               );
      END IF;

      WU_incoming_ChangeStatus (RINCOM.ID, 1);
   EXCEPTION
      WHEN OTHERS
      THEN
         BEGIN
            ROLLBACK;
            RAISE;
         END;

         COMMIT;
   END;

   PROCEDURE WU_incoming_ChangeStatus (v_id INTEGER, V_STATUS INTEGER)
   IS
   BEGIN
      UPDATE WU_INCOMING
         SET STATUS = V_STATUS
       WHERE id = v_id;

      COMMIT;
   END;

   PROCEDURE ImportReportTable (StDate DATE, EndDate DATE)
   IS
      CURSOR C_INCOM (ABRANCH VARCHAR)
      IS
         SELECT w.*, v.val_name AS valute
           FROM WU_Incoming w, avalute v
          WHERE w.currency = v.valute(+)
            AND w.branch = Abranch
            AND INCOMDATE BETWEEN STDATE AND ENDDATE;

      CURSOR C_BRANCH
      IS
         SELECT   *
             FROM WU_BRANCH
         ORDER BY BRANCHID;

      R_INCOM     C_INCOM%ROWTYPE;
      R_BRANCH    C_BRANCH%ROWTYPE;
      InAmount    NUMBER (15, 2);
      OutAmount   NUMBER (15, 2);
      ACount      INTEGER;
      ANom        INTEGER            DEFAULT 0;
      ARevenue    NUMBER (15, 2);
      NAME        VARCHAR2 (50);
   BEGIN
      ANom := 0;

      DELETE FROM WU_REPORT;

      COMMIT;
      OPEN C_BRANCH; --open batchs

      LOOP
         FETCH C_BRANCH INTO R_BRANCH;
         ACount := 0;
         InAmount := 0;
         OutAmount := 0;
         ARevenue := 0;
         ANom :=   ANom
                 + 1;
         OPEN c_incom (R_BRANCH.symbol); --open incoming

         LOOP
            FETCH C_INCOM INTO R_INCOM;
            EXIT WHEN C_INCOM%NOTFOUND;

            IF R_Incom.Revenue > 0
            THEN
               ACount :=   ACount
                         + 1;
               ARevenue :=   ARevenue
                           + R_Incom.Revenue;
            END IF;

            IF R_Incom.KIND = 'P'
            THEN
               InAmount :=   InAmount
                           + R_Incom.Principial;
            ELSIF R_Incom.KIND = 'S'
            THEN
               OutAmount :=   OutAmount
                            + R_Incom.Principial;
            END IF;
         END LOOP;

         CLOSE c_incom; --close incoming
         --create temporary report table
         EXIT WHEN C_BRANCH%NOTFOUND;

         INSERT INTO WU_REPORT
                     (nom, branch, transcount, amount_i, amount_o,
                      revenue)
              VALUES (ANom, R_BRANCH.BRANCHNAME, ACOUNT, InAmount, OutAmount,
                      ARevenue);
      END LOOP;

      INSERT INTO WU_REPORT
         SELECT NULL AS NOM, '∆яћ» ' AS BRANCH, SUM (TRANSCOUNT) AS TRANSCOUNT,
                SUM (AMOUNT_I) AS AMOUNT_I, SUM (AMOUNT_O) AS AMOUNT_O,
                SUM (REVENUE) AS REVENUE
           FROM WU_REPORT;

      CLOSE C_BRANCH; --close batchs
      COMMIT;
   END;
END;
/

