CREATE OR REPLACE 
PACKAGE BODY xs_controlold
IS
   
--------------------------------------------------------------------------------
   PROCEDURE SetIncomingTransaction (v_id NUMBER)
   IS
      transactionid    NUMBER;
      accountval_kod   NUMBER;
      v_commisionid    NUMBER;
      v_debitid        NUMBER;
      v_creditid       NUMBER;
      v_amount         NUMBER;
      v_valute         NUMBER;
      v_trname         VARCHAR2 (255);
      debit_id         NUMBER;
      accountclosed    NUMBER;
   BEGIN
      SELECT rec_client_acc_id
        INTO v_creditid
        FROM XS_INCOMING
       WHERE id = v_id;

      --Check for closed account 
      SELECT id
        INTO accountclosed
        FROM ACCOUNT
       WHERE (id = v_creditid) AND (close_dat IS NULL);

      --check credit account 
      IF  (v_creditid > 0) AND (accountclosed > 0)
      THEN
         SELECT val_cod
           INTO v_valute
           FROM XS_INCOMING
          WHERE id = v_id;

         SELECT Acc_id
           INTO v_debitID
           FROM XS_ACCOUNTS
          WHERE (valute = v_valute)
            AND (BRANCHID IN (SELECT FILIAL
                                FROM XS_INCOMING
                               WHERE ID = V_ID)
                );

         SELECT amount
           INTO v_amount
           FROM XS_INCOMING
          WHERE id = v_id;

         SELECT sen_name
           INTO v_trname
           FROM XS_INCOMING
          WHERE id = v_id;

         SELECT val_acc
           INTO accountval_kod
           FROM ACCOUNT
          WHERE (id = v_creditid);

         SELECT commisionid
           INTO v_commisionid
           FROM xs_config;

         --transactions
         transactionid :=
               sb_transaction.transaction_add (
                  debitid=> v_debitid,
                  creditid=> v_creditid,
                  debitamount=> v_amount,
                  creditamount=> NULL,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=>    'ўесаба дахилолма - '
                           || v_trname,
                  flags => 0,
                  parentid=> NULL,
                  
--                               inbalancechar => 0,
--                               outbalancechar => 0,
--                               transactionid => null,
--                               parentid => null,
--                               tempid => null,
                  operationtype=> 15,
                  transactiondate=> getdefaultdate
               );
         -- CHANGE ICON to accept                     
         xs_incoming_ChangeStatus (v_id, 1);
      ELSE
         -- CHANGE ICON to reject                                             
         xs_incoming_ChangeStatus (v_id, 2);
      END IF;
   EXCEPTION
      WHEN OTHERS
      THEN
         xs_incoming_ChangeStatus (v_id, 2);
         DBMS_OUTPUT.put_line (
            SUBSTR (   'Error '
                    || TO_CHAR (SQLCODE)
                    || ': '
                    || SQLERRM, 1, 255)
         );
         COMMIT;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE SetBatchsTransaction (v_id NUMBER)
   IS
      CURSOR creditmessages
      IS
         SELECT *
           FROM xs_beneficiary
          WHERE BatchID = v_id;

      messages           creditmessages%ROWTYPE;
      transactionid      NUMBER;
      v_debitid          NUMBER;
      v_creditid         NUMBER;
      v_commisionid      NUMBER;
      accountval_kod     NUMBER;
      debit_id           NUMBER;
      curs               NUMBER (22, 2);
      iconresult         NUMBER;
      customersid        INTEGER;
      reject_commision   INTEGER;
      bal_cn             INTEGER;
      TransactionsDate   DATE;
      ClientAccount      INTEGER;
      TransName          VARCHAR (250);
   BEGIN
      OPEN creditmessages;

      LOOP
         FETCH creditmessages INTO messages;
         EXIT WHEN creditmessages%NOTFOUND;

         SELECT acc_id
           INTO v_debitid
           FROM XS_BATCHS
          WHERE id = v_id;

         SELECT Acc_id
           INTO v_creditid
           FROM XS_ACCOUNTS
          WHERE (valute = messages.val_cod)
            AND (BRANCHID IN (SELECT FILIAL
                                FROM XS_BATCHS
                               WHERE ID = V_ID)
                );

         SELECT CommisionId
           INTO v_commisionid
           FROM XS_CONFIG;

         SELECT acc_id
           INTO debit_id
           FROM XS_BATCHS
          WHERE (id = messages.BatchID);

         SELECT val_acc
           INTO accountval_kod
           FROM ACCOUNT
          WHERE (id = debit_id);

         SELECT ostat
           INTO curs
           FROM operkurs
          WHERE (val_kod = accountval_kod) AND (dat = sbop.get_date);

         --Bank daxili hesablardan commisiya 
         SELECT bal_cn1
           INTO bal_cn
           FROM ACCOUNT
          WHERE (id = debit_id) AND (close_dat IS NULL);

         IF ((bal_cn >= 3300) AND (bal_cn <= 3999))
         THEN
            CLIENTACCOUNT := 1;
            TransName :=    ' ючцрм€ - '
                         || TO_CHAR (messages.amount);
         ELSE
            CLIENTACCOUNT := 0;
            TransName :=    ' ючцрм€ - '
                         || messages.client_name;
         END IF;

         TransactionsDate := GetDefaultDate;
         Transactionid :=
               sb_transaction.transaction_add (
                  debitid=> v_debitid,
                  creditid=> v_creditid,
                  debitamount=> NULL,
                  creditamount=> messages.amount,
                  lamount=> NULL,
                  debitrate=> NULL,
                  creditrate=> NULL,
                  trname=> TransName,
                  flags => 0,
                  -- inbalancechar => 0,
                  -- outbalancechar => 0,
                  -- transactionid => null,
                  -- parentid => null,
                  -- tempid => null
                  parentid=> NULL,
                  operationtype=> 15,
                  transactiondate=> TransactionsDate
               );

         --Set Transaction ID
         UPDATE XS_BENEFICIARY
            SET transaction_id = transactionid
          WHERE (BatchID = v_id) AND (id = messages.id);

         --CHILD TRANSACTION
        --NARIMANNNNNNNNNNNNN
				 IF CLIENTACCOUNT = 1
         THEN
            sb_complex_transactions.settransactions (
               v_commisionid,
               v_debitid,
               v_creditid,
               messages.amount,
               messages.amount,
               TransactionsDate
            );
         END IF;
      END LOOP;

      CLOSE creditmessages;

      --APPLY TRANSID                                                  
      UPDATE XS_BATCHS
         SET send = 0
       WHERE id = v_id;
   EXCEPTION
      WHEN OTHERS
      THEN
         BEGIN
            ROLLBACK WORK;
            iconresult := xs_Batchs_ChangeStatus (v_id, 0);
            RAISE_APPLICATION_ERROR (
               -20998,
               SUBSTR (
                     'Error '
                  || TO_CHAR (SQLCODE)
                  || ': '
                  || SQLERRM,
                  1,
                  255
               )
            );
         END;

         COMMIT WORK;
   END;

   PROCEDURE xs_incoming_ChangeStatus (v_id NUMBER, v_status NUMBER)
   IS
   BEGIN
      UPDATE xs_incoming
         SET status = v_status
       WHERE id = v_id;

      COMMIT;
   END;

   PROCEDURE xs_Incoming_upate (
      v_id       IN   xs_incoming.id%TYPE,
      v_acc_id   IN   xs_incoming.rec_client_acc_id%TYPE,
      v_acc_no   IN   xs_incoming.rec_client_acc%TYPE
   )
   IS
      filialid   NUMBER;
   BEGIN
      SELECT filial
        INTO filialid
        FROM ACCOUNT
       WHERE (id = v_acc_id);

      IF    (filialid = 0)
         OR (filialid IS NULL)
      THEN
         filialid := 0;
      END IF;

      UPDATE xs_Incoming
         SET rec_client_acc_id = v_acc_id,
             rec_client_acc = v_acc_no,
             filial = filialid
       WHERE id = v_id;

      COMMIT;
   END;

   
