   PROCEDURE xs_BatchAmount_update (v_id INTEGER)
   IS
      amountsum   NUMBER (22, 2);
   BEGIN
      SELECT SUM (amount)
        INTO amountsum
        FROM XS_BENEFICIARY
       WHERE BatchID = v_id;

      UPDATE XS_BATCHS
