--------------------------------------------------------------------------------
   FUNCTION xs_Batchs_ChangeStatus (v_id NUMBER, v_status NUMBER)
      RETURN INTEGER
   IS
      result         INTEGER;
      v_accept       INTEGER;
      messagecount   INTEGER;
   BEGIN
      --If message no commited
      IF v_status = 0
      THEN
         UPDATE XS_BATCHS
            SET status = v_status
          WHERE id = v_id;

         result := 1;
         COMMIT;
      END IF;

      IF v_status = 1
      THEN
         SELECT COUNT (*)
           INTO v_accept
           FROM XS_BENEFICIARY
          WHERE (status = 1) AND (BatchID = v_id);

         SELECT COUNT (*)
           INTO messagecount
           FROM XS_BENEFICIARY
          WHERE (BatchID = v_id);

         IF (v_accept = messagecount)
         THEN
            UPDATE XS_BATCHS
               SET status = v_status
             WHERE id = v_id;

            result := 1;
            COMMIT;
         ELSE
            result := 0;
         END IF;
      END IF;

      IF v_status = 2
      THEN
         UPDATE XS_BATCHS
            SET status = v_status
          WHERE id = v_id;

         result := 1;
         COMMIT;
      END IF;

      RETURN result;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE xs_transtype_code_change (
      v_id     INTEGER,
      v_name   VARCHAR2,
      v_code   INTEGER
   )
   IS
      fn   INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO fn
        FROM xs_transtype_code
       WHERE code = v_code;

      IF fn = 0
      THEN
         INSERT INTO xs_transtype_code
                     (nameid, NAME, code)
              VALUES (v_id, v_name, v_code);
      ELSE
         UPDATE xs_transtype_code
            SET nameid = v_id,
                NAME = v_name,
                code = v_code;
      END IF;

      COMMIT;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE xs_transtype_name_change (
      v_id     INTEGER,
      v_name   VARCHAR2,
      ins      INTEGER
   )
   IS
   BEGIN
      IF ins = 1
      THEN
         INSERT INTO xs_transtype_name
                     (NAME)
              VALUES (v_name);
      ELSIF ins = 0
      THEN
         BEGIN
            DELETE FROM xs_transtype_code
                  WHERE nameid = v_id;

            DELETE FROM xs_transtype_name
                  WHERE id = v_id;
         END;
      END IF;

      COMMIT;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE xs_config_change (oper INTEGER, v_value VARCHAR2)
   IS
   BEGIN
      IF oper = 1
      THEN
         UPDATE xs_config
            SET ACCOUNT = v_value;
      END IF;

      IF oper = 2
      THEN
         UPDATE xs_config
            SET amount_limit = TO_NUMBER (v_value);
      END IF;

      IF oper = 3
      THEN
         UPDATE xs_config
            SET in_dir = v_value;
      END IF;

      IF oper = 4
      THEN
         UPDATE xs_config
            SET out_dir = v_value;
      END IF;

      IF oper = 5
      THEN
         UPDATE xs_config
            SET archive_dir = v_value;
      END IF;

      COMMIT;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE xs_accounts_add (v_valute INTEGER, v_id INTEGER, v_branchID INTEGER)
   IS
      val_exists   INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO val_exists
        FROM xs_accounts
       WHERE valute = v_valute AND BRANCHID = v_branchID;

      IF val_exists > 0
      THEN
         UPDATE xs_accounts
            SET acc_id = v_id
          WHERE valute = v_valute AND BRANCHID = v_branchID;
      ELSE
         INSERT INTO xs_accounts
                     (acc_id, valute, BRANCHID)
              VALUES (v_id, v_valute, V_BRANCHID);
      END IF;

      COMMIT WORK;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE xs_Config_Commision_Change (v_id INTEGER)
   IS
   BEGIN
      UPDATE XS_CONFIG
         SET CommisionId = v_id;

      COMMIT;
   END;

   
--------------------------------------------------------------------------------
   FUNCTION CheckReadingBatch (v_id INTEGER, v_status INTEGER)
      RETURN INTEGER
   IS
      result         INTEGER;
      noaccept       INTEGER;
      messagecount   INTEGER;
      globalaccept   INTEGER;
   BEGIN
      SELECT COUNT (*)
        INTO noaccept
        FROM xs_beneficiary
       WHERE (NOT (status = v_status)) AND (BatchID = v_id);

      SELECT COUNT (*)
        INTO globalaccept
        FROM xs_beneficiary
       WHERE (transaction_id NOT IN
                          (SELECT id
                             FROM provdoc
                            WHERE dat = GetDefaultDate)
             )
         AND (BatchID = v_id);

      IF  (noaccept = 0) AND (globalaccept = 0)
      THEN
         result := 1;
      ELSE
         result := 0;
      END IF;

      RETURN result;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE BatchToReadyBatchs (v_id INTEGER DEFAULT NULL, SendAll INTEGER)
   IS
      maxamount   NUMBER (22, 2);
   BEGIN
      SELECT Amount_limit
        INTO maxamount
        FROM XS_CONFIG;

      IF SendAll = 0
      THEN
         UPDATE XS_SendingBatchs
            SET send = 0
          WHERE id = v_id;
      ELSIF SendAll = 1
      THEN
         UPDATE XS_SendingBatchs
            SET send = 0;
      END IF;

      COMMIT;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE BatchToSendingBatchs (v_id INTEGER DEFAULT NULL, SendAll INTEGER)
   IS
   BEGIN
      IF SendAll = 0
      THEN
         UPDATE xs_readybatchs
            SET send = 1
          WHERE (id = v_id);
      ELSIF SendAll = 1
      THEN
         UPDATE xs_readybatchs
            SET send = 1;
      END IF;

      COMMIT;
   END;

   
--------------------------------------------------------------------------------
   FUNCTION GetBatchAmount
      RETURN NUMBER
   IS
      result   NUMBER (22, 2);
   BEGIN
      SELECT SUM (amount)
        INTO result
        FROM XS_BATCHS
       WHERE send = 1;

      RETURN result;
   END;

   
--------------------------------------------------------------------------------
   FUNCTION GetDefaultDate
      RETURN DATE
   IS
      v_usebankdate   INTEGER;
      result          DATE;
   BEGIN
      SELECT usebankdate
        INTO v_usebankdate
        FROM xs_config;

      IF v_usebankdate = 1
      THEN
         result := sbop.get_date;
      ELSE
         result := TRUNC (SYSDATE);
      END IF;

      RETURN result;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE BANKM_ADDINFO
   IS
      CURSOR C_BANKM
      IS
         SELECT *
           FROM BANKM;

      R_BANKM    C_BANKM%ROWTYPE;
      TEMPSTR    VARCHAR2 (20);
      TEMPSTR1   VARCHAR2 (20);
   BEGIN
      OPEN C_BANKM;

      LOOP
         FETCH C_BANKM INTO R_BANKM;
         EXIT WHEN C_BANKM%NOTFOUND;
         TEMPSTR1 := TO_CHAR (R_BANKM.KRNO);
         TEMPSTR := CONCAT (
                          '0'
                       || SUBSTR (TEMPSTR1, 0, 5)
                       || '3',
                       SUBSTR (TEMPSTR1, 7, 7)
                    );

         
--  dbms_output.put_line(TEMPSTR);
         UPDATE BANKM
            SET SUBKRNO = TEMPSTR
          WHERE ID = R_BANKM.ID;
      END LOOP;

      CLOSE C_BANKM;
      COMMIT WORK;
   END;

   
--------------------------------------------------------------------------------
   PROCEDURE UpdateBatchReference (
      v_id           INTEGER,
      newreference   xs_batchs.trans_ref%TYPE
   )
   IS
   BEGIN
      UPDATE XS_BATCHS
         SET TRANS_REF = NEWREFERENCE
       WHERE ID = V_ID;

      COMMIT;
   END;
   
END;
